window.__QR["data/core/4.json"]={"v":[["يَـٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُواْ رَبَّكُمُ ٱلَّذِي خَلَقَكُم مِّن نَّفۡسٖ وَٰحِدَةٖ وَخَلَقَ مِنۡهَا زَوۡجَهَا وَبَثَّ مِنۡهُمَا رِجَالٗا كَثِيرٗا وَنِسَآءٗۚ وَٱتَّقُواْ ٱللَّهَ ٱلَّذِي تَسَآءَلُونَ بِهِۦ وَٱلۡأَرۡحَامَۚ إِنَّ ٱللَّهَ كَانَ عَلَيۡكُمۡ رَقِيبٗا","O mankind! Be careful of your duty to your Lord Who created you from a single soul and from it created its mate and from them twain hath spread abroad a multitude of men and women. Be careful of your duty toward Allah in Whom ye claim (your rights) of one another, and toward the wombs (that bare you). Lo! Allah hath been a watcher over you"],["وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ وَلَا تَتَبَدَّلُواْ ٱلۡخَبِيثَ بِٱلطَّيِّبِۖ وَلَا تَأۡكُلُوٓاْ أَمۡوَٰلَهُمۡ إِلَىٰٓ أَمۡوَٰلِكُمۡۚ إِنَّهُۥ كَانَ حُوبٗا كَبِيرٗا","Give unto orphans their wealth. Exchange not the good for the bad (in your management thereof) nor absorb their wealth into your own wealth. Lo! that would be a great sin"],["وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ فَٱنكِحُواْ مَا طَابَ لَكُم مِّنَ ٱلنِّسَآءِ مَثۡنَىٰ وَثُلَٰثَ وَرُبَٰعَۖ فَإِنۡ خِفۡتُمۡ أَلَّا تَعۡدِلُواْ فَوَٰحِدَةً أَوۡ مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۚ ذَٰلِكَ أَدۡنَىٰٓ أَلَّا تَعُولُواْ","And if ye fear that ye will not deal fairly by the orphans, marry of the women, who seem good to you, two or three or four; and if ye fear that ye cannot do justice (to so many) then one (only) or (the captives) that your right hands possess. Thus it is more likely that ye will not do injustice"],["وَءَاتُواْ ٱلنِّسَآءَ صَدُقَٰتِهِنَّ نِحۡلَةٗۚ فَإِن طِبۡنَ لَكُمۡ عَن شَيۡءٖ مِّنۡهُ نَفۡسٗا فَكُلُوهُ هَنِيٓـٔٗا مَّرِيٓـٔٗا","And give unto the women (whom ye marry) free gift of their marriage portions; but if they of their own accord remit unto you a part thereof, then ye are welcome to absorb it (in your wealth)"],["وَلَا تُؤۡتُواْ ٱلسُّفَهَآءَ أَمۡوَٰلَكُمُ ٱلَّتِي جَعَلَ ٱللَّهُ لَكُمۡ قِيَٰمٗا وَٱرۡزُقُوهُمۡ فِيهَا وَٱكۡسُوهُمۡ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا","Give not unto the foolish (what is in) your (keeping of their) wealth, which Allah hath given you to maintain; but feed and clothe them from it, and speak kindly unto them"],["وَٱبۡتَلُواْ ٱلۡيَتَٰمَىٰ حَتَّىٰٓ إِذَا بَلَغُواْ ٱلنِّكَاحَ فَإِنۡ ءَانَسۡتُم مِّنۡهُمۡ رُشۡدٗا فَٱدۡفَعُوٓاْ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡۖ وَلَا تَأۡكُلُوهَآ إِسۡرَافٗا وَبِدَارًا أَن يَكۡبَرُواْۚ وَمَن كَانَ غَنِيّٗا فَلۡيَسۡتَعۡفِفۡۖ وَمَن كَانَ فَقِيرٗا فَلۡيَأۡكُلۡ بِٱلۡمَعۡرُوفِۚ فَإِذَا دَفَعۡتُمۡ إِلَيۡهِمۡ أَمۡوَٰلَهُمۡ فَأَشۡهِدُواْ عَلَيۡهِمۡۚ وَكَفَىٰ بِٱللَّهِ حَسِيبٗا","Prove orphans till they reach the marriageable age; then, if ye find them of sound judgment, deliver over unto them their fortune; and devour it not by squandering and in haste lest they should grow up Whoso (of the guardians) is rich, let him abstain generously (from taking of the property of orphans); and whoso is poor let him take thereof in reason (for his guardianship). And when ye deliver up their fortune unto orphans, have (the transaction) witnessed in their presence. Allah sufficeth as a Reckoner"],["لِّلرِّجَالِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَ مِمَّا قَلَّ مِنۡهُ أَوۡ كَثُرَۚ نَصِيبٗا مَّفۡرُوضٗا","Unto the men (of a family) belongeth a share of that which parents and near kindred leave, and unto the women a share of that which parents and near kindred leave, whether it be little or much - a legal share"],["وَإِذَا حَضَرَ ٱلۡقِسۡمَةَ أُوْلُواْ ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينُ فَٱرۡزُقُوهُم مِّنۡهُ وَقُولُواْ لَهُمۡ قَوۡلٗا مَّعۡرُوفٗا","And when kinsfolk and orphans and the needy are present at the division (of the heritage), bestow on them therefrom and speak kindly unto them"],["وَلۡيَخۡشَ ٱلَّذِينَ لَوۡ تَرَكُواْ مِنۡ خَلۡفِهِمۡ ذُرِّيَّةٗ ضِعَٰفًا خَافُواْ عَلَيۡهِمۡ فَلۡيَتَّقُواْ ٱللَّهَ وَلۡيَقُولُواْ قَوۡلٗا سَدِيدًا","And let those fear (in their behaviour toward orphans) who if they left behind them weak offspring would be afraid for them. So let them mind their duty to Allah, and speak justly"],["إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ ظُلۡمًا إِنَّمَا يَأۡكُلُونَ فِي بُطُونِهِمۡ نَارٗاۖ وَسَيَصۡلَوۡنَ سَعِيرٗا","Lo! Those who devour the wealth of orphans wrongfully, they do but swallow fire into their bellies, and they will be exposed to burning flame"],["يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ لِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۚ فَإِن كُنَّ نِسَآءٗ فَوۡقَ ٱثۡنَتَيۡنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَۖ وَإِن كَانَتۡ وَٰحِدَةٗ فَلَهَا ٱلنِّصۡفُۚ وَلِأَبَوَيۡهِ لِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُ مِمَّا تَرَكَ إِن كَانَ لَهُۥ وَلَدٞۚ فَإِن لَّمۡ يَكُن لَّهُۥ وَلَدٞ وَوَرِثَهُۥٓ أَبَوَاهُ فَلِأُمِّهِ ٱلثُّلُثُۚ فَإِن كَانَ لَهُۥٓ إِخۡوَةٞ فَلِأُمِّهِ ٱلسُّدُسُۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِي بِهَآ أَوۡ دَيۡنٍۗ ءَابَآؤُكُمۡ وَأَبۡنَآؤُكُمۡ لَا تَدۡرُونَ أَيُّهُمۡ أَقۡرَبُ لَكُمۡ نَفۡعٗاۚ فَرِيضَةٗ مِّنَ ٱللَّهِۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","Allah chargeth you concerning (the provision for) your children: to the male the equivalent of the portion of two females, and if there be women more than two, then theirs is two-thirds of the inheritance, and if there be one (only) then the half. And to each of his parents a sixth of the inheritance, if he have a son; and if he have no son and his parents are his heirs, then to his mother appertaineth the third; and if he have brethren, then to his mother appertaineth the sixth, after any legacy he may have bequeathed, or debt (hath been paid). Your parents and your children: Ye know not which of them is nearer unto you in usefulness. It is an injunction from Allah. Lo! Allah is Knower, Wise"],["۞وَلَكُمۡ نِصۡفُ مَا تَرَكَ أَزۡوَٰجُكُمۡ إِن لَّمۡ يَكُن لَّهُنَّ وَلَدٞۚ فَإِن كَانَ لَهُنَّ وَلَدٞ فَلَكُمُ ٱلرُّبُعُ مِمَّا تَرَكۡنَۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصِينَ بِهَآ أَوۡ دَيۡنٖۚ وَلَهُنَّ ٱلرُّبُعُ مِمَّا تَرَكۡتُمۡ إِن لَّمۡ يَكُن لَّكُمۡ وَلَدٞۚ فَإِن كَانَ لَكُمۡ وَلَدٞ فَلَهُنَّ ٱلثُّمُنُ مِمَّا تَرَكۡتُمۚ مِّنۢ بَعۡدِ وَصِيَّةٖ تُوصُونَ بِهَآ أَوۡ دَيۡنٖۗ وَإِن كَانَ رَجُلٞ يُورَثُ كَلَٰلَةً أَوِ ٱمۡرَأَةٞ وَلَهُۥٓ أَخٌ أَوۡ أُخۡتٞ فَلِكُلِّ وَٰحِدٖ مِّنۡهُمَا ٱلسُّدُسُۚ فَإِن كَانُوٓاْ أَكۡثَرَ مِن ذَٰلِكَ فَهُمۡ شُرَكَآءُ فِي ٱلثُّلُثِۚ مِنۢ بَعۡدِ وَصِيَّةٖ يُوصَىٰ بِهَآ أَوۡ دَيۡنٍ غَيۡرَ مُضَآرّٖۚ وَصِيَّةٗ مِّنَ ٱللَّهِۗ وَٱللَّهُ عَلِيمٌ حَلِيمٞ","And unto you belongeth a half of that which your wives leave, if they have no child; but if they have a child then unto you the fourth of that which they leave, after any legacy they may have bequeathed, or debt (they may have contracted, hath been paid). And unto them belongeth the fourth of that which ye leave if ye have no child, but if ye have a child then the eighth of that which ye leave, after any legacy ye may have bequeathed, or debt (ye may have contracted, hath been paid). And if a man or a woman have a distant heir (having left neither parent nor child), and he (or she) have a brother or a sister (only on the mother's side) then to each of them twain (the brother and the sister) the sixth, and if they be more than two, then they shall be sharers in the third, after any legacy that may have been bequeathed or debt (contracted) not injuring (the heirs by willing away more than a third of the heritage) hath been paid. A commandment from Allah. Allah is Knower, Indulgent"],["تِلۡكَ حُدُودُ ٱللَّهِۚ وَمَن يُطِعِ ٱللَّهَ وَرَسُولَهُۥ يُدۡخِلۡهُ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَاۚ وَذَٰلِكَ ٱلۡفَوۡزُ ٱلۡعَظِيمُ","These are the limits (imposed by) Allah. Whoso obeyeth Allah and His messenger, He will make him enter Gardens underneath which rivers flow, where such will dwell for ever. That will be the great success"],["وَمَن يَعۡصِ ٱللَّهَ وَرَسُولَهُۥ وَيَتَعَدَّ حُدُودَهُۥ يُدۡخِلۡهُ نَارًا خَٰلِدٗا فِيهَا وَلَهُۥ عَذَابٞ مُّهِينٞ","And whoso disobeyeth Allah and His messenger and transgresseth His limits, He will make him enter Fire, where he will dwell for ever; his will be a shameful doom"],["وَٱلَّـٰتِي يَأۡتِينَ ٱلۡفَٰحِشَةَ مِن نِّسَآئِكُمۡ فَٱسۡتَشۡهِدُواْ عَلَيۡهِنَّ أَرۡبَعَةٗ مِّنكُمۡۖ فَإِن شَهِدُواْ فَأَمۡسِكُوهُنَّ فِي ٱلۡبُيُوتِ حَتَّىٰ يَتَوَفَّىٰهُنَّ ٱلۡمَوۡتُ أَوۡ يَجۡعَلَ ٱللَّهُ لَهُنَّ سَبِيلٗا","As for those of your women who are guilty of lewdness, call to witness four of you against them. And if they testify (to the truth of the allegation) then confine them to the houses until death take them or (until) Allah appoint for them a way (through new legislation)"],["وَٱلَّذَانِ يَأۡتِيَٰنِهَا مِنكُمۡ فَـَٔاذُوهُمَاۖ فَإِن تَابَا وَأَصۡلَحَا فَأَعۡرِضُواْ عَنۡهُمَآۗ إِنَّ ٱللَّهَ كَانَ تَوَّابٗا رَّحِيمًا","And as for the two of you who are guilty thereof, punish them both. And if they repent and improve, then let them be. Lo! Allah is ever relenting, Merciful"],["إِنَّمَا ٱلتَّوۡبَةُ عَلَى ٱللَّهِ لِلَّذِينَ يَعۡمَلُونَ ٱلسُّوٓءَ بِجَهَٰلَةٖ ثُمَّ يَتُوبُونَ مِن قَرِيبٖ فَأُوْلَـٰٓئِكَ يَتُوبُ ٱللَّهُ عَلَيۡهِمۡۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","Forgiveness is only incumbent on Allah toward those who do evil in ignorance (and) then turn quickly (in repentance) to Allah. These are they toward whom Allah relenteth. Allah is ever Knower, Wise"],["وَلَيۡسَتِ ٱلتَّوۡبَةُ لِلَّذِينَ يَعۡمَلُونَ ٱلسَّيِّـَٔاتِ حَتَّىٰٓ إِذَا حَضَرَ أَحَدَهُمُ ٱلۡمَوۡتُ قَالَ إِنِّي تُبۡتُ ٱلۡـَٰٔنَ وَلَا ٱلَّذِينَ يَمُوتُونَ وَهُمۡ كُفَّارٌۚ أُوْلَـٰٓئِكَ أَعۡتَدۡنَا لَهُمۡ عَذَابًا أَلِيمٗا","The forgiveness is not for those who do ill-deeds until, when death attendeth upon one of them, he saith: Lo! I repent now; nor yet for those who die while they are disbelievers. For such We have prepared a painful doom"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا يَحِلُّ لَكُمۡ أَن تَرِثُواْ ٱلنِّسَآءَ كَرۡهٗاۖ وَلَا تَعۡضُلُوهُنَّ لِتَذۡهَبُواْ بِبَعۡضِ مَآ ءَاتَيۡتُمُوهُنَّ إِلَّآ أَن يَأۡتِينَ بِفَٰحِشَةٖ مُّبَيِّنَةٖۚ وَعَاشِرُوهُنَّ بِٱلۡمَعۡرُوفِۚ فَإِن كَرِهۡتُمُوهُنَّ فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا","O ye who believe! It is not lawful for you forcibly to inherit the women (of your deceased kinsmen), nor (that) ye should put constraint upon them that ye may take away a part of that which ye have given them, unless they be guilty of flagrant lewdness. But consort with them in kindness, for if ye hate them it may happen that ye hate a thing wherein Allah hath placed much good"],["وَإِنۡ أَرَدتُّمُ ٱسۡتِبۡدَالَ زَوۡجٖ مَّكَانَ زَوۡجٖ وَءَاتَيۡتُمۡ إِحۡدَىٰهُنَّ قِنطَارٗا فَلَا تَأۡخُذُواْ مِنۡهُ شَيۡـًٔاۚ أَتَأۡخُذُونَهُۥ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا","And if ye wish to exchange one wife for another and ye have given unto one of them a sum of money (however great), take nothing from it. Would ye take it by the way of calumny and open wrong"],["وَكَيۡفَ تَأۡخُذُونَهُۥ وَقَدۡ أَفۡضَىٰ بَعۡضُكُمۡ إِلَىٰ بَعۡضٖ وَأَخَذۡنَ مِنكُم مِّيثَٰقًا غَلِيظٗا","How can ye take it (back) after one of you hath gone in unto the other, and they have taken a strong pledge from you"],["وَلَا تَنكِحُواْ مَا نَكَحَ ءَابَآؤُكُم مِّنَ ٱلنِّسَآءِ إِلَّا مَا قَدۡ سَلَفَۚ إِنَّهُۥ كَانَ فَٰحِشَةٗ وَمَقۡتٗا وَسَآءَ سَبِيلًا","And marry not those women whom your fathers married, except what hath already happened (of that nature) in the past. Lo! it was ever lewdness and abomination, and an evil way"],["حُرِّمَتۡ عَلَيۡكُمۡ أُمَّهَٰتُكُمۡ وَبَنَاتُكُمۡ وَأَخَوَٰتُكُمۡ وَعَمَّـٰتُكُمۡ وَخَٰلَٰتُكُمۡ وَبَنَاتُ ٱلۡأَخِ وَبَنَاتُ ٱلۡأُخۡتِ وَأُمَّهَٰتُكُمُ ٱلَّـٰتِيٓ أَرۡضَعۡنَكُمۡ وَأَخَوَٰتُكُم مِّنَ ٱلرَّضَٰعَةِ وَأُمَّهَٰتُ نِسَآئِكُمۡ وَرَبَـٰٓئِبُكُمُ ٱلَّـٰتِي فِي حُجُورِكُم مِّن نِّسَآئِكُمُ ٱلَّـٰتِي دَخَلۡتُم بِهِنَّ فَإِن لَّمۡ تَكُونُواْ دَخَلۡتُم بِهِنَّ فَلَا جُنَاحَ عَلَيۡكُمۡ وَحَلَـٰٓئِلُ أَبۡنَآئِكُمُ ٱلَّذِينَ مِنۡ أَصۡلَٰبِكُمۡ وَأَن تَجۡمَعُواْ بَيۡنَ ٱلۡأُخۡتَيۡنِ إِلَّا مَا قَدۡ سَلَفَۗ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","Forbidden unto you are your mothers, and your daughters, and your sisters, and your father's sisters, and your mother's sisters, and your brother's daughters and your sister's daughters, and your foster-mothers, and your foster-sisters, and your mothers-in-law, and your step-daughters who are under your protection (born) of your women unto whom ye have gone in - but if ye have not gone in unto them, then it is no sin for you (to marry their daughters) - and the wives of your sons who (spring) from your own loins. And (it is forbidden unto you) that ye should have two sisters together, except what hath already happened (of that nature) in the past. Lo! Allah is ever Forgiving, Merciful"],["۞وَٱلۡمُحۡصَنَٰتُ مِنَ ٱلنِّسَآءِ إِلَّا مَا مَلَكَتۡ أَيۡمَٰنُكُمۡۖ كِتَٰبَ ٱللَّهِ عَلَيۡكُمۡۚ وَأُحِلَّ لَكُم مَّا وَرَآءَ ذَٰلِكُمۡ أَن تَبۡتَغُواْ بِأَمۡوَٰلِكُم مُّحۡصِنِينَ غَيۡرَ مُسَٰفِحِينَۚ فَمَا ٱسۡتَمۡتَعۡتُم بِهِۦ مِنۡهُنَّ فَـَٔاتُوهُنَّ أُجُورَهُنَّ فَرِيضَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ فِيمَا تَرَٰضَيۡتُم بِهِۦ مِنۢ بَعۡدِ ٱلۡفَرِيضَةِۚ إِنَّ ٱللَّهَ كَانَ عَلِيمًا حَكِيمٗا","And all married women (are forbidden unto you) save those (captives) whom your right hands possess. It is a decree of Allah for you. Lawful unto you are all beyond those mentioned, so that ye seek them with your wealth in honest wedlock, not debauchery. And those of whom ye seek content (by marrying them), give unto them their portions as a duty. And there is no sin for you in what ye do by mutual agreement after the duty (hath been done). Lo! Allah is ever Knower, Wise"],["وَمَن لَّمۡ يَسۡتَطِعۡ مِنكُمۡ طَوۡلًا أَن يَنكِحَ ٱلۡمُحۡصَنَٰتِ ٱلۡمُؤۡمِنَٰتِ فَمِن مَّا مَلَكَتۡ أَيۡمَٰنُكُم مِّن فَتَيَٰتِكُمُ ٱلۡمُؤۡمِنَٰتِۚ وَٱللَّهُ أَعۡلَمُ بِإِيمَٰنِكُمۚ بَعۡضُكُم مِّنۢ بَعۡضٖۚ فَٱنكِحُوهُنَّ بِإِذۡنِ أَهۡلِهِنَّ وَءَاتُوهُنَّ أُجُورَهُنَّ بِٱلۡمَعۡرُوفِ مُحۡصَنَٰتٍ غَيۡرَ مُسَٰفِحَٰتٖ وَلَا مُتَّخِذَٰتِ أَخۡدَانٖۚ فَإِذَآ أُحۡصِنَّ فَإِنۡ أَتَيۡنَ بِفَٰحِشَةٖ فَعَلَيۡهِنَّ نِصۡفُ مَا عَلَى ٱلۡمُحۡصَنَٰتِ مِنَ ٱلۡعَذَابِۚ ذَٰلِكَ لِمَنۡ خَشِيَ ٱلۡعَنَتَ مِنكُمۡۚ وَأَن تَصۡبِرُواْ خَيۡرٞ لَّكُمۡۗ وَٱللَّهُ غَفُورٞ رَّحِيمٞ","And whoso is not able to afford to marry free, believing women, let them marry from the believing maids whom your right hands possess. Allah knoweth best (concerning) your faith. Ye (proceed) one from another; so wed them by permission of their folk, and give unto them their portions in kindness, they being honest, not debauched nor of loose conduct. And if when they are honourably married they commit lewdness they shall incur the half of the punishment (prescribed) for free women (in that case). This is for him among you who feareth to commit sin. But to have patience would be better for you. Allah is Forgiving, Merciful"],["يُرِيدُ ٱللَّهُ لِيُبَيِّنَ لَكُمۡ وَيَهۡدِيَكُمۡ سُنَنَ ٱلَّذِينَ مِن قَبۡلِكُمۡ وَيَتُوبَ عَلَيۡكُمۡۗ وَٱللَّهُ عَلِيمٌ حَكِيمٞ","Allah would explain to you and guide you by the examples of those who were before you, and would turn to you in mercy. Allah is Knower, Wise"],["وَٱللَّهُ يُرِيدُ أَن يَتُوبَ عَلَيۡكُمۡ وَيُرِيدُ ٱلَّذِينَ يَتَّبِعُونَ ٱلشَّهَوَٰتِ أَن تَمِيلُواْ مَيۡلًا عَظِيمٗا","And Allah would turn to you in mercy; but those who follow vain desires would have you go tremendously astray"],["يُرِيدُ ٱللَّهُ أَن يُخَفِّفَ عَنكُمۡۚ وَخُلِقَ ٱلۡإِنسَٰنُ ضَعِيفٗا","Allah would make the burden light for you, for man was created weak"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَأۡكُلُوٓاْ أَمۡوَٰلَكُم بَيۡنَكُم بِٱلۡبَٰطِلِ إِلَّآ أَن تَكُونَ تِجَٰرَةً عَن تَرَاضٖ مِّنكُمۡۚ وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ إِنَّ ٱللَّهَ كَانَ بِكُمۡ رَحِيمٗا","O ye who believe! Squander not your wealth among yourselves in vanity, except it be a trade by mutual consent, and kill not one another. Lo! Allah is ever Merciful unto you"],["وَمَن يَفۡعَلۡ ذَٰلِكَ عُدۡوَٰنٗا وَظُلۡمٗا فَسَوۡفَ نُصۡلِيهِ نَارٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرًا","Whoso doeth that through aggression and injustice, we shall cast him into Fire, and that is ever easy for Allah"],["إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا","If ye avoid the great (things) which ye are forbidden, We will remit from you your evil deeds and make you enter at a noble gate"],["وَلَا تَتَمَنَّوۡاْ مَا فَضَّلَ ٱللَّهُ بِهِۦ بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ لِّلرِّجَالِ نَصِيبٞ مِّمَّا ٱكۡتَسَبُواْۖ وَلِلنِّسَآءِ نَصِيبٞ مِّمَّا ٱكۡتَسَبۡنَۚ وَسۡـَٔلُواْ ٱللَّهَ مِن فَضۡلِهِۦٓۚ إِنَّ ٱللَّهَ كَانَ بِكُلِّ شَيۡءٍ عَلِيمٗا","And covet not the thing in which Allah hath made some of you excel others. Unto men a fortune from that which they have earned, and unto women a fortune from that which they have earned. (Envy not one another) but ask Allah of His bounty. Lo! Allah is ever Knower of all things"],["وَلِكُلّٖ جَعَلۡنَا مَوَٰلِيَ مِمَّا تَرَكَ ٱلۡوَٰلِدَانِ وَٱلۡأَقۡرَبُونَۚ وَٱلَّذِينَ عَقَدَتۡ أَيۡمَٰنُكُمۡ فَـَٔاتُوهُمۡ نَصِيبَهُمۡۚ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٖ شَهِيدًا","And unto each We have appointed heirs of that which parents and near kindred leave; and as for those with whom your right hands have made a covenant, give them their due. Lo! Allah is ever Witness over all things"],["ٱلرِّجَالُ قَوَّـٰمُونَ عَلَى ٱلنِّسَآءِ بِمَا فَضَّلَ ٱللَّهُ بَعۡضَهُمۡ عَلَىٰ بَعۡضٖ وَبِمَآ أَنفَقُواْ مِنۡ أَمۡوَٰلِهِمۡۚ فَٱلصَّـٰلِحَٰتُ قَٰنِتَٰتٌ حَٰفِظَٰتٞ لِّلۡغَيۡبِ بِمَا حَفِظَ ٱللَّهُۚ وَٱلَّـٰتِي تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَٱهۡجُرُوهُنَّ فِي ٱلۡمَضَاجِعِ وَٱضۡرِبُوهُنَّۖ فَإِنۡ أَطَعۡنَكُمۡ فَلَا تَبۡغُواْ عَلَيۡهِنَّ سَبِيلًاۗ إِنَّ ٱللَّهَ كَانَ عَلِيّٗا كَبِيرٗا","Men are in charge of women, because Allah hath made the one of them to excel the other, and because they spend of their property (for the support of women). So good women are the obedient, guarding in secret that which Allah hath guarded. As for those from whom ye fear rebellion, admonish them and banish them to beds apart, and scourge them. Then if they obey you, seek not a way against them. Lo! Allah is ever High, Exalted, Great"],["وَإِنۡ خِفۡتُمۡ شِقَاقَ بَيۡنِهِمَا فَٱبۡعَثُواْ حَكَمٗا مِّنۡ أَهۡلِهِۦ وَحَكَمٗا مِّنۡ أَهۡلِهَآ إِن يُرِيدَآ إِصۡلَٰحٗا يُوَفِّقِ ٱللَّهُ بَيۡنَهُمَآۗ إِنَّ ٱللَّهَ كَانَ عَلِيمًا خَبِيرٗا","And if ye fear a breach between them twain (the man and wife), appoint an arbiter from his folk and an arbiter from her folk. If they desire amendment Allah will make them of one mind. Lo! Allah is ever Knower, Aware"],["۞وَٱعۡبُدُواْ ٱللَّهَ وَلَا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗا وَبِذِي ٱلۡقُرۡبَىٰ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱلۡجَارِ ذِي ٱلۡقُرۡبَىٰ وَٱلۡجَارِ ٱلۡجُنُبِ وَٱلصَّاحِبِ بِٱلۡجَنۢبِ وَٱبۡنِ ٱلسَّبِيلِ وَمَا مَلَكَتۡ أَيۡمَٰنُكُمۡۗ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ مُخۡتَالٗا فَخُورًا","And serve Allah. Ascribe no thing as partner unto Him. (Show) kindness unto parents, and unto near kindred, and orphans, and the needy, and unto the neighbour who is of kin (unto you) and the neighbour who is not of kin, and the fellow-traveller and the wayfarer and (the slaves) whom your right hands possess. Lo! Allah loveth not such as are proud and boastful"],["ٱلَّذِينَ يَبۡخَلُونَ وَيَأۡمُرُونَ ٱلنَّاسَ بِٱلۡبُخۡلِ وَيَكۡتُمُونَ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۗ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","Who hoard their wealth and enjoin avarice on others, and hide that which Allah hath bestowed upon them of His bounty. For disbelievers We prepare a shameful doom"],["وَٱلَّذِينَ يُنفِقُونَ أَمۡوَٰلَهُمۡ رِئَآءَ ٱلنَّاسِ وَلَا يُؤۡمِنُونَ بِٱللَّهِ وَلَا بِٱلۡيَوۡمِ ٱلۡأٓخِرِۗ وَمَن يَكُنِ ٱلشَّيۡطَٰنُ لَهُۥ قَرِينٗا فَسَآءَ قَرِينٗا","And (also) those who spend their wealth in order to be seen of men, and believe not in Allah nor the Last Day. Whoso taketh Satan for a comrade, a bad comrade hath he"],["وَمَاذَا عَلَيۡهِمۡ لَوۡ ءَامَنُواْ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ وَأَنفَقُواْ مِمَّا رَزَقَهُمُ ٱللَّهُۚ وَكَانَ ٱللَّهُ بِهِمۡ عَلِيمًا","What have they (to fear) if they believe in Allah and the Last Day and spend (aright) of that which Allah hath bestowed upon them, when Allah is ever Aware of them (and all they do)"],["إِنَّ ٱللَّهَ لَا يَظۡلِمُ مِثۡقَالَ ذَرَّةٖۖ وَإِن تَكُ حَسَنَةٗ يُضَٰعِفۡهَا وَيُؤۡتِ مِن لَّدُنۡهُ أَجۡرًا عَظِيمٗا","Lo! Allah wrongeth not even of the weight of an ant; and if there is a good deed, He will double it and will give (the doer) from His presence an immense reward"],["فَكَيۡفَ إِذَا جِئۡنَا مِن كُلِّ أُمَّةِۭ بِشَهِيدٖ وَجِئۡنَا بِكَ عَلَىٰ هَـٰٓؤُلَآءِ شَهِيدٗا","But how (will it be with them) when We bring of every people a witness, and We bring thee (O Muhammad) a witness against these"],["يَوۡمَئِذٖ يَوَدُّ ٱلَّذِينَ كَفَرُواْ وَعَصَوُاْ ٱلرَّسُولَ لَوۡ تُسَوَّىٰ بِهِمُ ٱلۡأَرۡضُ وَلَا يَكۡتُمُونَ ٱللَّهَ حَدِيثٗا","On that day those who disbelieved and disobeyed the messenger will wish that they were level with the ground, and they can hide no fact from Allah"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ وَلَا جُنُبًا إِلَّا عَابِرِي سَبِيلٍ حَتَّىٰ تَغۡتَسِلُواْۚ وَإِن كُنتُم مَّرۡضَىٰٓ أَوۡ عَلَىٰ سَفَرٍ أَوۡ جَآءَ أَحَدٞ مِّنكُم مِّنَ ٱلۡغَآئِطِ أَوۡ لَٰمَسۡتُمُ ٱلنِّسَآءَ فَلَمۡ تَجِدُواْ مَآءٗ فَتَيَمَّمُواْ صَعِيدٗا طَيِّبٗا فَٱمۡسَحُواْ بِوُجُوهِكُمۡ وَأَيۡدِيكُمۡۗ إِنَّ ٱللَّهَ كَانَ عَفُوًّا غَفُورًا","O ye who believe! Draw not near unto prayer when ye are drunken, till ye know that which ye utter, nor when ye are polluted, save when journeying upon the road, till ye have bathed. And if ye be ill, or on a journey, or one of you cometh from the closet, or ye have touched women, and ye find not water, then go to high clean soil and rub your faces and your hands (therewith). Lo! Allah is Benign, Forgiving"],["أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يَشۡتَرُونَ ٱلضَّلَٰلَةَ وَيُرِيدُونَ أَن تَضِلُّواْ ٱلسَّبِيلَ","Seest thou not those unto whom a portion of the Scripture hath been given, how they purchase error, and seek to make you (Muslims) err from the right way"],["وَٱللَّهُ أَعۡلَمُ بِأَعۡدَآئِكُمۡۚ وَكَفَىٰ بِٱللَّهِ وَلِيّٗا وَكَفَىٰ بِٱللَّهِ نَصِيرٗا","Allah knoweth best (who are) your enemies. Allah is sufficient as a Guardian, and Allah is sufficient as a Supporter"],["مِّنَ ٱلَّذِينَ هَادُواْ يُحَرِّفُونَ ٱلۡكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعۡنَا وَعَصَيۡنَا وَٱسۡمَعۡ غَيۡرَ مُسۡمَعٖ وَرَٰعِنَا لَيَّۢا بِأَلۡسِنَتِهِمۡ وَطَعۡنٗا فِي ٱلدِّينِۚ وَلَوۡ أَنَّهُمۡ قَالُواْ سَمِعۡنَا وَأَطَعۡنَا وَٱسۡمَعۡ وَٱنظُرۡنَا لَكَانَ خَيۡرٗا لَّهُمۡ وَأَقۡوَمَ وَلَٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا","Some of those who are Jews change words from their context and say: \"We hear and disobey; hear thou as one who heareth not\" and \"Listen to us!\" distorting with their tongues and slandering religion. If they had said: \"We hear and we obey: hear thou, and look at us\" it had been better for them, and more upright. But Allah hath cursed them for their disbelief, so they believe not, save a few"],["يَـٰٓأَيُّهَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ ءَامِنُواْ بِمَا نَزَّلۡنَا مُصَدِّقٗا لِّمَا مَعَكُم مِّن قَبۡلِ أَن نَّطۡمِسَ وُجُوهٗا فَنَرُدَّهَا عَلَىٰٓ أَدۡبَارِهَآ أَوۡ نَلۡعَنَهُمۡ كَمَا لَعَنَّآ أَصۡحَٰبَ ٱلسَّبۡتِۚ وَكَانَ أَمۡرُ ٱللَّهِ مَفۡعُولًا","O ye unto whom the Scripture hath been given! Believe in what We have revealed confirming that which ye possess, before We destroy countenances so as to confound them, or curse them as We cursed the Sabbath-breakers (of old time). The commandment of Allah is always executed"],["إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدِ ٱفۡتَرَىٰٓ إِثۡمًا عَظِيمًا","Lo! Allah forgiveth not that a partner should be ascribed unto Him. He forgiveth (all) save that to whom He will. Whoso ascribeth partners to Allah, he hath indeed invented a tremendous sin"],["أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يُزَكُّونَ أَنفُسَهُمۚ بَلِ ٱللَّهُ يُزَكِّي مَن يَشَآءُ وَلَا يُظۡلَمُونَ فَتِيلًا","Hast thou not seen those who praise themselves for purity? Nay, Allah purifieth whom He will, and they will not be wronged even the hair upon a date-stone"],["ٱنظُرۡ كَيۡفَ يَفۡتَرُونَ عَلَى ٱللَّهِ ٱلۡكَذِبَۖ وَكَفَىٰ بِهِۦٓ إِثۡمٗا مُّبِينًا","See, how they invent lies about Allah! That of itself is flagrant sin"],["أَلَمۡ تَرَ إِلَى ٱلَّذِينَ أُوتُواْ نَصِيبٗا مِّنَ ٱلۡكِتَٰبِ يُؤۡمِنُونَ بِٱلۡجِبۡتِ وَٱلطَّـٰغُوتِ وَيَقُولُونَ لِلَّذِينَ كَفَرُواْ هَـٰٓؤُلَآءِ أَهۡدَىٰ مِنَ ٱلَّذِينَ ءَامَنُواْ سَبِيلًا","Hast thou not seen those unto whom a portion of the Scripture hath been given, how they believe in idols and false deities, and how they say of those (idolaters) who disbelieve: \"These are more rightly guided than those who believe"],["أُوْلَـٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُۖ وَمَن يَلۡعَنِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ نَصِيرًا","Those are they whom Allah hath cursed, and he whom Allah hath cursed, thou (O Muhammad) wilt find for him no helper"],["أَمۡ لَهُمۡ نَصِيبٞ مِّنَ ٱلۡمُلۡكِ فَإِذٗا لَّا يُؤۡتُونَ ٱلنَّاسَ نَقِيرًا","Or have they even a share in the Sovereignty? Then in that case, they would not give mankind even the speck on a date-stone"],["أَمۡ يَحۡسُدُونَ ٱلنَّاسَ عَلَىٰ مَآ ءَاتَىٰهُمُ ٱللَّهُ مِن فَضۡلِهِۦۖ فَقَدۡ ءَاتَيۡنَآ ءَالَ إِبۡرَٰهِيمَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَءَاتَيۡنَٰهُم مُّلۡكًا عَظِيمٗا","Or are they jealous of mankind because of that which Allah of His bounty hath bestowed upon them? For We bestowed upon the house of Abraham (of old) the Scripture and wisdom, and We bestowed on them a mighty kingdom"],["فَمِنۡهُم مَّنۡ ءَامَنَ بِهِۦ وَمِنۡهُم مَّن صَدَّ عَنۡهُۚ وَكَفَىٰ بِجَهَنَّمَ سَعِيرًا","And of them were (some) who believed therein and of them were (some) who turned away from it. Hell is sufficient for (their) burning"],["إِنَّ ٱلَّذِينَ كَفَرُواْ بِـَٔايَٰتِنَا سَوۡفَ نُصۡلِيهِمۡ نَارٗا كُلَّمَا نَضِجَتۡ جُلُودُهُم بَدَّلۡنَٰهُمۡ جُلُودًا غَيۡرَهَا لِيَذُوقُواْ ٱلۡعَذَابَۗ إِنَّ ٱللَّهَ كَانَ عَزِيزًا حَكِيمٗا","Lo! Those who disbelieve Our revelations, We shall expose them to the Fire. As often as their skins are consumed We shall exchange them for fresh skins that they may taste the torment. Lo! Allah is ever Mighty, Wise"],["وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ لَّهُمۡ فِيهَآ أَزۡوَٰجٞ مُّطَهَّرَةٞۖ وَنُدۡخِلُهُمۡ ظِلّٗا ظَلِيلًا","And as for those who believe and do good works, We shall make them enter Gardens underneath which rivers flow - to dwell therein for ever; there for them are pure companions - and We shall make them enter plenteous shade"],["۞إِنَّ ٱللَّهَ يَأۡمُرُكُمۡ أَن تُؤَدُّواْ ٱلۡأَمَٰنَٰتِ إِلَىٰٓ أَهۡلِهَا وَإِذَا حَكَمۡتُم بَيۡنَ ٱلنَّاسِ أَن تَحۡكُمُواْ بِٱلۡعَدۡلِۚ إِنَّ ٱللَّهَ نِعِمَّا يَعِظُكُم بِهِۦٓۗ إِنَّ ٱللَّهَ كَانَ سَمِيعَۢا بَصِيرٗا","Lo! Allah commandeth you that ye restore deposits to their owners, and, if ye judge between mankind, that ye judge justly. Lo! comely is this which Allah admonisheth you. Lo! Allah is ever Hearer, Seer"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ أَطِيعُواْ ٱللَّهَ وَأَطِيعُواْ ٱلرَّسُولَ وَأُوْلِي ٱلۡأَمۡرِ مِنكُمۡۖ فَإِن تَنَٰزَعۡتُمۡ فِي شَيۡءٖ فَرُدُّوهُ إِلَى ٱللَّهِ وَٱلرَّسُولِ إِن كُنتُمۡ تُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِۚ ذَٰلِكَ خَيۡرٞ وَأَحۡسَنُ تَأۡوِيلًا","O ye who believe! Obey Allah, and obey the messenger and those of you who are in authority; and if ye have a dispute concerning any matter, refer it to Allah and the messenger if ye are (in truth) believers in Allah and the Last Day. That is better and more seemly in the end"],["أَلَمۡ تَرَ إِلَى ٱلَّذِينَ يَزۡعُمُونَ أَنَّهُمۡ ءَامَنُواْ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَ يُرِيدُونَ أَن يَتَحَاكَمُوٓاْ إِلَى ٱلطَّـٰغُوتِ وَقَدۡ أُمِرُوٓاْ أَن يَكۡفُرُواْ بِهِۦۖ وَيُرِيدُ ٱلشَّيۡطَٰنُ أَن يُضِلَّهُمۡ ضَلَٰلَۢا بَعِيدٗا","Hast thou not seen those who pretend that they believe in that which is revealed unto thee and that which was revealed before thee, how they would go for judgment (in their disputes) to false deities when they have been ordered to abjure them? Satan would mislead them far astray"],["وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ إِلَىٰ مَآ أَنزَلَ ٱللَّهُ وَإِلَى ٱلرَّسُولِ رَأَيۡتَ ٱلۡمُنَٰفِقِينَ يَصُدُّونَ عَنكَ صُدُودٗا","And when it is said unto them: Come unto that which Allah hath revealed and unto the messenger, thou seest the hypocrites turn from thee with aversion"],["فَكَيۡفَ إِذَآ أَصَٰبَتۡهُم مُّصِيبَةُۢ بِمَا قَدَّمَتۡ أَيۡدِيهِمۡ ثُمَّ جَآءُوكَ يَحۡلِفُونَ بِٱللَّهِ إِنۡ أَرَدۡنَآ إِلَّآ إِحۡسَٰنٗا وَتَوۡفِيقًا","How would it be if a misfortune smote them because of that which their own hands have sent before (them)? Then would they come unto thee, swearing by Allah that they were seeking naught but harmony and kindness"],["أُوْلَـٰٓئِكَ ٱلَّذِينَ يَعۡلَمُ ٱللَّهُ مَا فِي قُلُوبِهِمۡ فَأَعۡرِضۡ عَنۡهُمۡ وَعِظۡهُمۡ وَقُل لَّهُمۡ فِيٓ أَنفُسِهِمۡ قَوۡلَۢا بَلِيغٗا","Those are they, the secrets of whose hearts Allah knoweth. So oppose them and admonish them, and address them in plain terms about their souls"],["وَمَآ أَرۡسَلۡنَا مِن رَّسُولٍ إِلَّا لِيُطَاعَ بِإِذۡنِ ٱللَّهِۚ وَلَوۡ أَنَّهُمۡ إِذ ظَّلَمُوٓاْ أَنفُسَهُمۡ جَآءُوكَ فَٱسۡتَغۡفَرُواْ ٱللَّهَ وَٱسۡتَغۡفَرَ لَهُمُ ٱلرَّسُولُ لَوَجَدُواْ ٱللَّهَ تَوَّابٗا رَّحِيمٗا","We sent no messenger save that he should be obeyed by Allah's leave. And if, when they had wronged themselves, they had but come unto thee and asked forgiveness of Allah, and asked forgiveness of the messenger, they would have found Allah Forgiving, Merciful"],["فَلَا وَرَبِّكَ لَا يُؤۡمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيۡنَهُمۡ ثُمَّ لَا يَجِدُواْ فِيٓ أَنفُسِهِمۡ حَرَجٗا مِّمَّا قَضَيۡتَ وَيُسَلِّمُواْ تَسۡلِيمٗا","But nay, by thy Lord, they will not believe (in truth) until they make thee judge of what is in dispute between them and find within themselves no dislike of that which thou decidest, and submit with full submission"],["وَلَوۡ أَنَّا كَتَبۡنَا عَلَيۡهِمۡ أَنِ ٱقۡتُلُوٓاْ أَنفُسَكُمۡ أَوِ ٱخۡرُجُواْ مِن دِيَٰرِكُم مَّا فَعَلُوهُ إِلَّا قَلِيلٞ مِّنۡهُمۡۖ وَلَوۡ أَنَّهُمۡ فَعَلُواْ مَا يُوعَظُونَ بِهِۦ لَكَانَ خَيۡرٗا لَّهُمۡ وَأَشَدَّ تَثۡبِيتٗا","And if We had decreed for them: Lay down your lives or go forth from your dwellings, but few of them would have done it; though if they did what they are exhorted to do it would be better for them, and more strengthening"],["وَإِذٗا لَّأٓتَيۡنَٰهُم مِّن لَّدُنَّآ أَجۡرًا عَظِيمٗا","And then We should bestow upon them from Our presence an immense reward"],["وَلَهَدَيۡنَٰهُمۡ صِرَٰطٗا مُّسۡتَقِيمٗا","And should guide them unto a straight path"],["وَمَن يُطِعِ ٱللَّهَ وَٱلرَّسُولَ فَأُوْلَـٰٓئِكَ مَعَ ٱلَّذِينَ أَنۡعَمَ ٱللَّهُ عَلَيۡهِم مِّنَ ٱلنَّبِيِّـۧنَ وَٱلصِّدِّيقِينَ وَٱلشُّهَدَآءِ وَٱلصَّـٰلِحِينَۚ وَحَسُنَ أُوْلَـٰٓئِكَ رَفِيقٗا","Whoso obeyeth Allah and the messenger, they are with those unto whom Allah hath shown favour, of the prophets and the saints and the martyrs and the righteous. The best of company are they"],["ذَٰلِكَ ٱلۡفَضۡلُ مِنَ ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ عَلِيمٗا","That is bounty from Allah, and Allah sufficeth as Knower"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ خُذُواْ حِذۡرَكُمۡ فَٱنفِرُواْ ثُبَاتٍ أَوِ ٱنفِرُواْ جَمِيعٗا","O ye who believe! Take your precautions, then advance the proven ones, or advance all together"],["وَإِنَّ مِنكُمۡ لَمَن لَّيُبَطِّئَنَّ فَإِنۡ أَصَٰبَتۡكُم مُّصِيبَةٞ قَالَ قَدۡ أَنۡعَمَ ٱللَّهُ عَلَيَّ إِذۡ لَمۡ أَكُن مَّعَهُمۡ شَهِيدٗا","Lo! among you there is he who loitereth; and if disaster overtook you, he would say: Allah hath been gracious unto me since I was not present with them"],["وَلَئِنۡ أَصَٰبَكُمۡ فَضۡلٞ مِّنَ ٱللَّهِ لَيَقُولَنَّ كَأَن لَّمۡ تَكُنۢ بَيۡنَكُمۡ وَبَيۡنَهُۥ مَوَدَّةٞ يَٰلَيۡتَنِي كُنتُ مَعَهُمۡ فَأَفُوزَ فَوۡزًا عَظِيمٗا","And if a bounty from Allah befell you, he would surely cry, as if there had been no love between you and him: Oh, would that I had been with them, then should I have achieved a great success"],["۞فَلۡيُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يَشۡرُونَ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا بِٱلۡأٓخِرَةِۚ وَمَن يُقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ فَيُقۡتَلۡ أَوۡ يَغۡلِبۡ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","Let those fight in the way of Allah who sell the life of this world for the other. Whoso fighteth in the way of Allah, be he slain or be he victorious, on him We shall bestow a vast reward"],["وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ ٱلَّذِينَ يَقُولُونَ رَبَّنَآ أَخۡرِجۡنَا مِنۡ هَٰذِهِ ٱلۡقَرۡيَةِ ٱلظَّالِمِ أَهۡلُهَا وَٱجۡعَل لَّنَا مِن لَّدُنكَ وَلِيّٗا وَٱجۡعَل لَّنَا مِن لَّدُنكَ نَصِيرًا","How should ye not fight for the cause of Allah and of the feeble among men and of the women and the children who are crying: Our Lord! Bring us forth from out this town of which the people are oppressors! Oh, give us from thy presence some protecting friend! Oh, give us from Thy presence some defender"],["ٱلَّذِينَ ءَامَنُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ وَٱلَّذِينَ كَفَرُواْ يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّـٰغُوتِ فَقَٰتِلُوٓاْ أَوۡلِيَآءَ ٱلشَّيۡطَٰنِۖ إِنَّ كَيۡدَ ٱلشَّيۡطَٰنِ كَانَ ضَعِيفًا","Those who believe do battle for the cause of Allah; and those who disbelieve do battle for the cause of idols. So fight the minions of the devil. Lo! the devil's strategy is ever weak"],["أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ وَقَالُواْ رَبَّنَا لِمَ كَتَبۡتَ عَلَيۡنَا ٱلۡقِتَالَ لَوۡلَآ أَخَّرۡتَنَآ إِلَىٰٓ أَجَلٖ قَرِيبٖۗ قُلۡ مَتَٰعُ ٱلدُّنۡيَا قَلِيلٞ وَٱلۡأٓخِرَةُ خَيۡرٞ لِّمَنِ ٱتَّقَىٰ وَلَا تُظۡلَمُونَ فَتِيلًا","Hast thou not seen those unto whom it was said: Withhold your hands, establish worship and pay the poordue, but when fighting was prescribed for them behold! a party of them fear mankind even as their fear of Allah or with greater fear, and say: Our Lord! Why hast Thou ordained fighting for us? If only Thou wouldst give us respite yet a while! Say (unto them, O Muhammad): The comfort of this world is scant; the Hereafter will be better for him who wardeth off (evil); and ye will not be wronged the down upon a date-stone"],["أَيۡنَمَا تَكُونُواْ يُدۡرِككُّمُ ٱلۡمَوۡتُ وَلَوۡ كُنتُمۡ فِي بُرُوجٖ مُّشَيَّدَةٖۗ وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَـٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا","Wheresoever ye may be, death will overtake you, even though ye were in lofty towers. Yet if a happy thing befalleth them they say: This is from Allah; and if an evil thing befalleth them they say: This is of thy doing (O Muhammad). Say (unto them): All is from Allah. What is amiss with these people that they come not nigh to understand a happening"],["مَّآ أَصَابَكَ مِنۡ حَسَنَةٖ فَمِنَ ٱللَّهِۖ وَمَآ أَصَابَكَ مِن سَيِّئَةٖ فَمِن نَّفۡسِكَۚ وَأَرۡسَلۡنَٰكَ لِلنَّاسِ رَسُولٗاۚ وَكَفَىٰ بِٱللَّهِ شَهِيدٗا","Whatever of good befalleth thee (O man) it is from Allah, and whatever of ill befalleth thee it is from thyself. We have sent thee (Muhammad) as a messenger unto mankind and Allah is sufficient as Witness"],["مَّن يُطِعِ ٱلرَّسُولَ فَقَدۡ أَطَاعَ ٱللَّهَۖ وَمَن تَوَلَّىٰ فَمَآ أَرۡسَلۡنَٰكَ عَلَيۡهِمۡ حَفِيظٗا","Whoso obeyeth the messenger hath obeyed Allah, and whoso turneth away: We have not sent thee as a warder over them"],["وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ وَٱللَّهُ يَكۡتُبُ مَا يُبَيِّتُونَۖ فَأَعۡرِضۡ عَنۡهُمۡ وَتَوَكَّلۡ عَلَى ٱللَّهِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا","And they say: (It is) obedience; but when they have gone forth from thee a party of them spend the night in planning other than what thou sayest. Allah recordeth what they plan by night. So oppose them and put thy trust in Allah. Allah is sufficient as Trustee"],["أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَۚ وَلَوۡ كَانَ مِنۡ عِندِ غَيۡرِ ٱللَّهِ لَوَجَدُواْ فِيهِ ٱخۡتِلَٰفٗا كَثِيرٗا","Will they not then ponder on the Qur'an? If it had been from other than Allah they would have found therein much incongruity"],["وَإِذَا جَآءَهُمۡ أَمۡرٞ مِّنَ ٱلۡأَمۡنِ أَوِ ٱلۡخَوۡفِ أَذَاعُواْ بِهِۦۖ وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ لَعَلِمَهُ ٱلَّذِينَ يَسۡتَنۢبِطُونَهُۥ مِنۡهُمۡۗ وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكُمۡ وَرَحۡمَتُهُۥ لَٱتَّبَعۡتُمُ ٱلشَّيۡطَٰنَ إِلَّا قَلِيلٗا","And if any tidings, whether of safety or fear, come unto them, they noise it abroad, whereas if they had referred it to the messenger and to such of them as are in authority, those among them who are able to think out the matter would have known it. If it had not been for the grace of Allah upon you and His mercy ye would have followed Satan, save a few (of you)"],["فَقَٰتِلۡ فِي سَبِيلِ ٱللَّهِ لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا","So fight (O Muhammad) in the way of Allah Thou art not taxed (with the responsibility for anyone) except thyself - and urge on the believers. Peradventure Allah will restrain the might of those who disbelieve. Allah is stronger in might and stronger in inflicting punishment"],["مَّن يَشۡفَعۡ شَفَٰعَةً حَسَنَةٗ يَكُن لَّهُۥ نَصِيبٞ مِّنۡهَاۖ وَمَن يَشۡفَعۡ شَفَٰعَةٗ سَيِّئَةٗ يَكُن لَّهُۥ كِفۡلٞ مِّنۡهَاۗ وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا","Whoso interveneth in a good cause will have the reward thereof, and whoso interveneth in an evil cause will bear the consequence thereof. Allah overseeth all things"],["وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا","When ye are greeted with a greeting, greet ye with a better than it or return it. Lo! Allah taketh count of all things"],["ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَۚ لَيَجۡمَعَنَّكُمۡ إِلَىٰ يَوۡمِ ٱلۡقِيَٰمَةِ لَا رَيۡبَ فِيهِۗ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا","Allah! There is no Allah save Him. He gathereth you all unto a Day of Resurrection whereof there is no doubt. Who is more true in statement than Allah"],["۞فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا","What aileth you that ye are become two parties regarding the hypocrites, when Allah cast them back (to disbelief) because of what they earned? Seek ye to guide him whom Allah hath sent astray? He whom Allah sendeth astray, for him thou (O MUhammad) canst not find a road"],["وَدُّواْ لَوۡ تَكۡفُرُونَ كَمَا كَفَرُواْ فَتَكُونُونَ سَوَآءٗۖ فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ حَتَّىٰ يُهَاجِرُواْ فِي سَبِيلِ ٱللَّهِۚ فَإِن تَوَلَّوۡاْ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا","They long that ye should disbelieve even as they disbelieve, that ye may be upon a level (with them). So choose not friends from them till they forsake their homes in the way of Allah; if they turn back (to enmity) then take them and kill them wherever ye find them, and choose no friend nor helper from among them"],["إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٌ أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ فَلَقَٰتَلُوكُمۡۚ فَإِنِ ٱعۡتَزَلُوكُمۡ فَلَمۡ يُقَٰتِلُوكُمۡ وَأَلۡقَوۡاْ إِلَيۡكُمُ ٱلسَّلَمَ فَمَا جَعَلَ ٱللَّهُ لَكُمۡ عَلَيۡهِمۡ سَبِيلٗا","Except those who seek refuge with a people between whom and you there is a covenant, or (those who) come unto you because their hearts forbid them to make war on you or make war on their own folk. Had Allah willed He could have given them power over you so that assuredly they would have fought you. So, if they hold aloof from you and wage not war against you and offer you peace, Allah alloweth you no way against them"],["سَتَجِدُونَ ءَاخَرِينَ يُرِيدُونَ أَن يَأۡمَنُوكُمۡ وَيَأۡمَنُواْ قَوۡمَهُمۡ كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ أُرۡكِسُواْ فِيهَاۚ فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ وَيُلۡقُوٓاْ إِلَيۡكُمُ ٱلسَّلَمَ وَيَكُفُّوٓاْ أَيۡدِيَهُمۡ فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡۚ وَأُوْلَـٰٓئِكُمۡ جَعَلۡنَا لَكُمۡ عَلَيۡهِمۡ سُلۡطَٰنٗا مُّبِينٗا","Ye will find others who desire that they should have security from you, and security from their own folk. So often as they are returned to hostility they are plunged therein. If they keep not aloof from you nor offer you peace nor hold their hands, then take them and kill them wherever ye find them. Against such We have given you clear warrant"],["وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ وَمَن قَتَلَ مُؤۡمِنًا خَطَـٔٗا فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖ وَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦٓ إِلَّآ أَن يَصَّدَّقُواْۚ فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ فَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ وَتَحۡرِيرُ رَقَبَةٖ مُّؤۡمِنَةٖۖ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ مُتَتَابِعَيۡنِ تَوۡبَةٗ مِّنَ ٱللَّهِۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","It is not for a believer to kill a believer unless (it be) by mistake. He who hath killed a believer by mistake must set free a believing slave, and pay the blood-money to the family of the slain, unless they remit it as a charity. If he (the victim) be of a people hostile unto you, and he is a believer, then (the penance is) to set free a believing slave. And if he cometh of a folk between whom and you there is a covenant, then the blood-money must be paid unto his folk and (also) a believing slave must be set free. And whoso hath not the wherewithal must fast two consecutive months. A penance from Allah. Allah is Knower, Wise"],["وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا فَجَزَآؤُهُۥ جَهَنَّمُ خَٰلِدٗا فِيهَا وَغَضِبَ ٱللَّهُ عَلَيۡهِ وَلَعَنَهُۥ وَأَعَدَّ لَهُۥ عَذَابًا عَظِيمٗا","Whoso slayeth a believer of set purpose, his reward is hell for ever. Allah is wroth against him and He hath cursed him and prepared for him an awful doom"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا تَبۡتَغُونَ عَرَضَ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ مَغَانِمُ كَثِيرَةٞۚ كَذَٰلِكَ كُنتُم مِّن قَبۡلُ فَمَنَّ ٱللَّهُ عَلَيۡكُمۡ فَتَبَيَّنُوٓاْۚ إِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","O ye who believe! When ye go forth (to fight) in the way of Allah, be careful to discriminate, and say not unto one who offereth you peace: \"Thou art not a believer,\" seeking the chance profits of this life (so that ye may despoil him). With Allah are plenteous spoils. Even thus (as he now is) were ye before; but Allah hath since then been gracious unto you. Therefore take care to discriminate. Allah is ever Informed of what ye do"],["لَّا يَسۡتَوِي ٱلۡقَٰعِدُونَ مِنَ ٱلۡمُؤۡمِنِينَ غَيۡرُ أُوْلِي ٱلضَّرَرِ وَٱلۡمُجَٰهِدُونَ فِي سَبِيلِ ٱللَّهِ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡۚ فَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ بِأَمۡوَٰلِهِمۡ وَأَنفُسِهِمۡ عَلَى ٱلۡقَٰعِدِينَ دَرَجَةٗۚ وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ وَفَضَّلَ ٱللَّهُ ٱلۡمُجَٰهِدِينَ عَلَى ٱلۡقَٰعِدِينَ أَجۡرًا عَظِيمٗا","Those of the believers who sit still, other than those who have a (disabling) hurt, are not on an equality with those who strive in the way of Allah with their wealth and lives. Allah hath conferred on those who strive with their wealth and lives a rank above the sedentary. Unto each Allah hath promised good, but He hath bestowed on those who strive a great reward above the sedentary"],["دَرَجَٰتٖ مِّنۡهُ وَمَغۡفِرَةٗ وَرَحۡمَةٗۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمًا","Degrees of rank from Him, and forgiveness and mercy. Allah is ever Forgiving, Merciful"],["إِنَّ ٱلَّذِينَ تَوَفَّىٰهُمُ ٱلۡمَلَـٰٓئِكَةُ ظَالِمِيٓ أَنفُسِهِمۡ قَالُواْ فِيمَ كُنتُمۡۖ قَالُواْ كُنَّا مُسۡتَضۡعَفِينَ فِي ٱلۡأَرۡضِۚ قَالُوٓاْ أَلَمۡ تَكُنۡ أَرۡضُ ٱللَّهِ وَٰسِعَةٗ فَتُهَاجِرُواْ فِيهَاۚ فَأُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُۖ وَسَآءَتۡ مَصِيرًا","Lo! as for those whom the angels take (in death) while they wrong themselves, (the angels) will ask: In what were ye engaged? They will say: We were oppressed in the land. (The angels) will say: Was not Allah's earth spacious that ye could have migrated therein? As for such, their habitation will be hell, an evil journey's end"],["إِلَّا ٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلرِّجَالِ وَٱلنِّسَآءِ وَٱلۡوِلۡدَٰنِ لَا يَسۡتَطِيعُونَ حِيلَةٗ وَلَا يَهۡتَدُونَ سَبِيلٗا","Except the feeble among men, and the women, and the children, who are unable to devise a plan and are not shown a way"],["فَأُوْلَـٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا","As for such, it may be that Allah will pardon them. Allah is ever Clement, Forgiving"],["۞وَمَن يُهَاجِرۡ فِي سَبِيلِ ٱللَّهِ يَجِدۡ فِي ٱلۡأَرۡضِ مُرَٰغَمٗا كَثِيرٗا وَسَعَةٗۚ وَمَن يَخۡرُجۡ مِنۢ بَيۡتِهِۦ مُهَاجِرًا إِلَى ٱللَّهِ وَرَسُولِهِۦ ثُمَّ يُدۡرِكۡهُ ٱلۡمَوۡتُ فَقَدۡ وَقَعَ أَجۡرُهُۥ عَلَى ٱللَّهِۗ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","Whoso migrateth for the cause of Allah will find much refuge and abundance in the earth, and whoso forsaketh his home, a fugitive unto Allah and His messenger, and death overtaketh him, his reward is then incumbent on Allah. Allah is ever Forgiving, Merciful"],["وَإِذَا ضَرَبۡتُمۡ فِي ٱلۡأَرۡضِ فَلَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَقۡصُرُواْ مِنَ ٱلصَّلَوٰةِ إِنۡ خِفۡتُمۡ أَن يَفۡتِنَكُمُ ٱلَّذِينَ كَفَرُوٓاْۚ إِنَّ ٱلۡكَٰفِرِينَ كَانُواْ لَكُمۡ عَدُوّٗا مُّبِينٗا","And when ye go forth in the land, it is no sin for you to curtail (your) worship if ye fear that those who disbelieve may attack you. In truth the disbelievers are an open enemy to you"],["وَإِذَا كُنتَ فِيهِمۡ فَأَقَمۡتَ لَهُمُ ٱلصَّلَوٰةَ فَلۡتَقُمۡ طَآئِفَةٞ مِّنۡهُم مَّعَكَ وَلۡيَأۡخُذُوٓاْ أَسۡلِحَتَهُمۡۖ فَإِذَا سَجَدُواْ فَلۡيَكُونُواْ مِن وَرَآئِكُمۡ وَلۡتَأۡتِ طَآئِفَةٌ أُخۡرَىٰ لَمۡ يُصَلُّواْ فَلۡيُصَلُّواْ مَعَكَ وَلۡيَأۡخُذُواْ حِذۡرَهُمۡ وَأَسۡلِحَتَهُمۡۗ وَدَّ ٱلَّذِينَ كَفَرُواْ لَوۡ تَغۡفُلُونَ عَنۡ أَسۡلِحَتِكُمۡ وَأَمۡتِعَتِكُمۡ فَيَمِيلُونَ عَلَيۡكُم مَّيۡلَةٗ وَٰحِدَةٗۚ وَلَا جُنَاحَ عَلَيۡكُمۡ إِن كَانَ بِكُمۡ أَذٗى مِّن مَّطَرٍ أَوۡ كُنتُم مَّرۡضَىٰٓ أَن تَضَعُوٓاْ أَسۡلِحَتَكُمۡۖ وَخُذُواْ حِذۡرَكُمۡۗ إِنَّ ٱللَّهَ أَعَدَّ لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","And when thou (O Muhammad) art among them and arrangest (their) worship for them, let only a party of them stand with thee (to worship) and let them take their arms. Then when they have performed their prostrations let them fall to the rear and let another party come that hath not worshipped and let them worship with thee, and let them take their precaution and their arms. Those who disbelieve long for you to neglect your arms and your baggage that they may attack you once for all. It is no sin for you to lay aside your arms, if rain impedeth you or ye are sick. But take your precaution. Lo! Allah prepareth for the disbelievers shameful punishment"],["فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ فَٱذۡكُرُواْ ٱللَّهَ قِيَٰمٗا وَقُعُودٗا وَعَلَىٰ جُنُوبِكُمۡۚ فَإِذَا ٱطۡمَأۡنَنتُمۡ فَأَقِيمُواْ ٱلصَّلَوٰةَۚ إِنَّ ٱلصَّلَوٰةَ كَانَتۡ عَلَى ٱلۡمُؤۡمِنِينَ كِتَٰبٗا مَّوۡقُوتٗا","When ye have performed the act of worship, remember Allah, standing, sitting and reclining. And when ye are in safety, observe proper worship. Worship at fixed times hath been enjoined on the believers"],["وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ إِن تَكُونُواْ تَأۡلَمُونَ فَإِنَّهُمۡ يَأۡلَمُونَ كَمَا تَأۡلَمُونَۖ وَتَرۡجُونَ مِنَ ٱللَّهِ مَا لَا يَرۡجُونَۗ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمًا","Relent not in pursuit of the enemy. If ye are suffering, lo! they suffer even as ye suffer and ye hope from Allah that for which they cannot hope. Allah is ever Knower, Wise"],["إِنَّآ أَنزَلۡنَآ إِلَيۡكَ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِتَحۡكُمَ بَيۡنَ ٱلنَّاسِ بِمَآ أَرَىٰكَ ٱللَّهُۚ وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا","Lo! We reveal unto thee the Scripture with the truth, that thou mayst judge between mankind by that which Allah showeth thee. And be not thou a pleader for the treacherous"],["وَٱسۡتَغۡفِرِ ٱللَّهَۖ إِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","And seek forgiveness of Allah. Lo! Allah is ever Forgiving, Merciful"],["وَلَا تُجَٰدِلۡ عَنِ ٱلَّذِينَ يَخۡتَانُونَ أَنفُسَهُمۡۚ إِنَّ ٱللَّهَ لَا يُحِبُّ مَن كَانَ خَوَّانًا أَثِيمٗا","And plead not on behalf of (people) who deceive themselves. Lo! Allah loveth not one who is treacherous and sinful"],["يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ وَهُوَ مَعَهُمۡ إِذۡ يُبَيِّتُونَ مَا لَا يَرۡضَىٰ مِنَ ٱلۡقَوۡلِۚ وَكَانَ ٱللَّهُ بِمَا يَعۡمَلُونَ مُحِيطًا","They seek to hide from men and seek not to hide from Allah. He is with them when by night they hold discourse displeasing unto Him. Allah ever surroundeth what they do"],["هَـٰٓأَنتُمۡ هَـٰٓؤُلَآءِ جَٰدَلۡتُمۡ عَنۡهُمۡ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا فَمَن يُجَٰدِلُ ٱللَّهَ عَنۡهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِ أَم مَّن يَكُونُ عَلَيۡهِمۡ وَكِيلٗا","Ho! ye are they who pleaded for them in the life of the world. But who will plead with Allah for them on the Day of Resurrection, or who will then be their defender"],["وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورٗا رَّحِيمٗا","Yet whoso doeth evil or wrongeth his own soul, then seeketh pardon of Allah, will find Allah Forgiving, Merciful"],["وَمَن يَكۡسِبۡ إِثۡمٗا فَإِنَّمَا يَكۡسِبُهُۥ عَلَىٰ نَفۡسِهِۦۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","Whoso committeth sin committeth it only against himself. Allah is ever Knower, Wise"],["وَمَن يَكۡسِبۡ خَطِيٓـَٔةً أَوۡ إِثۡمٗا ثُمَّ يَرۡمِ بِهِۦ بَرِيٓـٔٗا فَقَدِ ٱحۡتَمَلَ بُهۡتَٰنٗا وَإِثۡمٗا مُّبِينٗا","And whoso committeth a delinquency or crime, then throweth (the blame) thereof upon the innocent, hath burdened himself with falsehood and a flagrant crime"],["وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ مِّنۡهُمۡ أَن يُضِلُّوكَ وَمَا يُضِلُّونَ إِلَّآ أَنفُسَهُمۡۖ وَمَا يَضُرُّونَكَ مِن شَيۡءٖۚ وَأَنزَلَ ٱللَّهُ عَلَيۡكَ ٱلۡكِتَٰبَ وَٱلۡحِكۡمَةَ وَعَلَّمَكَ مَا لَمۡ تَكُن تَعۡلَمُۚ وَكَانَ فَضۡلُ ٱللَّهِ عَلَيۡكَ عَظِيمٗا","But for the grace of Allah upon thee (Muhammad), and His mercy, a party of them had resolved to mislead thee, but they will mislead only themselves and they will hurt thee not at all. Allah revealeth unto thee the Scripture and wisdom, and teacheth thee that which thou knewest not. The grace of Allah toward thee hath been infinite"],["۞لَّا خَيۡرَ فِي كَثِيرٖ مِّن نَّجۡوَىٰهُمۡ إِلَّا مَنۡ أَمَرَ بِصَدَقَةٍ أَوۡ مَعۡرُوفٍ أَوۡ إِصۡلَٰحِۭ بَيۡنَ ٱلنَّاسِۚ وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ فَسَوۡفَ نُؤۡتِيهِ أَجۡرًا عَظِيمٗا","There is no good in much of their secret conferences save (in) him who enjoineth almsgiving and kindness and peace-making among the people. Whoso doeth that, seeking the good pleasure of Allah, We shall bestow on him a vast reward"],["وَمَن يُشَاقِقِ ٱلرَّسُولَ مِنۢ بَعۡدِ مَا تَبَيَّنَ لَهُ ٱلۡهُدَىٰ وَيَتَّبِعۡ غَيۡرَ سَبِيلِ ٱلۡمُؤۡمِنِينَ نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ وَسَآءَتۡ مَصِيرًا","And whoso opposeth the messenger after the guidance (of Allah) hath been manifested unto him, and followeth other than the believer's way, We appoint for him that unto which he himself hath turned, and expose him unto hell - a hapless journey's end"],["إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ وَمَن يُشۡرِكۡ بِٱللَّهِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا","Lo! Allah pardoneth not that partners should be ascribed unto Him. He pardoneth all save that to whom He will. Whoso ascribeth partners unto Allah hath wandered far astray"],["إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا","They invoke in His stead only females; they pray to none else than Satan, a rebel"],["لَّعَنَهُ ٱللَّهُۘ وَقَالَ لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ نَصِيبٗا مَّفۡرُوضٗا","Whom Allah cursed, and he said: Surely I will take of Thy bondmen an appointed portion"],["وَلَأُضِلَّنَّهُمۡ وَلَأُمَنِّيَنَّهُمۡ وَلَأٓمُرَنَّهُمۡ فَلَيُبَتِّكُنَّ ءَاذَانَ ٱلۡأَنۡعَٰمِ وَلَأٓمُرَنَّهُمۡ فَلَيُغَيِّرُنَّ خَلۡقَ ٱللَّهِۚ وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ فَقَدۡ خَسِرَ خُسۡرَانٗا مُّبِينٗا","And surely I will lead them astray, and surely I will arouse desires in them, and surely I will command them and they will cut the cattle' ears, and surely I will command them and they will change Allah's creation. Whoso chooseth Satan for a patron instead of Allah is verily a loser and his loss is manifest"],["يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ وَمَا يَعِدُهُمُ ٱلشَّيۡطَٰنُ إِلَّا غُرُورًا","He promiseth them and stirreth up desires in them, and Satan promiseth them only to beguile"],["أُوْلَـٰٓئِكَ مَأۡوَىٰهُمۡ جَهَنَّمُ وَلَا يَجِدُونَ عَنۡهَا مَحِيصٗا","For such, their habitation will be hell, and they will find no refuge therefrom"],["وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ سَنُدۡخِلُهُمۡ جَنَّـٰتٖ تَجۡرِي مِن تَحۡتِهَا ٱلۡأَنۡهَٰرُ خَٰلِدِينَ فِيهَآ أَبَدٗاۖ وَعۡدَ ٱللَّهِ حَقّٗاۚ وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ قِيلٗا","But as for those who believe and do good works We shall bring them into Gardens underneath which rivers flow, wherein they will abide for ever. It is a promise from Allah in truth; and who can be more truthful than Allah in utterance"],["لَّيۡسَ بِأَمَانِيِّكُمۡ وَلَآ أَمَانِيِّ أَهۡلِ ٱلۡكِتَٰبِۗ مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ وَلَا يَجِدۡ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا","It will not be in accordance with your desires, nor the desires of the People of the Scripture. He who doeth wrong will have the recompense thereof, and will not find against Allah any protecting friend or helper"],["وَمَن يَعۡمَلۡ مِنَ ٱلصَّـٰلِحَٰتِ مِن ذَكَرٍ أَوۡ أُنثَىٰ وَهُوَ مُؤۡمِنٞ فَأُوْلَـٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ وَلَا يُظۡلَمُونَ نَقِيرٗا","And whoso doeth good works, whether of male or female, and he (or she) is a believer, such will enter paradise and they will not be wronged the dint in a date-stone"],["وَمَنۡ أَحۡسَنُ دِينٗا مِّمَّنۡ أَسۡلَمَ وَجۡهَهُۥ لِلَّهِ وَهُوَ مُحۡسِنٞ وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا","Who is better in religion than he who surrendereth his purpose to Allah while doing good (to men) and followeth the tradition of Abraham, the upright? Allah (Himself) chose Abraham for friend"],["وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ بِكُلِّ شَيۡءٖ مُّحِيطٗا","Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. Allah ever surroundeth all things"],["وَيَسۡتَفۡتُونَكَ فِي ٱلنِّسَآءِۖ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِيهِنَّ وَمَا يُتۡلَىٰ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ فِي يَتَٰمَى ٱلنِّسَآءِ ٱلَّـٰتِي لَا تُؤۡتُونَهُنَّ مَا كُتِبَ لَهُنَّ وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ وَٱلۡمُسۡتَضۡعَفِينَ مِنَ ٱلۡوِلۡدَٰنِ وَأَن تَقُومُواْ لِلۡيَتَٰمَىٰ بِٱلۡقِسۡطِۚ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ كَانَ بِهِۦ عَلِيمٗا","They consult thee concerning women. Say: Allah giveth you decree concerning them, and the Scripture which hath been recited unto you (giveth decree), concerning female orphans and those unto whom ye give not that which is ordained for them though ye desire to marry them, and (concerning) the weak among children, and that ye should deal justly with orphans. Whatever good ye do, lo! Allah is ever Aware of it"],["وَإِنِ ٱمۡرَأَةٌ خَافَتۡ مِنۢ بَعۡلِهَا نُشُوزًا أَوۡ إِعۡرَاضٗا فَلَا جُنَاحَ عَلَيۡهِمَآ أَن يُصۡلِحَا بَيۡنَهُمَا صُلۡحٗاۚ وَٱلصُّلۡحُ خَيۡرٞۗ وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ وَإِن تُحۡسِنُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","If a woman feareth ill treatment from her husband, or desertion, it is no sin for them twain if they make terms of peace between themselves. Peace is better. But greed hath been made present in the minds (of men). If ye do good and keep from evil, lo! Allah is ever Informed of what ye do"],["وَلَن تَسۡتَطِيعُوٓاْ أَن تَعۡدِلُواْ بَيۡنَ ٱلنِّسَآءِ وَلَوۡ حَرَصۡتُمۡۖ فَلَا تَمِيلُواْ كُلَّ ٱلۡمَيۡلِ فَتَذَرُوهَا كَٱلۡمُعَلَّقَةِۚ وَإِن تُصۡلِحُواْ وَتَتَّقُواْ فَإِنَّ ٱللَّهَ كَانَ غَفُورٗا رَّحِيمٗا","Ye will not be able to deal equally between (your) wives, however much ye wish (to do so). But turn not altogether away (from one), leaving her as in suspense. If ye do good and keep from evil, lo! Allah is ever Forgiving, Merciful"],["وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ وَكَانَ ٱللَّهُ وَٰسِعًا حَكِيمٗا","But if they separate, Allah will compensate each out of His abundance. Allah is ever All-Embracing, All-Knowing"],["وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ مِن قَبۡلِكُمۡ وَإِيَّاكُمۡ أَنِ ٱتَّقُواْ ٱللَّهَۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ غَنِيًّا حَمِيدٗا","Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. And We charged those who received the Scripture before you, and (We charge) you, that ye keep your duty toward Allah. And if ye disbelieve, lo! unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth, and Allah is ever Absolute, Owner of Praise"],["وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۚ وَكَفَىٰ بِٱللَّهِ وَكِيلًا","Unto Allah belongeth whatsoever is in the heavens and whatsoever is in the earth. And Allah is sufficient as Defender"],["إِن يَشَأۡ يُذۡهِبۡكُمۡ أَيُّهَا ٱلنَّاسُ وَيَأۡتِ بِـَٔاخَرِينَۚ وَكَانَ ٱللَّهُ عَلَىٰ ذَٰلِكَ قَدِيرٗا","If He will, He can remove you, O people, and produce others (in your stead). Allah is Able to do that"],["مَّن كَانَ يُرِيدُ ثَوَابَ ٱلدُّنۡيَا فَعِندَ ٱللَّهِ ثَوَابُ ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۚ وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا","Whoso desireth the reward of the world, (let him know that) with Allah is the reward of the world and the Hereafter. Allah is ever Hearer, Seer"],["۞يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ كُونُواْ قَوَّـٰمِينَ بِٱلۡقِسۡطِ شُهَدَآءَ لِلَّهِ وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ أَوِ ٱلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَۚ إِن يَكُنۡ غَنِيًّا أَوۡ فَقِيرٗا فَٱللَّهُ أَوۡلَىٰ بِهِمَاۖ فَلَا تَتَّبِعُواْ ٱلۡهَوَىٰٓ أَن تَعۡدِلُواْۚ وَإِن تَلۡوُۥٓاْ أَوۡ تُعۡرِضُواْ فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا","O ye who believe! Be ye staunch in justice, witnesses for Allah, even though it be against yourselves or (your) parents or (your) kindred, whether (the case be of) a rich man or a poor man, for Allah is nearer unto both (them ye are). So follow not passion lest ye lapse (from truth) and if ye lapse or fall away, then lo! Allah is ever Informed of what ye do"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ ءَامِنُواْ بِٱللَّهِ وَرَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِي نَزَّلَ عَلَىٰ رَسُولِهِۦ وَٱلۡكِتَٰبِ ٱلَّذِيٓ أَنزَلَ مِن قَبۡلُۚ وَمَن يَكۡفُرۡ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ فَقَدۡ ضَلَّ ضَلَٰلَۢا بَعِيدًا","O ye who believe! Believe in Allah and His messenger and the Scripture which He hath revealed unto His messenger, and the Scripture which He revealed aforetime. Whoso disbelieveth in Allah and His angels and His scriptures and His messengers and the Last Day, he verily hath wandered far astray"],["إِنَّ ٱلَّذِينَ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ءَامَنُواْ ثُمَّ كَفَرُواْ ثُمَّ ٱزۡدَادُواْ كُفۡرٗا لَّمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ سَبِيلَۢا","Lo! those who believe, then disbelieve and then (again) believe, then disbelieve, and then increase in disbelief, Allah will never pardon them, nor will He guide them unto a way"],["بَشِّرِ ٱلۡمُنَٰفِقِينَ بِأَنَّ لَهُمۡ عَذَابًا أَلِيمًا","Bear unto the hypocrites the tidings that for them there is a painful doom"],["ٱلَّذِينَ يَتَّخِذُونَ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَيَبۡتَغُونَ عِندَهُمُ ٱلۡعِزَّةَ فَإِنَّ ٱلۡعِزَّةَ لِلَّهِ جَمِيعٗا","Those who chose disbelievers for their friends instead of believers! Do they look for power at their hands? Lo! all power appertaineth to Allah"],["وَقَدۡ نَزَّلَ عَلَيۡكُمۡ فِي ٱلۡكِتَٰبِ أَنۡ إِذَا سَمِعۡتُمۡ ءَايَٰتِ ٱللَّهِ يُكۡفَرُ بِهَا وَيُسۡتَهۡزَأُ بِهَا فَلَا تَقۡعُدُواْ مَعَهُمۡ حَتَّىٰ يَخُوضُواْ فِي حَدِيثٍ غَيۡرِهِۦٓ إِنَّكُمۡ إِذٗا مِّثۡلُهُمۡۗ إِنَّ ٱللَّهَ جَامِعُ ٱلۡمُنَٰفِقِينَ وَٱلۡكَٰفِرِينَ فِي جَهَنَّمَ جَمِيعًا","He hath already revealed unto you in the Scripture that, when ye hear the revelations of Allah rejected and derided, (ye) sit not with them (who disbelieve and mock) until they engage in some other conversation. Lo! in that case (if ye stayed) ye would be like unto them. Lo! Allah will gather hypocrites and disbelievers, all together, into hell"],["ٱلَّذِينَ يَتَرَبَّصُونَ بِكُمۡ فَإِن كَانَ لَكُمۡ فَتۡحٞ مِّنَ ٱللَّهِ قَالُوٓاْ أَلَمۡ نَكُن مَّعَكُمۡ وَإِن كَانَ لِلۡكَٰفِرِينَ نَصِيبٞ قَالُوٓاْ أَلَمۡ نَسۡتَحۡوِذۡ عَلَيۡكُمۡ وَنَمۡنَعۡكُم مِّنَ ٱلۡمُؤۡمِنِينَۚ فَٱللَّهُ يَحۡكُمُ بَيۡنَكُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۚ وَلَن يَجۡعَلَ ٱللَّهُ لِلۡكَٰفِرِينَ عَلَى ٱلۡمُؤۡمِنِينَ سَبِيلًا","Those who wait upon occasion in regard to you and, if a victory cometh unto you from Allah, say: Are we not with you? and if the disbelievers meet with a success say: Had we not the mastery of you, and did we not protect you from the believers? - Allah will judge between you at the Day of Resurrection, and Allah will not give the disbelievers any way (of success) against the believers"],["إِنَّ ٱلۡمُنَٰفِقِينَ يُخَٰدِعُونَ ٱللَّهَ وَهُوَ خَٰدِعُهُمۡ وَإِذَا قَامُوٓاْ إِلَى ٱلصَّلَوٰةِ قَامُواْ كُسَالَىٰ يُرَآءُونَ ٱلنَّاسَ وَلَا يَذۡكُرُونَ ٱللَّهَ إِلَّا قَلِيلٗا","Lo! the hypocrites seek to beguile Allah, but it is He Who beguileth them. When they stand up to worship they perform it languidly and to be seen of men, and are mindful of Allah but little"],["مُّذَبۡذَبِينَ بَيۡنَ ذَٰلِكَ لَآ إِلَىٰ هَـٰٓؤُلَآءِ وَلَآ إِلَىٰ هَـٰٓؤُلَآءِۚ وَمَن يُضۡلِلِ ٱللَّهُ فَلَن تَجِدَ لَهُۥ سَبِيلٗا","Swaying between this (and that), (belonging) neither to these nor to those. He whom Allah causeth to go astray, thou (O Muhammad) wilt not find a way for him"],["يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ لَا تَتَّخِذُواْ ٱلۡكَٰفِرِينَ أَوۡلِيَآءَ مِن دُونِ ٱلۡمُؤۡمِنِينَۚ أَتُرِيدُونَ أَن تَجۡعَلُواْ لِلَّهِ عَلَيۡكُمۡ سُلۡطَٰنٗا مُّبِينًا","O ye who believe! Choose not disbelievers for (your) friends in place of believers. Would ye give Allah a clear warrant against you"],["إِنَّ ٱلۡمُنَٰفِقِينَ فِي ٱلدَّرۡكِ ٱلۡأَسۡفَلِ مِنَ ٱلنَّارِ وَلَن تَجِدَ لَهُمۡ نَصِيرًا","Lo! the hypocrites (will be) in the lowest deep of the Fire, and thou wilt find no helper for them"],["إِلَّا ٱلَّذِينَ تَابُواْ وَأَصۡلَحُواْ وَٱعۡتَصَمُواْ بِٱللَّهِ وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ فَأُوْلَـٰٓئِكَ مَعَ ٱلۡمُؤۡمِنِينَۖ وَسَوۡفَ يُؤۡتِ ٱللَّهُ ٱلۡمُؤۡمِنِينَ أَجۡرًا عَظِيمٗا","Save those who repent and amend and hold fast to Allah and make their religion pure for Allah (only). Those are with the believers. And Allah will bestow on the believers an immense reward"],["مَّا يَفۡعَلُ ٱللَّهُ بِعَذَابِكُمۡ إِن شَكَرۡتُمۡ وَءَامَنتُمۡۚ وَكَانَ ٱللَّهُ شَاكِرًا عَلِيمٗا","What concern hath Allah for your punishment if ye are thankful (for His mercies) and believe (in Him)? Allah was ever Responsive, Aware"],["۞لَّا يُحِبُّ ٱللَّهُ ٱلۡجَهۡرَ بِٱلسُّوٓءِ مِنَ ٱلۡقَوۡلِ إِلَّا مَن ظُلِمَۚ وَكَانَ ٱللَّهُ سَمِيعًا عَلِيمًا","Allah loveth not the utterance of harsh speech save by one who hath been wronged. Allah is ever Hearer, Knower"],["إِن تُبۡدُواْ خَيۡرًا أَوۡ تُخۡفُوهُ أَوۡ تَعۡفُواْ عَن سُوٓءٖ فَإِنَّ ٱللَّهَ كَانَ عَفُوّٗا قَدِيرًا","If ye do good openly or keep it secret, or forgive evil, lo! Allah is ever Forgiving, Powerful"],["إِنَّ ٱلَّذِينَ يَكۡفُرُونَ بِٱللَّهِ وَرُسُلِهِۦ وَيُرِيدُونَ أَن يُفَرِّقُواْ بَيۡنَ ٱللَّهِ وَرُسُلِهِۦ وَيَقُولُونَ نُؤۡمِنُ بِبَعۡضٖ وَنَكۡفُرُ بِبَعۡضٖ وَيُرِيدُونَ أَن يَتَّخِذُواْ بَيۡنَ ذَٰلِكَ سَبِيلًا","Lo! those who disbelieve in Allah and His messengers, and seek to make distinction between Allah and His messengers, and say: We believe in some and disbelieve in others, and seek to choose a way in between"],["أُوْلَـٰٓئِكَ هُمُ ٱلۡكَٰفِرُونَ حَقّٗاۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ عَذَابٗا مُّهِينٗا","Such are disbelievers in truth; and for disbelievers We prepare a shameful doom"],["وَٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرُسُلِهِۦ وَلَمۡ يُفَرِّقُواْ بَيۡنَ أَحَدٖ مِّنۡهُمۡ أُوْلَـٰٓئِكَ سَوۡفَ يُؤۡتِيهِمۡ أُجُورَهُمۡۚ وَكَانَ ٱللَّهُ غَفُورٗا رَّحِيمٗا","But those who believe in Allah and His messengers and make no distinction between any of them, unto them Allah will give their wages; and Allah was ever Forgiving, Merciful"],["يَسۡـَٔلُكَ أَهۡلُ ٱلۡكِتَٰبِ أَن تُنَزِّلَ عَلَيۡهِمۡ كِتَٰبٗا مِّنَ ٱلسَّمَآءِۚ فَقَدۡ سَأَلُواْ مُوسَىٰٓ أَكۡبَرَ مِن ذَٰلِكَ فَقَالُوٓاْ أَرِنَا ٱللَّهَ جَهۡرَةٗ فَأَخَذَتۡهُمُ ٱلصَّـٰعِقَةُ بِظُلۡمِهِمۡۚ ثُمَّ ٱتَّخَذُواْ ٱلۡعِجۡلَ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ فَعَفَوۡنَا عَن ذَٰلِكَۚ وَءَاتَيۡنَا مُوسَىٰ سُلۡطَٰنٗا مُّبِينٗا","The people of the Scripture ask of thee that thou shouldst cause an (actual) Book to descend upon them from heaven. They asked a greater thing of Moses aforetime, for they said: Show us Allah plainly. The storm of lightning seized them for their wickedness. Then (even) after that) they chose the calf (for worship) after clear proofs (of Allah's Sovereignty) had come unto them. And We forgave them that! And We bestowed on Moses evident authority"],["وَرَفَعۡنَا فَوۡقَهُمُ ٱلطُّورَ بِمِيثَٰقِهِمۡ وَقُلۡنَا لَهُمُ ٱدۡخُلُواْ ٱلۡبَابَ سُجَّدٗا وَقُلۡنَا لَهُمۡ لَا تَعۡدُواْ فِي ٱلسَّبۡتِ وَأَخَذۡنَا مِنۡهُم مِّيثَٰقًا غَلِيظٗا","And We caused the Mount to tower above them at (the taking of) their covenant: and We bade them: Enter the gate, prostrate! and We bode them: Transgress not the Sabbath! and We took from them a firm covenant"],["فَبِمَا نَقۡضِهِم مِّيثَٰقَهُمۡ وَكُفۡرِهِم بِـَٔايَٰتِ ٱللَّهِ وَقَتۡلِهِمُ ٱلۡأَنۢبِيَآءَ بِغَيۡرِ حَقّٖ وَقَوۡلِهِمۡ قُلُوبُنَا غُلۡفُۢۚ بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ فَلَا يُؤۡمِنُونَ إِلَّا قَلِيلٗا","Then because of their breaking of their covenant, and their disbelieving in the revelations of Allah, and their slaying of the prophets wrongfully, and their saying: Our hearts are hardened - Nay, but Allah set a seal upon them for their disbelief, so that they believe not save a few"],["وَبِكُفۡرِهِمۡ وَقَوۡلِهِمۡ عَلَىٰ مَرۡيَمَ بُهۡتَٰنًا عَظِيمٗا","And because of their disbelief and of their speaking against Mary a tremendous calumny"],["وَقَوۡلِهِمۡ إِنَّا قَتَلۡنَا ٱلۡمَسِيحَ عِيسَى ٱبۡنَ مَرۡيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمۡۚ وَإِنَّ ٱلَّذِينَ ٱخۡتَلَفُواْ فِيهِ لَفِي شَكّٖ مِّنۡهُۚ مَا لَهُم بِهِۦ مِنۡ عِلۡمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّۚ وَمَا قَتَلُوهُ يَقِينَۢا","And because of their saying: We slew the Messiah, Jesus son of Mary, Allah's messenger - they slew him not nor crucified him, but it appeared so unto them; and lo! those who disagree concerning it are in doubt thereof; they have no knowledge thereof save pursuit of a conjecture; they slew him not for certain"],["بَل رَّفَعَهُ ٱللَّهُ إِلَيۡهِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا","But Allah took him up unto Himself. Allah was ever Mighty, Wise"],["وَإِن مِّنۡ أَهۡلِ ٱلۡكِتَٰبِ إِلَّا لَيُؤۡمِنَنَّ بِهِۦ قَبۡلَ مَوۡتِهِۦۖ وَيَوۡمَ ٱلۡقِيَٰمَةِ يَكُونُ عَلَيۡهِمۡ شَهِيدٗا","There is not one of the People of the Scripture but will believe in him before his death, and on the Day of Resurrection he will be a witness against them"],["فَبِظُلۡمٖ مِّنَ ٱلَّذِينَ هَادُواْ حَرَّمۡنَا عَلَيۡهِمۡ طَيِّبَٰتٍ أُحِلَّتۡ لَهُمۡ وَبِصَدِّهِمۡ عَن سَبِيلِ ٱللَّهِ كَثِيرٗا","Because of the wrongdoing of the Jews We forbade them good things which were (before) made lawful unto them, and because of their much hindering from Allah's way"],["وَأَخۡذِهِمُ ٱلرِّبَوٰاْ وَقَدۡ نُهُواْ عَنۡهُ وَأَكۡلِهِمۡ أَمۡوَٰلَ ٱلنَّاسِ بِٱلۡبَٰطِلِۚ وَأَعۡتَدۡنَا لِلۡكَٰفِرِينَ مِنۡهُمۡ عَذَابًا أَلِيمٗا","And of their taking usury when they were forbidden it, and of their devouring people's wealth by false pretences, We have prepared for those of them who disbelieve a painful doom"],["لَّـٰكِنِ ٱلرَّـٰسِخُونَ فِي ٱلۡعِلۡمِ مِنۡهُمۡ وَٱلۡمُؤۡمِنُونَ يُؤۡمِنُونَ بِمَآ أُنزِلَ إِلَيۡكَ وَمَآ أُنزِلَ مِن قَبۡلِكَۚ وَٱلۡمُقِيمِينَ ٱلصَّلَوٰةَۚ وَٱلۡمُؤۡتُونَ ٱلزَّكَوٰةَ وَٱلۡمُؤۡمِنُونَ بِٱللَّهِ وَٱلۡيَوۡمِ ٱلۡأٓخِرِ أُوْلَـٰٓئِكَ سَنُؤۡتِيهِمۡ أَجۡرًا عَظِيمًا","But those of them who are firm in knowledge and the believers believe in that which is revealed unto thee, and that which was revealed before thee, especially the diligent in prayer and those who pay the poor-due, the believers in Allah and the Last Day. Upon these We shall bestow immense reward"],["۞إِنَّآ أَوۡحَيۡنَآ إِلَيۡكَ كَمَآ أَوۡحَيۡنَآ إِلَىٰ نُوحٖ وَٱلنَّبِيِّـۧنَ مِنۢ بَعۡدِهِۦۚ وَأَوۡحَيۡنَآ إِلَىٰٓ إِبۡرَٰهِيمَ وَإِسۡمَٰعِيلَ وَإِسۡحَٰقَ وَيَعۡقُوبَ وَٱلۡأَسۡبَاطِ وَعِيسَىٰ وَأَيُّوبَ وَيُونُسَ وَهَٰرُونَ وَسُلَيۡمَٰنَۚ وَءَاتَيۡنَا دَاوُۥدَ زَبُورٗا","Lo! We inspire thee as We inspired Noah and the prophets after him, as We inspired Abraham and Ishmael and Isaac and Jacob and the tribes, and Jesus and Job and Jonah and Aaron and Solomon, and as We imparted unto David the Psalms"],["وَرُسُلٗا قَدۡ قَصَصۡنَٰهُمۡ عَلَيۡكَ مِن قَبۡلُ وَرُسُلٗا لَّمۡ نَقۡصُصۡهُمۡ عَلَيۡكَۚ وَكَلَّمَ ٱللَّهُ مُوسَىٰ تَكۡلِيمٗا","And messengers We have mentioned unto thee before and messengers We have not mentioned unto thee; and Allah spake directly unto Moses"],["رُّسُلٗا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةُۢ بَعۡدَ ٱلرُّسُلِۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمٗا","Messengers of good cheer and of warning, in order that mankind might have no argument against Allah after the messengers. Allah was ever Mighty, Wise"],["لَّـٰكِنِ ٱللَّهُ يَشۡهَدُ بِمَآ أَنزَلَ إِلَيۡكَۖ أَنزَلَهُۥ بِعِلۡمِهِۦۖ وَٱلۡمَلَـٰٓئِكَةُ يَشۡهَدُونَۚ وَكَفَىٰ بِٱللَّهِ شَهِيدًا","But Allah (Himself) testifieth concerning that which He hath revealeth unto thee; in His knowledge hath He revealed it; and the angels also testify. And Allah is sufficient Witness"],["إِنَّ ٱلَّذِينَ كَفَرُواْ وَصَدُّواْ عَن سَبِيلِ ٱللَّهِ قَدۡ ضَلُّواْ ضَلَٰلَۢا بَعِيدًا","Lo! those who disbelieve and hinder (others) from the way of Allah, they verily have wandered far astray"],["إِنَّ ٱلَّذِينَ كَفَرُواْ وَظَلَمُواْ لَمۡ يَكُنِ ٱللَّهُ لِيَغۡفِرَ لَهُمۡ وَلَا لِيَهۡدِيَهُمۡ طَرِيقًا","Lo! those who disbelieve and deal in wrong, Allah will never forgive them, neither will He guide them unto a road"],["إِلَّا طَرِيقَ جَهَنَّمَ خَٰلِدِينَ فِيهَآ أَبَدٗاۚ وَكَانَ ذَٰلِكَ عَلَى ٱللَّهِ يَسِيرٗا","Except the road of hell, wherein they will abide for ever. And that is ever easy for Allah"],["يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُمُ ٱلرَّسُولُ بِٱلۡحَقِّ مِن رَّبِّكُمۡ فَـَٔامِنُواْ خَيۡرٗا لَّكُمۡۚ وَإِن تَكۡفُرُواْ فَإِنَّ لِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضِۚ وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا","O mankind! The messenger hath come unto you with the Truth from your Lord. Therefor believe; (it is) better for you. But if ye disbelieve, still, lo! unto Allah belongeth whatsoever is in the heavens and the earth. Allah is ever Knower, Wise"],["يَـٰٓأَهۡلَ ٱلۡكِتَٰبِ لَا تَغۡلُواْ فِي دِينِكُمۡ وَلَا تَقُولُواْ عَلَى ٱللَّهِ إِلَّا ٱلۡحَقَّۚ إِنَّمَا ٱلۡمَسِيحُ عِيسَى ٱبۡنُ مَرۡيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلۡقَىٰهَآ إِلَىٰ مَرۡيَمَ وَرُوحٞ مِّنۡهُۖ فَـَٔامِنُواْ بِٱللَّهِ وَرُسُلِهِۦۖ وَلَا تَقُولُواْ ثَلَٰثَةٌۚ ٱنتَهُواْ خَيۡرٗا لَّكُمۡۚ إِنَّمَا ٱللَّهُ إِلَٰهٞ وَٰحِدٞۖ سُبۡحَٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٞۘ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ وَكَفَىٰ بِٱللَّهِ وَكِيلٗا","O People of the Scripture! Do not exaggerate in your religion nor utter aught concerning Allah save the truth. The Messiah, Jesus son of Mary, was only a messenger of Allah, and His word which He conveyed unto Mary, and a spirit from Him. So believe in Allah and His messengers, and say not \"Three\" - Cease! (it is) better for you! - Allah is only One Allah. Far is it removed from His Transcendent Majesty that He should have a son. His is all that is in the heavens and all that is in the earth. And Allah is sufficient as Defender"],["لَّن يَسۡتَنكِفَ ٱلۡمَسِيحُ أَن يَكُونَ عَبۡدٗا لِّلَّهِ وَلَا ٱلۡمَلَـٰٓئِكَةُ ٱلۡمُقَرَّبُونَۚ وَمَن يَسۡتَنكِفۡ عَنۡ عِبَادَتِهِۦ وَيَسۡتَكۡبِرۡ فَسَيَحۡشُرُهُمۡ إِلَيۡهِ جَمِيعٗا","The Messiah will never scorn to be a slave unto Allah, nor will the favoured angels. Whoso scorneth His service and is proud, all such will He assemble unto Him"],["فَأَمَّا ٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ فَيُوَفِّيهِمۡ أُجُورَهُمۡ وَيَزِيدُهُم مِّن فَضۡلِهِۦۖ وَأَمَّا ٱلَّذِينَ ٱسۡتَنكَفُواْ وَٱسۡتَكۡبَرُواْ فَيُعَذِّبُهُمۡ عَذَابًا أَلِيمٗا وَلَا يَجِدُونَ لَهُم مِّن دُونِ ٱللَّهِ وَلِيّٗا وَلَا نَصِيرٗا","Then, as for those who believed and did good works, unto them will He pay their wages in full, adding unto them of His bounty; and as for those who were scornful and proud, them will He punish with a painful doom. And they will not find for them, against Allah, any protecting friend or helper"],["يَـٰٓأَيُّهَا ٱلنَّاسُ قَدۡ جَآءَكُم بُرۡهَٰنٞ مِّن رَّبِّكُمۡ وَأَنزَلۡنَآ إِلَيۡكُمۡ نُورٗا مُّبِينٗا","O mankind! Now hath a proof from your Lord come unto you, and We have sent down unto you a clear light"],["فَأَمَّا ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَٱعۡتَصَمُواْ بِهِۦ فَسَيُدۡخِلُهُمۡ فِي رَحۡمَةٖ مِّنۡهُ وَفَضۡلٖ وَيَهۡدِيهِمۡ إِلَيۡهِ صِرَٰطٗا مُّسۡتَقِيمٗا","As for those who believe in Allah, and hold fast unto Him, them He will cause to enter into His mercy and grace, and will guide them unto Him by a straight road"],["يَسۡتَفۡتُونَكَ قُلِ ٱللَّهُ يُفۡتِيكُمۡ فِي ٱلۡكَلَٰلَةِۚ إِنِ ٱمۡرُؤٌاْ هَلَكَ لَيۡسَ لَهُۥ وَلَدٞ وَلَهُۥٓ أُخۡتٞ فَلَهَا نِصۡفُ مَا تَرَكَۚ وَهُوَ يَرِثُهَآ إِن لَّمۡ يَكُن لَّهَا وَلَدٞۚ فَإِن كَانَتَا ٱثۡنَتَيۡنِ فَلَهُمَا ٱلثُّلُثَانِ مِمَّا تَرَكَۚ وَإِن كَانُوٓاْ إِخۡوَةٗ رِّجَالٗا وَنِسَآءٗ فَلِلذَّكَرِ مِثۡلُ حَظِّ ٱلۡأُنثَيَيۡنِۗ يُبَيِّنُ ٱللَّهُ لَكُمۡ أَن تَضِلُّواْۗ وَٱللَّهُ بِكُلِّ شَيۡءٍ عَلِيمُۢ","They ask thee for a pronouncement. Say: Allah hath pronounced for you concerning distant kindred. If a man die childless and he have a sister, hers is half the heritage, and he would have inherited from her had she died childless. And if there be two sisters, then theirs are two-thirds of the heritage, and if they be brethren, men and women, unto the male is the equivalent of the share of two females. Allah expoundeth unto you, so that ye err not. Allah is Knower of all things"]],"jal":[[1,1,"سُورَة النِّساء [ مَدَنِيَّة وآياتها ١٧٦ أوْ ١٧٧ نَزَلَتْ بَعْد المُمْتَحِنَة ]\n\n﴿يا أيّها النّاس﴾ أيْ أهْل مَكَّة ﴿اتَّقُوا رَبّكُمْ﴾ أيْ عِقابه بِأَنْ تُطِيعُوهُ ﴿الَّذِي خَلَقَكُمْ مِن نَفْس واحِدَة﴾ آدَم ﴿وخَلَقَ مِنها زَوْجها﴾ حَوّاء بِالمَدِّ مِن ضِلْع مِن أضْلاعه اليُسْرى ﴿وبَثَّ﴾ فَرَّقَ ونَشَرَ ﴿مِنهُما﴾ مِن آدَم وحَوّاء ﴿رِجالًا كَثِيرًا ونِساء﴾ كَثِيرَة ﴿واتَّقُوا اللَّه الَّذِي تَساءَلُونَ﴾ فِيهِ إدْغام التّاء فِي الأَصْل فِي السِّين وفِي قِراءَة بِالتَّخْفِيفِ بِحَذْفِها أيْ تَتَساءَلُونَ ﴿بِهِ﴾ فِيما بَيْنكُمْ حَيْثُ يَقُول بَعْضكُمْ لِبَعْضٍ أسْأَلك بِاللَّهِ وأَنْشُدك بِاللَّهِ ﴿و﴾ اتَّقُوا ﴿الأَرْحام﴾ أنْ تَقْطَعُوها وفِي قِراءَة بِالجَرِّ عَطْفًا عَلى الضَّمِير فِي بِهِ وكانُوا يَتَناشَدُونَ بِالرَّحِمِ ﴿إنّ اللَّه كانَ عَلَيْكُمْ رَقِيبًا﴾ حافِظًا لِأَعْمالِكُمْ فَيُجازِيكُمْ بِها أيْ لَمْ يَزَلْ مُتَّصِفًا بِذَلِك"],[2,2,"ونَزَلَ فِي يَتِيم طَلَبَ مِن ولِيّه ماله فَمَنَعَهُ ﴿وآتُوا اليَتامى﴾ الصِّغار الَّذِينَ لا أب لَهُمْ، ﴿أمْوالهمْ﴾ إذا بَلَغُوا ﴿ولا تَتَبَدَّلُوا الخَبِيث﴾ الحَرام ﴿بِالطَّيِّبِ﴾ الحَلال أيْ تَأْخُذُوهُ بَدَله كَما تَفْعَلُونَ مِن أخْذ الجَيِّد مِن مال اليَتِيم وجَعْل الرَّدِيء مِن مالكُمْ مَكانه ﴿ولا تَأْكُلُوا أمْوالهمْ﴾ مَضْمُومَة ﴿إلى أمْوالكُمْ إنّهُ﴾ أيْ أكْلها ﴿كانَ حُوبًا﴾ ذَنْبًا ﴿كَبِيرًا﴾ عَظِيمًا ولَمّا نَزَلَتْ تَحَرَّجُوا مِن وِلايَة اليَتامى وكانَ فِيهِمْ مَن تَحْته العَشْر أوْ الثَّمان مِن الأَزْواج فَلا يَعْدِل بَيْنهنَّ فَنَزَلَ"],[3,3,"﴿وإنْ خِفْتُمْ﴾ أنْ لا ﴿تُقْسِطُوا﴾ تَعْدِلُوا ﴿فِي اليَتامى﴾ فَتَحَرَّجْتُمْ مِن أمْرهمْ فَخافُوا أيْضًا أنْ لا تَعْدِلُوا بَيْن النِّساء إذا نَكَحْتُمُوهُنَّ ﴿فانْكِحُوا﴾ تَزَوَّجُوا ﴿ما﴾ بِمَعْنى مَن ﴿طابَ لَكُمْ مِن النِّساء مَثْنى وثُلاث ورُباع﴾ أيْ اثْنَتَيْنِ وثَلاثًا وأَرْبَعًا ولا تَزِيدُوا عَلى ذَلِكَ ﴿فَإنْ خِفْتُمْ﴾ أنْ لا ﴿تَعْدِلُوا﴾ فِيهِنَّ بِالنَّفَقَةِ والقَسْم ﴿فَواحِدَة﴾ انْكِحُوها ﴿أوْ﴾ اقْتَصِرُوا عَلى ﴿ما مَلَكَتْ أيْمانكُمْ﴾ مِن الإماء إذْ لَيْسَ لَهُنَّ مِن الحُقُوق ما لِلزَّوْجاتِ ﴿ذَلِكَ﴾ أيْ نِكاح الأَرْبَع فَقَطْ أوْ الواحِدَة أوْ التَّسَرِّي ﴿أدْنى﴾ أقْرَب إلى ﴿ألّا تَعُولُوا﴾ تَجُورُوا"],[4,4,"﴿وآتُوا﴾ أعْطُوا ﴿النِّساء صَدَقاتهنَّ﴾ جَمْع صَدَقَة مُهُورهنَّ ﴿نِحْلَة﴾ مَصْدَر عَطِيَّة عَنْ طِيب نَفْس ﴿فَإنْ طِبْنَ لَكُمْ عَنْ شَيْء مِنهُ نَفْسًا﴾ تَمْيِيز مُحَوَّل عَنْ الفاعِل أيْ طابَتْ أنْفُسهنَّ لَكُمْ عَنْ شَيْء مِن الصَّداق فَوَهَبْنَهُ لَكُمْ ﴿فَكُلُوهُ هَنِيئًا﴾ طَيِّبًا ﴿مَرِيئًا﴾ مَحْمُود العاقِبَة لا ضَرَر فِيهِ عَلَيْكُمْ فِي الآخِرَة نَزَلَتْ رَدًّا عَلى مَن كَرِهَ ذَلِكَ"],[5,5,"﴿ولا تُؤْتُوا﴾ أيّها الأَوْلِياء ﴿السُّفَهاء﴾ المُبَذِّرِينَ مِن الرِّجال والنِّساء والصِّبْيان ﴿أمْوالكُمْ﴾ أيْ أمْوالكُمْ الَّتِي فِي أيْدِيكُمْ ﴿الَّتِي جَعَلَ اللَّه لَكُمْ قِيامًا﴾ مَصْدَر قامَ أيْ تَقُوم بِمَعاشِكُمْ وصَلاح أوْلادكُمْ فَيَضَعُوها فِي غَيْر وجْهها وفِي قِراءَة قِيَمًا جَمْع قِيمَة ما تَقُوم بِهِ الأَمْتِعَة ﴿وارْزُقُوهُمْ فِيها﴾ أيْ أطْعِمُوهُمْ مِنها ﴿واكْسُوهُمْ وقُولُوا لَهُمْ قَوْلًا مَعْرُوفًا﴾ عِدُوهُمْ عِدَة جَمِيلَة بِإعْطائِهِمْ أمْوالهمْ إذا رَشَدُوا."],[6,6,"﴿وابْتَلُوا﴾ اخْتَبِرُوا ﴿اليَتامى﴾ قَبْل البُلُوغ فِي دِينهمْ وتَصَرُّفهمْ فِي أحْوالهمْ ﴿حَتّى إذا بَلَغُوا النِّكاح﴾ أيْ صارُوا أهْلًا لَهُ بِالِاحْتِلامِ أوْ السِّنّ وهُوَ اسْتِكْمال خَمْس عَشْرَة سَنَة عِنْد الشّافِعِيّ ﴿فَإنْ آنَسْتُمْ﴾ أبْصَرْتُمْ ﴿مِنهُمْ رُشْدًا﴾ صَلاحًا فِي دِينهمْ ومالهمْ ﴿فادْفَعُوا إلَيْهِمْ أمْوالهمْ ولا تَأْكُلُوها﴾ أيّها الأَوْلِياء ﴿إسْرافًا﴾ بِغَيْرِ حَقّ حال ﴿وبِدارًا﴾ أيْ مُبادِرِينَ إلى إنْفاقها مَخافَة ﴿أنْ يَكْبُرُوا﴾ رُشَداء فَيَلْزَمكُمْ تَسْلِيمها إلَيْهِمْ ﴿ومَن كانَ غَنِيًّا﴾ مِن الأَوْلِياء ﴿فَلْيَسْتَعْفِفْ﴾ أيْ يَعِفّ عَنْ مال اليَتِيم ويَمْتَنِع مِن أكْله ﴿ومَن كانَ فَقِيرًا فَلْيَأْكُلْ﴾ مِنهُ ﴿بِالمَعْرُوفِ﴾ بِقَدْرِ أُجْرَة عَمَله ﴿فَإذا دَفَعْتُمْ إلَيْهِمْ﴾ أيْ إلى اليَتامى ﴿أمْوالهمْ فَأَشْهِدُوا عَلَيْهِمْ﴾ أنَّهُمْ تَسَلَّمُوها وبَرِئْتُمْ لِئَلّا يَقَع اخْتِلاف فَتَرْجِعُوا إلى البَيِّنَة وهَذا أمْر إرْشاد ﴿وكَفى بِاللَّهِ﴾ الباء زائِدَة ﴿حَسِيبًا﴾ حافِظًا لِأَعْمالِ خَلْقه ومُحاسِبهمْ"],[7,7,"ونَزَلَ رَدًّا لِما كانَ عَلَيْهِ فِي الجاهِلِيَّة مِن عَدَم تَوْرِيث النِّساء والصِّغار: ﴿لِلرِّجالِ﴾ الأَوْلاد والأَقْرِباء، ﴿نَصِيب﴾ حَظّ ﴿مِمّا تَرَكَ الوالِدانِ والأَقْرَبُونَ﴾ المُتَوَفَّوْنَ ﴿ولِلنِّساءِ نَصِيب مِمّا تَرَكَ الوالِدانِ والأَقْرَبُونَ مِمّا قَلَّ مِنهُ﴾ أيْ المال ﴿أوْ كَثُرَ﴾ جَعَلَهُ اللَّه ﴿نَصِيبًا مَفْرُوضًا﴾ مَقْطُوعًا بِتَسْلِيمِهِ إلَيْهِمْ"],[8,8,"﴿وإذا حَضَرَ القِسْمَة﴾ لِلْمِيراثِ ﴿أُولُو القُرْبى﴾ ذَوُو القَرابَة مِمَّنْ لا يَرِث ﴿واليَتامى والمَساكِين فارْزُقُوهُمْ مِنهُ﴾ شَيْئًا قَبْل القِسْمَة ﴿وقُولُوا﴾ أيّها الأَوْلِياء ﴿لَهُمْ﴾ إذا كانَ الوَرَثَة صِغارًا ﴿قَوْلًا مَعْرُوفًا﴾ جَمِيلًا بِأَنْ تَعْتَذِرُوا إلَيْهِمْ أنَّكُمْ لا تَمْلِكُونَهُ وأَنَّهُ لِلصِّغارِ وهَذا قِيلَ إنّهُ مَنسُوخ وقِيلَ لا ولَكِنْ تَهاوَنَ النّاس فِي تَرْكه وعَلَيْهِ فَهُوَ نَدْب وعَنْ ابْن عَبّاس واجِب"],[9,9,"﴿ولْيَخْشَ﴾ أيْ لِيَخَفْ عَلى اليَتامى ﴿الَّذِينَ لَوْ تَرَكُوا﴾ أيْ قارَبُوا أنْ يَتْرُكُوا ﴿مِن خَلْفهمْ﴾ أيْ بَعْد مَوْتهمْ ﴿ذُرِّيَّة ضِعافًا﴾ أوْلادًا صِغارًا ﴿خافُوا عَلَيْهِمْ﴾ الضَّياع ﴿فَلْيَتَّقُوا اللَّه﴾ فِي أمْر اليَتامى ولْيَأْتُوا إلَيْهِ ما يُحِبُّونَ أنْ يُفْعَل بِذُرِّيَّتِهِمْ مِن بَعْدهمْ ﴿ولْيَقُولُوا﴾ لِمَن حَضَرَتْهُ الوَفاة ﴿قَوْلًا سَدِيدًا﴾ صَوابًا بِأَنْ يَأْمُرُوهُ أنْ يَتَصَدَّق بِدُونِ ثُلُثه ويَدَع الباقِي لِوَرَثَتِهِ ولا يَتْرُكهُمْ عالَة"],[10,10,"﴿إنّ الَّذِينَ يَأْكُلُونَ أمْوال اليَتامى ظُلْمًا﴾ بِغَيْرِ حَقّ ﴿إنّما يَأْكُلُونَ فِي بُطُونهمْ﴾ أيْ مِلْأَها ﴿نارًا﴾ لِأَنَّهُ يُؤَوَّل إلَيْها ﴿وسَيَصْلَوْنَ﴾ بِالبِناءِ لِلْفاعِلِ والمَفْعُول يَدْخُلُونَ ﴿سَعِيرًا﴾ نارًا شَدِيدَة يَحْتَرِقُونَ فِيها"],[11,11,"﴿يُوصِيكُمْ﴾ يَأْمُركُمْ ﴿اللَّه فِي﴾ شَأْن ﴿أوْلادكُمْ﴾ بِما يَذْكُر ﴿لِلذَّكَرِ﴾ مِنهُمْ ﴿مِثْل حَظّ﴾ نَصِيب ﴿الأُنْثَيَيْنِ﴾ إذا اجْتَمَعَتا مَعَهُ فَلَهُ نِصْف المال ولَهُما النِّصْف فَإنْ كانَ مَعَهُ واحِدَة فَلَها الثُّلُث ولَهُ الثُّلُثانِ وإنْ انْفَرَدَ حازَ المال ﴿فَإنْ كُنَّ﴾ أيْ الأَوْلاد ﴿نِساء﴾ فَقَطْ ﴿فَوْق اثْنَتَيْنِ فَلَهُنَّ ثُلُثا ما تَرَكَ﴾ المَيِّت وكَذا الِاثْنَتانِ لِأَنَّهُ لِلْأُخْتَيْنِ بِقَوْلِهِ ﴿فَلَهُما الثُّلُثانِ مِمّا تَرَكَ﴾ فَهُما أوْلى ولِأَنَّ البِنْت تَسْتَحِقّ الثُّلُث مَعَ الذَّكَر فَمَعَ الأُنْثى أوْلى (وفَوْق) قِيلَ صِلَة وقِيلَ لِدَفْعِ تَوَهُّم زِيادَة النَّصِيب بِزِيادَةِ العَدَد لِما فُهِمَ اسْتِحْقاق البِنْتَيْنِ الثُّلُثَيْنِ مِن جَعْل الثُّلُث لِلْواحِدَةِ مَعَ الذَّكَر ﴿وإنْ كانَتْ﴾ المَوْلُودَة ﴿واحِدَة﴾ وفِي قِراءَة بِالرَّفْعِ فَكانَ تامَّة ﴿فَلَها النِّصْف ولِأَبَوَيْهِ﴾ أيْ المَيِّت ويُبْدَل مِنهُما ﴿لِكُلِّ واحِد مِنهُما السُّدُس مِمّا تَرَكَ إنْ كانَ لَهُ ولَد﴾ ذَكَر أوْ أُنْثى ونُكْتَة البَدَل إفادَة أنَّهُما لا يَشْتَرِكانِ فِيهِ وأُلْحِق بِالوَلَدِ ولَد الِابْن وبِالأَبِ الجَدّ ﴿فَإنْ لَمْ يَكُنْ لَهُ ولَد ووَرِثَهُ أبَواهُ﴾ فَقَطْ أوْ مَعَ زَوْج ﴿فَلِأُمِّهِ﴾ بِضَمِّ الهَمْزَة وكَسْرها فِرارًا مِن الِانْتِقال مِن ضَمَّة إلى كَسْرَة لِثَقَلِهِ فِي المَوْضِعَيْنِ ﴿الثُّلُث﴾ أيْ ثُلُث المال أوْ ما يَبْقى بَعْد الزَّوْج والباقِي لِلْأَبِ ﴿فَإنْ كانَ لَهُ إخْوَة﴾ أيْ اثْنانِ فَصاعِدًا ذُكُورًا أوْ إناثًا ﴿فَلِأُمِّهِ السُّدُس﴾ والباقِي لِلْأَبِ ولا شَيْء لِلْإخْوَةِ وإرْث مَن ذُكِرَ ما ذُكِرَ ﴿مِن بَعْد﴾ تَنْفِيذ ﴿وصِيَّة يُوصِي﴾ بِالبِناءِ لِلْفاعِلِ والمَفْعُول ﴿بِها أوْ﴾ قَضاء ﴿دَيْن﴾ عَلَيْهِ وتَقْدِيم الوَصِيَّة عَلى الدَّيْن وإنْ كانَتْ مُؤَخَّرَة عَنْهُ فِي الوَفاء لِلِاهْتِمامِ بِها ﴿آباؤُكُمْ وأَبْناؤُكُمْ﴾ مُبْتَدَأ خَبَره ﴿لا تَدْرُونَ أيّهمْ أقْرَب لَكُمْ نَفْعًا﴾ ﴿لا تَدْرُونَ أيّهمْ أقْرَب لَكُمْ نَفْعًا﴾ فِي الدُّنْيا والآخِرَة فَظانّ أنَّ ابْنه أنْفَع لَهُ فَيُعْطِيه المِيراث فَيَكُون الأَب أنْفَع وبِالعَكْسِ وإنَّما العالِم بِذَلِك هُوَ اللَّه فَفَرَضَ لَكُمْ المِيراث ﴿فَرِيضَة مِن اللَّه إنّ اللَّه كانَ عَلِيمًا﴾ بِخَلْقِهِ ﴿حَكِيمًا﴾ فِيما دَبَّرَهُ لَهُمْ: أيْ لَمْ يَزَلْ مُتَّصِفًا بِذَلِكَ"],[12,12,"﴿ولَكُمْ نِصْف ما تَرَكَ أزْواجكُمْ إنْ لَمْ يَكُنْ لَهُنَّ ولَد﴾ مِنكُمْ أوْ مِن غَيْركُمْ ﴿فَإنْ كانَ لَهُنَّ ولَد فَلَكُمْ الرُّبُع مِمّا تَرَكْنَ مِن بَعْد وصِيَّة يُوصِينَ بِها أوْ دَيْن﴾ وأُلْحِق بِالوَلَدِ فِي ذَلِكَ ولَد الِابْن بِالإجْماعِ ﴿ولَهُنَّ﴾ أيْ الزَّوْجات تَعَدَّدْنَ أوَّلًا ﴿الرُّبُع مِمّا تَرَكْتُمْ إنْ لَمْ يَكُنْ لَكُمْ ولَد فَإنْ كانَ لَكُمْ ولَد﴾ مِنهُنَّ أوْ مِن غَيْرهنَّ ﴿فَلَهُنَّ الثُّمُن بِما تَرَكْتُمْ مِن بَعْد وصِيَّة تُوصُونَ بِها أوْ دَيْن﴾ ووَلَد الِابْن فِي ذَلِكَ كالوَلَدِ إجْماعًا ﴿وإنْ كانَ رَجُل يُورَث﴾ صِفَة والخَبَر ﴿كَلالَة﴾ أيْ لا والِد لَهُ ولا ولَد ﴿أوْ امْرَأَة﴾ تُورَث كَلالَة ﴿ولَهُ﴾ أيْ لِلْمُورِثِ كَلالَة ﴿أخ أوْ أُخْت﴾ أيْ مِن أُمّ وقَرَأَ بِهِ ابْن مَسْعُود وغَيْره ﴿فَلِكُلِّ واحِد مِنهُما السُّدُس﴾ مِمّا تَرَكَ ﴿فَإنْ كانُوا﴾ أيْ الإخْوَة والأَخَوات مِن الأُمّ ﴿أكْثَر مِن ذَلِكَ﴾ أيْ مِن واحِد ﴿فَهُمْ شُرَكاء فِي الثُّلُث﴾ يَسْتَوِي فِيهِ ذَكَرهمْ وأُنْثاهُمْ ﴿مِن بَعْد وصِيَّة يُوصى بِها أوْ دَيْن غَيْر مُضارّ﴾ حال مِن ضَمِير يُوصى أيْ غَيْر مُدْخِل الضَّرَر عَلى الوَرَثَة بِأَنْ يُوصِي بِأَكْثَر مِن الثُّلُث ﴿وصِيَّة﴾ مَصْدَر مُؤَكِّد ليُوصِيكُمْ ﴿مِن دُون اللَّه واللَّه عَلِيم﴾ بِما دَبَّرَهُ لِخَلْقِهِ مِن الفَرائِض ﴿حَلِيم﴾ بِتَأْخِيرِ العُقُوبَة عَمَّنْ خالَفَهُ وخَصَّتْ السُّنَّة تَوْرِيث مَن ذُكِرَ بِمَن لَيْسَ فِيهِ مانِع مِن قَتْل أوْ اخْتِلاف دِين أوْ رِقّ"],[13,13,"﴿تِلْكَ﴾ الأَحْكام المَذْكُورَة مِن أمْر اليَتامى وما بَعْده ﴿حُدُود اللَّه﴾ شَرائِعه الَّتِي حَدّها لِعِبادِهِ لِيَعْمَلُوا بِها ولا يَتَعَدَّوْها ﴿ومَن يُطِعْ اللَّه ورَسُوله﴾ فِيما حَكَمَ بِهِ ﴿يُدْخِلهُ﴾ بِالياءِ والنُّون التِفاتًا"],[14,14,"﴿ومَن يَعْصِ اللَّه ورَسُوله ويَتَعَدَّ حُدُوده يُدْخِلهُ﴾ بِالوَجْهَيْنِ ﴿نارًا خالِدًا فِيها ولَهُ﴾ فِيها ﴿عَذاب مُهِين﴾ ذُو إهانَة رُوعِيَ فِي الضَّمائِر فِي الآيَتَيْنِ لَفْظ مَن وفِي خالِدِينَ مَعْناها"],[15,15,"﴿واللّاتِي يَأْتِينَ الفاحِشَة﴾ الزِّنا ﴿مِن نِسائِكُمْ فاسْتَشْهِدُوا عَلَيْهِنَّ أرْبَعَة مِنكُمْ﴾ أيْ مِن رِجالكُمْ المُسْلِمِينَ ﴿فَإنْ شَهِدُوا﴾ عَلَيْهِنَّ بِها ﴿فَأَمْسِكُوهُنَّ﴾ احْبِسُوهُنَّ ﴿فِي البُيُوت﴾ وامْنَعُوهُنَّ مِن مُخالَطَة النّاس ﴿حَتّى يَتَوَفّاهُنَّ المَوْت﴾ أيْ مَلائِكَته ﴿أوْ﴾ إلى أنْ ﴿يَجْعَل اللَّه لَهُنَّ سَبِيلًا﴾ طَرِيقًا إلى الخُرُوج مِنها أُمِرُوا بِذَلِكَ أوَّل الإسْلام ثُمَّ جَعَلَ لَهُنَّ سَبِيلًا بِجَلْدِ البِكْر مِائَة وتَغْرِيبها عامًا ورَجْم المُحْصَنَة وفِي الحَدِيث لَمّا بَيَّنَ الحَدّ قالَ (خُذُوا عَنِّي خُذُوا عَنِّي قَدْ جَعَلَ اللَّه لَهُنَّ سَبِيلًا) رَواهُ مُسْلِم"],[16,16,"﴿واللَّذانِ﴾ بِتَخْفِيفِ النُّون وتَشْدِيدها ﴿يَأْتِيانِها﴾ أيْ الفاحِشَة الزِّنا أوْ اللِّواط ﴿مِنكُمْ﴾ أيْ الرِّجال ﴿فَآذُوهُما﴾ بِالسَّبِّ والضَّرْب بِالنِّعالِ، ﴿فَإنْ تابا﴾ مِنها ﴿وأَصْلَحا﴾ العَمَل ﴿فَأَعْرِضُوا عَنْهُما﴾ ولا تُؤْذُوهُما ﴿إنّ اللَّه كانَ تَوّابًا﴾ عَلى مَن تابَ ﴿رَحِيمًا﴾ بِهِ وهَذا مَنسُوخ بِالحَدِّ إنْ أُرِيدَ بِها الزِّنا وكَذا إنْ أُرِيدَ بِها اللِّواط عِنْد الشّافِعِيّ لَكِنَّ المَفْعُول بِهِ لا يُرْجَم عِنْده وإنْ كانَ مُحْصَنًا بَلْ يُجْلَد ويُغَرَّب وإرادَة اللِّواط أظْهَر بِدَلِيلِ تَثْنِيَة الضَّمِير والأَوَّل قالَ أرادَ الزّانِي والزّانِيَة ويَرُدّهُ تَبْيِينهما بِمَن المُتَّصِلَة بِضَمِيرِ الرِّجال واشْتِراكهما فِي الأَذى والتَّوْبَة والإعْراض وهُوَ مَخْصُوص بِالرِّجالِ لِما تَقَدَّمَ فِي النِّساء فِي الحَبْس"],[17,17,"﴿إنّما التَّوْبَة عَلى اللَّه﴾ أيْ الَّتِي كَتَبَ عَلى نَفْسه قَبُولها بِفَضْلِهِ ﴿لِلَّذِينَ يَعْمَلُونَ السُّوء﴾ المَعْصِيَة ﴿بِجَهالَةٍ﴾ حال أيْ جاهِلِينَ إذا عَصَوْا رَبّهمْ ﴿ثُمَّ يَتُوبُونَ مِن﴾ زَمَن ﴿قَرِيب﴾ قَبْل أنْ يُغَرْغِرُوا ﴿فَأُولَئِكَ يَتُوب اللَّه عَلَيْهِمْ﴾ يَقْبَل تَوْبَتهمْ ﴿وكانَ اللَّه عَلِيمًا﴾ بِخَلْقِهِ ﴿حَكِيمًا﴾ فِي صُنْعه بِهِمْ"],[18,18,"﴿ولَيْسَتْ التَّوْبَة لِلَّذِينَ يَعْمَلُونَ السَّيِّئات﴾ الذُّنُوب ﴿حَتّى إذا حَضَرَ أحَدهمْ المَوْت﴾ وأَخَذَ فِي النَّزْع ﴿قالَ﴾ عِنْد مُشاهَدَة ما هُوَ فِيهِ ﴿إنِّي تُبْت الآن﴾ فَلا يَنْفَعهُ ذَلِكَ ولا يُقْبَل مِنهُ ﴿ولا الَّذِينَ يَمُوتُونَ وهُمْ كُفّار﴾ إذا تابُوا فِي الآخِرَة عِنْد مُعايَنَة العَذاب لا تُقْبَل مِنهُمْ ﴿أُولَئِكَ أعْتَدْنا﴾ أعْدَدْنا ﴿لَهُمْ عَذابًا ألِيمًا﴾ مُؤْلِمًا"],[19,19,"﴿يا أيّها الَّذِينَ آمَنُوا لا يَحِلّ لَكُمْ أنْ تَرِثُوا النِّساء﴾ أيْ ذاتهنَّ ﴿كَرْهًا﴾ بِالفَتْحِ والضَّمّ لُغَتانِ أيْ مُكْرِهِيهِنَّ عَلى ذَلِكَ كانُوا فِي الجاهِلِيَّة يَرِثُونَ نِساء أقْرِبائِهِمْ فَإنْ شاءُوا تَزَوَّجُوهُنَّ بِلا صَداق أوْ زَوَّجُوهُنَّ وأَخَذُوا صَداقهنَّ أوْ عَضَلُوهُنَّ حَتّى يَفْتَدِينَ بِما ورِثْنَهُ أوْ يَمُتْنَ فَيَرِثُوهُنَّ فَنُهُوا عَنْ ذَلِكَ ﴿ولا﴾ أنْ ﴿تَعْضُلُوهُنَّ﴾ أيْ تَمْنَعُوا أزْواجكُمْ عَنْ نِكاح غَيْركُمْ بِإمْساكِهِنَّ ولا رَغْبَة لَكُمْ فِيهِنَّ ضِرارًا ﴿لِتَذْهَبُوا بِبَعْضِ ما آتَيْتُمُوهُنَّ﴾ مِن المَهْر ﴿إلّا أنْ يَأْتِينَ بِفاحِشَةٍ مُبَيِّنَة﴾ بِفَتْحِ الياء وكَسْرها أيْ بَيَّنَتْ أوْ هِيَ بَيِّنَة أيْ زِنًا أوْ نُشُوز فَلَكُمْ أنْ تُضارُّوهُنَّ حَتّى يَفْتَدِينَ مِنكُمْ ويَخْتَلِعْن ﴿وعاشِرُوهُنَّ بِالمَعْرُوفِ﴾ أيْ بِالإجْمالِ فِي القَوْل والنَّفَقَة والمَبِيت ﴿فَإنْ كَرِهْتُمُوهُنَّ﴾ فاصْبِرُوا ﴿فَعَسى أنْ تَكْرَهُوا شَيْئًا ويَجْعَل اللَّه فِيهِ خَيْرًا كَثِيرًا﴾ ولَعَلَّهُ يَجْعَل فِيهِنَّ ذَلِكَ بِأَنْ يَرْزُقكُمْ مِنهُنَّ ولَدًا صالِحًا"],[20,20,"﴿وإنْ أرَدْتُمْ اسْتِبْدال زَوْج مَكان زَوْج﴾ أيْ أخْذها بَدَلها بِأَنْ طَلَّقْتُمُوها ﴿و﴾ قَدْ ﴿آتَيْتُمْ إحْداهُنَّ﴾ أيْ الزَّوْجات ﴿قِنْطارًا﴾ مالًا كَثِيرًا صَداقًا ﴿فَلا تَأْخُذُوا مِنهُ شَيْئًا أتَأْخُذُونَهُ بُهْتانًا﴾ ظُلْمًا ﴿وإثْمًا مُبِينًا﴾ بَيِّنًا ونَصْبهما عَلى الحال، والِاسْتِفْهام لِلتَّوْبِيخِ ولِلْإنْكارِ فِي قَوْله:"],[21,21,"﴿وكَيْفَ تَأْخُذُونَهُ﴾ أيْ بِأَيِّ وجْه ﴿وقَدْ أفْضى﴾ وصَلَ ﴿بَعْضكُمْ إلى بَعْض﴾ بِالجِماعِ المُقَرِّر لِلْمَهْرِ ﴿وأَخَذْنَ مِنكُمْ مِيثاقًا﴾ عَهْدًا ﴿غَلِيظًا﴾ شَدِيدًا وهُوَ ما أمَرَ اللَّه بِهِ مِن إمْساكهنَّ بِمَعْرُوفٍ أوْ تَسْرِيحهنَّ بِإحْسانٍ"],[22,22,"﴿ولا تَنْكِحُوا ما﴾ بِمَعْنى مَن ﴿نَكَحَ آباؤُكُمْ مِن النِّساء إلّا﴾ لَكِنْ ﴿ما قَدْ سَلَفَ﴾ مِن فِعْلكُمْ ذَلِكَ فَإنَّهُ مَعْفُوّ عَنْهُ ﴿إنّهُ﴾ أيْ نِكاحهنَّ ﴿كانَ فاحِشَة﴾ قَبِيحًا ﴿ومَقْتًا﴾ سَبَبًا لِلْمَقْتِ مِن اللَّه وهُوَ أشَدّ البُغْض ﴿وساءَ﴾ بِئْسَ ﴿سَبِيلًا﴾ طَرِيقًا ذَلِكَ"],[23,23,"﴿حُرِّمَتْ عَلَيْكُمْ أُمَّهاتكُمْ﴾ أنْ تَنْكِحُوهُنَّ وشَمِلَتْ الجَدّات مِن قِبَل الأَب أوْ الأُمّ ﴿وبَناتكُمْ﴾ وشَمِلَتْ بَنات الأَوْلاد وإنْ سَفَلْنَ ﴿وأَخَواتكُمْ﴾ مِن جِهَة الأَب أوْ الأُمّ ﴿وعَمّاتكُمْ﴾ أيْ أخَوات آبائِكُمْ وأَجْدادكُمْ ﴿وخالاتكُمْ﴾ أيْ أخَوات أُمَّهاتكُمْ وجَدّاتكُمْ ﴿وبَنات الأَخ وبَنات الأُخْت﴾ ويَدْخُل فِيهِنَّ أوْلادهمْ ﴿وأُمَّهاتكُمْ اللّاتِي أرْضَعْنَكُمْ﴾ قَبْل اسْتِكْمال الحَوْلَيْنِ خَمْس رَضَعات كَما بَيَّنَهُ الحَدِيث ﴿وأَخَواتكُمْ مِن الرَّضاعَة﴾ ويُلْحَق بِذَلِكَ بِالسُّنَّةِ البَنات مِنها وهُنَّ مَن أرْضَعَتْهُمْ مَوْطُوءَته والعَمّات والخالات وبَنات الأَخ وبَنات الأُخْت مِنها لِحَدِيثِ (يَحْرُم مِن الرَّضاع ما يَحْرُم مِن النَّسَب) رَواهُ البُخارِيّ ومُسْلِم ﴿وأُمَّهات نِسائِكُمْ ورَبائِبكُمْ﴾ جَمْع رَبِيبَة وهِيَ بِنْت الزَّوْجَة مِن غَيْره ﴿اللّاتِي فِي حُجُوركُمْ﴾ تُرَبُّونَهُنَّ صِفَة مُوافِقَة لِلْغالِبِ فَلا مَفْهُوم لَها ﴿مِن نِسائِكُمْ اللّاتِي دَخَلْتُمْ بِهِنَّ﴾ أيْ جامَعْتُمُوهُنَّ ﴿فَإنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلا جُناح عَلَيْكُمْ﴾ فِي نِكاح بَناتهنَّ إذا فارَقْتُمُوهُنَّ ﴿وحَلائِل﴾ أزْواج ﴿أبْنائِكُمْ الَّذِينَ مِن أصْلابكُمْ﴾ بِخِلافِ مَن تَبَنَّيْتُمُوهُمْ فَلَكُمْ نِكاح حَلائِلهمْ ﴿وأَنْ تَجْمَعُوا بَيْن الأُخْتَيْنِ﴾ مِن نَسَب أوْ رَضاع بِالنِّكاحِ ويُلْحَق بِهِما بِالسُّنَّةِ الجَمْع بَيْنها وبَيْن عَمَّتها أوْ خالَتها ويَجُوز نِكاح كُلّ واحِدَة عَلى الِانْفِراد ومِلْكهما مَعًا ويَطَأ واحِدَة ﴿إلّا﴾ لَكِنْ ﴿ما قَدْ سَلَفَ﴾ فِي الجاهِلِيَّة مِن نِكاحهمْ بَعْض ما ذُكِرَ فَلا جُناح عَلَيْكُمْ فِيهِ ﴿إنّ اللَّه كانَ غَفُورًا﴾ لِما سَلَفَ مِنكُمْ قَبْل النَّهْي ﴿رَحِيمًا﴾ بِكُمْ فِي ذَلِكَ"],[24,24,"﴿و﴾ حُرِّمَتْ عَلَيْكُمْ ﴿المُحْصَنات﴾ أيْ ذَوات الأَزْواج ﴿مِن النِّساء﴾ أنْ تَنْكِحُوهُنَّ قَبْل مُفارَقَة أزْواجهنَّ حَرائِر مُسْلِمات كُنَّ أوْ لا ﴿إلّا ما مَلَكَتْ أيْمانكُمْ﴾ مِن الإماء بِالسَّبْيِ فَلَكُمْ وطْؤُهُنَّ وإنْ كانَ لَهُنَّ أزْواج فِي دار الحَرْب بَعْد الِاسْتِبْراء ﴿كِتاب اللَّه﴾ نُصِبَ عَلى المَصْدَر أيْ كَتَبَ ذَلِكَ ﴿عَلَيْكُمْ وأُحِلَّ﴾ بِالبِناءِ لِلْفاعِلِ والمَفْعُول ﴿لَكُمْ ما وراء ذَلِكُمْ﴾ أيْ سِوى ما حُرِّمَ عَلَيْكُمْ مِن النِّساء ﴿أنْ تَبْتَغُوا﴾ تَطْلُبُوا النِّساء ﴿بِأَمْوالِكُمْ﴾ بِصَداقٍ أوْ ثَمَن ﴿مُحْصِنِينَ﴾ مُتَزَوِّجِينَ ﴿غَيْر مُسافِحِينَ﴾ زانِينَ ﴿فَما﴾ فَمَن ﴿اسْتَمْتَعْتُمْ﴾ تَمَتَّعْتُمْ ﴿بِهِ مِنهُنَّ﴾ مِمَّنْ تَزَوَّجْتُمْ بِالوَطْءِ ﴿فَآتُوهُنَّ أُجُورهنَّ﴾ مُهُورهنَّ الَّتِي فَرَضْتُمْ لَهُنَّ ﴿فَرِيضَة ولا جُناح عَلَيْكُمْ فِيما تَراضَيْتُمْ﴾ أنْتُمْ وهُنَّ ﴿بِهِ مِن بَعْد الفَرِيضَة﴾ مِن حَطّها أوْ بَعْضها أوْ زِيادَة عَلَيْها ﴿إنّ اللَّه كانَ عَلِيمًا﴾ بِخَلْقِهِ ﴿حَكِيمًا﴾ فِيما دَبَّرَهُ لَهُمْ"],[25,25,"﴿ومَن لَمْ يَسْتَطِعْ مِنكُمْ طَوْلًا﴾ أيْ غِنًى ﴿أنْ يَنْكِح المُحْصَنات﴾ الحَرائِر ﴿المُؤْمِنات﴾ هُوَ جَرْي عَلى الغالِب فَلا مَفْهُوم لَهُ ﴿فَمِن ما مَلَكَتْ أيْمانكُمْ﴾ يَنْكِح ﴿مِن فَتَياتكُمْ المُؤْمِنات واللَّه أعْلَم بِإيمانِكُمْ﴾ فاكْتَفُوا بِظاهِرِهِ وكِلُوا السَّرائِر إلَيْهِ فَإنَّهُ العالِم بِتَفْضِيلِها ورُبّ أمَة تَفْضُل حُرَّة فِيهِ وهَذا تَأْنِيس بِنِكاحِ الإماء ﴿بَعْضكُمْ مِن بَعْض﴾ أيْ أنْتُمْ وهُنَّ سَواء فِي الدِّين فَلا تَسْتَنْكِفُوا مِن نِكاحهنَّ ﴿فانْكِحُوهُنَّ بِإذْنِ أهْلهنَّ﴾ مَوالِيهنَّ ﴿وآتُوهُنَّ﴾ أعْطُوهُنَّ ﴿أُجُورهنَّ﴾ مُهُورهنَّ ﴿بِالمَعْرُوفِ﴾ مِن غَيْر مَطْل ونَقْص ﴿مُحْصَنات﴾ عَفائِف حال ﴿غَيْر مُسافِحات﴾ زانِيات جَهْرًا ﴿ولا مُتَّخِذات أخْدان﴾ أخِلّاء يَزْنُونَ بِهِنَّ سِرًّا ﴿فَإذا أُحْصِنَّ﴾ زُوِّجْنَ وفِي قِراءَة بِالبِناءِ لِلْفاعِلِ تَزَوَّجْنَ ﴿فَإنْ أتَيْنَ بِفاحِشَةٍ﴾ زِنًا ﴿فَعَلَيْهِنَّ نِصْف ما عَلى المُحْصَنات﴾ الحَرائِر الأَبْكار إذا زَنَيْنَ ﴿مِن العَذاب﴾ الحَدّ فَيُجْلَدْنَ خَمْسِينَ ويُغَرَّبْنَ نِصْف سَنَة ويُقاس عَلَيْهِنَّ العَبِيد ولَمْ يَجْعَل الإحْصان شَرْطًا لِوُجُوبِ الحَدّ لِإفادَةِ أنَّهُ لا رَجْم عَلَيْهِنَّ أصْلًا ﴿ذَلِكَ﴾ أيْ نِكاح المَمْلُوكات عِنْد عَدَم الطَّوْل ﴿لِمَن خَشِيَ﴾ خافَ ﴿العَنَت﴾ الزِّنا وأَصْله المَشَقَّة سُمِّيَ بِهِ الزِّنا لِأَنَّهُ سَبَبها بِالحَدِّ فِي الدُّنْيا والعُقُوبَة فِي الآخِرَة ﴿مِنكُمْ﴾ بِخِلافِ مَن لا يَخافهُ مِن الأَحْرار فَلا يَحِلّ لَهُ نِكاحها وكَذا مَن اسْتَطاعَ طَوْل حُرَّة وعَلَيْهِ الشّافِعِيّ وخَرَجَ بِقَوْلِهِ ﴿مِن فَتَياتكُمْ المُؤْمِنات﴾ الكافِرات: فَلا يَحِلّ لَهُ نِكاحها ولَوْ عَدِمَ وخافَ ﴿وأَنْ تَصْبِرُوا﴾ عَنْ نِكاح المَمْلُوكات ﴿خَيْر لَكُمْ﴾ لِئَلّا يَصِير الوَلَد رَقِيقًا ﴿واللَّه غَفُور رَحِيم﴾ بِالتَّوْسِعَةِ فِي ذَلِكَ"],[26,26,"﴿يُرِيد اللَّه لِيُبَيِّن لَكُمْ﴾ شَرائِع دِينكُمْ ومَصالِح أمْركُمْ ﴿ويَهْدِيكُمْ سُنَن﴾ طَرائِق ﴿الَّذِينَ مِن قَبْلكُمْ﴾ مِن الأَنْبِياء فِي التَّحْلِيل والتَّحْرِيم فَتَتَّبِعُوهُمْ ﴿ويَتُوب عَلَيْكُمْ﴾ يَرْجِع بِكُمْ عَنْ مَعْصِيَته الَّتِي كُنْتُمْ عَلَيْها إلى طاعَته ﴿واللَّه عَلِيم﴾ بِكُمْ ﴿حَكِيم﴾ فِيما دَبَّرَهُ لَكُمْ"],[27,27,"﴿واللَّه يُرِيد أنْ يَتُوب عَلَيْكُمْ﴾ كَرَّرَهُ لِيَبْنِيَ عَلَيْهِ ﴿ويُرِيد الَّذِينَ يَتَّبِعُونَ الشَّهَوات﴾ اليَهُود والنَّصارى أوْ المَجُوس أوْ الزُّناة ﴿أنْ تَمِيلُوا مَيْلًا عَظِيمًا﴾ تَعْدِلُوا عَنْ الحَقّ بِارْتِكابِ ما حُرِّمَ عَلَيْكُمْ فَتَكُونُوا مِثْلهمْ"],[28,28,"﴿يُرِيد اللَّه أنْ يُخَفِّف عَنْكُمْ﴾ يُسَهِّل عَلَيْكُمْ أحْكام الشَّرْع ﴿وخُلِقَ الإنْسان ضَعِيفًا﴾ لا يَصْبِر عَنْ النِّساء والشَّهَوات"],[29,29,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَأْكُلُوا أمْوالكُمْ بَيْنكُمْ بِالباطِلِ﴾ بِالحَرامِ فِي الشَّرْع كالرِّبا والغَصْب ﴿إلّا﴾ لَكِنْ ﴿أنْ تَكُون﴾ تَقَع ﴿تِجارَة﴾ وفِي قِراءَة بِالنَّصْبِ أنْ تَكُون الأَمْوال أمْوال تِجارَة صادِرَة ﴿عَنْ تَراضٍ مِنكُمْ﴾ وطِيب نَفْس فَلَكُمْ أنْ تَأْكُلُوها ﴿ولا تَقْتُلُوا أنْفُسكُمْ﴾ بِارْتِكابِ ما يُؤَدِّي إلى هَلاكها أيًّا كانَ فِي الدُّنْيا أوْ الآخِرَة بِقَرِينَةِ ﴿إنّ اللَّه كانَ بِكُمْ رَحِيمًا﴾ فِي مَنعه لَكُمْ مِن ذَلِكَ"],[30,30,"﴿ومَن يَفْعَل ذَلِكَ﴾ أيْ ما نُهِيَ عَنْهُ ﴿عُدْوانًا﴾ تَجاوُزًا لِلْحَلالِ حال ﴿وظُلْمًا﴾ تَأْكِيد ﴿فَسَوْفَ نُصْلِيه﴾ نُدْخِلهُ ﴿نارًا﴾ يَحْتَرِق فِيها ﴿وكانَ ذَلِكَ عَلى اللَّه يَسِيرًا﴾ هَيِّنًا"],[31,31,"﴿إنْ تَجْتَنِبُوا كَبائِر ما تُنْهَوْنَ عَنْهُ﴾ وهِيَ ما ورَدَ عَلَيْها وعِيد كالقَتْلِ والزِّنا والسَّرِقَة وعَنْ ابْن عَبّاس هِيَ إلى السَّبْعمِائَةِ أقْرَب ﴿نُكَفِّر عَنْكُمْ سَيِّئاتكُمْ﴾ الصَّغائِر بِالطّاعاتِ ﴿ونُدْخِلكُمْ مُدْخَلًا﴾ بِضَمِّ المِيم وفَتْحها أيْ إدْخالًا أوْ مَوْضِعًا ﴿كَرِيمًا﴾ هُوَ الجَنَّة"],[32,32,"﴿ولا تَتَمَنَّوْا ما فَضَّلَ اللَّه بِهِ بَعْضكُمْ عَلى بَعْض﴾ مِن جِهَة الدُّنْيا أوْ الدِّين لِئَلّا يُؤَدِّي إلى التَّحاسُد والتَّباغُض ﴿لِلرِّجالِ نَصِيب﴾ ثَواب ﴿مِمّا اكْتَسَبُوا﴾ بِسَبَبِ ما عَمِلُوا مِن الجِهاد وغَيْره ﴿ولِلنِّساءِ نَصِيب مِمّا اكْتَسَبْنَ﴾ مِن طاعَة أزْواجهنَّ وحِفْظ فُرُوجهنَّ نَزَلَتْ لَمّا قالَتْ أُمّ سَلَمَة: لَيْتَنا كُنّا رِجالًا فَجاهَدْنا وكانَ لَنا مِثْل أجْر الرِّجال ﴿وسَأَلُوا﴾ بِهَمْزَةٍ ودُونها ﴿اللَّه مِن فَضْله﴾ ما احْتَجْتُمْ إلَيْهِ يُعْطِكُمْ ﴿إنّ اللَّه كانَ بِكُلِّ شَيْء عَلِيمًا﴾ ومِنهُ مَحَلّ الفَضْل وسُؤالكُمْ"],[33,33,"﴿ولِكُلٍّ﴾ مِن الرِّجال والنِّساء ﴿جَعَلْنا مَوالِي﴾ عَصَبَة يُعْطَوْنَ ﴿مِمّا تَرَكَ الوالِدانِ والأَقْرَبُونَ﴾ لَهُمْ مِن المال ﴿والَّذِينَ عَقَدَتْ﴾ بِأَلِفٍ ودُونها ﴿أيْمانكُمْ﴾ جَمْع يَمِين بِمَعْنى القَسْم أوْ اليَد أيْ الحُلَفاء الَّذِينَ عاهَدْتُمُوهُمْ فِي الجاهِلِيَّة عَلى النُّصْرَة والإرْث ﴿فَآتُوهُمْ﴾ الآن ﴿نَصِيبهمْ﴾ حُظُوظهمْ مِن المِيراث وهُوَ السُّدُس ﴿إنّ اللَّه كانَ عَلى كُلّ شَيْء شَهِيدًا﴾ مُطَلِّعًا ومِنهُ حالكُمْ وهَذا مَنسُوخ بِقَوْلِهِ ﴿وأُولُو الأَرْحام بَعْضهمْ أوْلى بِبَعْضٍ﴾"],[34,34,"﴿الرِّجال قَوّامُونَ﴾ مُسَلَّطُونَ ﴿عَلى النِّساء﴾ يُؤَدِّبُونَهُنَّ ويَأْخُذُونَ عَلى أيْدِيهنَّ ﴿بِما فَضَّلَ اللَّه بَعْضهمْ عَلى بَعْض﴾ أيْ بِتَفْضِيلِهِ لَهُمْ عَلَيْهِنَّ بِالعِلْمِ والعَقْل والوِلايَة وغَيْر ذَلِكَ ﴿وبِما أنْفَقُوا﴾ عَلَيْهِنَّ ﴿مِن أمْوالهمْ فالصّالِحات﴾ مِنهُنَّ ﴿قانِتات﴾ مُطِيعات لِأَزْواجِهِنَّ ﴿حافِظات لِلْغَيْبِ﴾ أيْ لِفُرُوجِهِنَّ وغَيْرها فِي غَيْبَة أزْواجهنَّ ﴿بِما حَفِظَ﴾ لَهُنَّ ﴿اللَّه﴾ حَيْثُ أوْصى عَلَيْهِنَّ الأَزْواج ﴿واللّاتِي تَخافُونَ نُشُوزهنَّ﴾ عِصْيانهنَّ لَكُمْ بِأَنْ ظَهَرَتْ أمارَته ﴿فَعِظُوهُنَّ﴾ فَخَوِّفُوهُنَّ اللَّه ﴿واهْجُرُوهُنَّ فِي المَضاجِع﴾ اعْتَزِلُوا إلى فِراش آخَر إنْ أظْهَرْنَ النُّشُوز ﴿واضْرِبُوهُنَّ﴾ ضَرْبًا غَيْر مُبْرِّح إنْ لَمْ يَرْجِعْنَ بِالهِجْرانِ ﴿فَإنْ أطَعْنَكُمْ﴾ فِيما يُراد مِنهُنَّ ﴿فَلا تَبْغُوا﴾ تَطْلُبُوا ﴿عَلَيْهِنَّ سَبِيلًا﴾ طَرِيقًا إلى ضَرْبهنَّ ظُلْمًا ﴿إنّ اللَّه كانَ عَلِيًّا كَبِيرًا﴾ فاحْذَرُوهُ أنْ يُعاقِبكُمْ إنْ ظَلَمْتُمُوهُنَّ"],[35,35,"﴿وإنْ خِفْتُمْ﴾ عَلِمْتُمْ ﴿شِقاق﴾ خِلاف ﴿بَيْنهما﴾ بَيْن الزَّوْجَيْنِ والإضافَة لِلِاتِّساعِ أيْ شِقاقًا بَيْنهما ﴿فابْعَثُوا﴾ إلَيْهِما بِرِضاهُما ﴿حَكَمًا﴾ رَجُلًا عَدْلًا ﴿مِن أهْله﴾ أقارِبه ﴿وحَكَمًا مِن أهْلها﴾ ويُوَكِّل الزَّوْج حُكْمه فِي طَلاق وقَبُول عِوَض عَلَيْهِ وتُوَكِّل هِيَ حُكْمها فِي الِاخْتِلاع فَيَجْتَهِدانِ ويَأْمُرانِ الظّالِم بِالرُّجُوعِ أوْ يُفَرِّقانِ إنْ رَأَياهُ قالَ تَعالى ﴿إنْ يُرِيدا﴾ أيْ الحَكَمانِ ﴿إصْلاحًا يُوَفِّق اللَّه بَيْنهما﴾ بَيْن الزَّوْجَيْنِ أيْ يُقْدِرهُما عَلى ما هُوَ الطّاعَة مِن إصْلاح أوْ فِراق ﴿إنّ اللَّه كانَ عَلِيمًا﴾ بِكُلِّ شَيْء ﴿خَبِيرًا﴾ بِالبَواطِنِ كالظَّواهِرِ"],[36,36,"﴿واعْبُدُوا اللَّه﴾ وحِّدُوهُ ﴿ولا تُشْرِكُوا بِهِ شَيْئًا﴾ أحْسِنُوا ﴿وبِالوالِدَيْنِ إحْسانًا﴾ بَرًّا ولِين جانِب ﴿وبِذِي القُرْبى﴾ القَرابَة ﴿واليَتامى والمَساكِين والجار ذِي القُرْبى﴾ القَرِيب مِنك فِي الجِوار أوْ النَّسَب ﴿والجار الجُنُب﴾ البَعِيد عَنْك فِي الجِوار أوْ النَّسَب ﴿والصّاحِب بِالجَنْبِ﴾ الرَّفِيق فِي السَّفَر أوْ صِناعَة وقِيلَ الزَّوْجَة ﴿وابْن السَّبِيل﴾ المُنْقَطِع فِي سَفَره ﴿وما مَلَكَتْ أيْمانكُمْ﴾ مِن الأَرِقّاء ﴿إنّ اللَّه لا يُحِبّ مَن كانَ مُخْتالًا﴾ مُتَكَبِّرًا ﴿فَخُورًا﴾ عَلى النّاس بِما أُوتِيَ"],[37,37,"﴿الَّذِينَ﴾ مُبْتَدَأ ﴿يَبْخَلُونَ﴾ بِما يَجِب عَلَيْهِمْ ﴿ويَأْمُرُونَ النّاس بِالبُخْلِ﴾ بِهِ ﴿ويَكْتُمُونَ ما آتاهُمْ اللَّه مِن فَضْله﴾ مِن العِلْم والمال وهُمْ اليَهُود وخَبَر المُبْتَدَأ لَهُمْ وعِيد شَدِيد ﴿وأَعْتَدْنا لِلْكافِرِينَ﴾ بِذَلِكَ وبِغَيْرِهِ ﴿عَذابًا مُهِينًا﴾ ذا إهانَة"],[38,38,"﴿والَّذِينَ﴾ عُطِفَ عَلى الَّذِينَ قَبْله ﴿يُنْفِقُونَ أمْوالهمْ رِئاء النّاس﴾ مُرائِينَ لَهُمْ ﴿ولا يُؤْمِنُونَ بِاللَّهِ ولا بِاليَوْمِ الآخِر﴾ كالمُنافِقِينَ وأَهْل مَكَّة ﴿ومَن يَكُنْ الشَّيْطان لَهُ قَرِينًا﴾ صاحِبًا يَعْمَل بِأَمْرِهِ كَهَؤُلاءِ ﴿فَساءَ﴾ بِئْسَ ﴿قَرِينًا﴾ هُوَ"],[39,39,"﴿وماذا عَلَيْهِمْ لَوْ آمَنُوا بِاللَّهِ واليَوْم الآخِر وأَنْفَقُوا مِمّا رَزَقَهُمْ اللَّه﴾ أيْ أيّ ضَرَر عَلَيْهِمْ فِي ذَلِكَ والِاسْتِفْهام لِلْإنْكارِ ولَوْ مَصْدَرِيَّة أيْ لا ضَرَر فِيهِ وإنَّما الضَّرَر فِيما هُمْ عَلَيْهِ ﴿وكانَ اللَّه بِهِمْ عَلِيمًا﴾ فَيُجازِيهِمْ بِما عَمِلُوا"],[40,40,"﴿إنّ اللَّه لا يَظْلِم﴾ أحَدًا ﴿مِثْقال﴾ وزْن ﴿ذَرَّة﴾ أصْغَر نَمْلَة بِأَنْ يُنْقِصها مِن حَسَناته أوْ يَزِيدها فِي سَيِّئاته ﴿وإنْ تَكُنْ﴾ الذَّرَّة ﴿حَسَنَة﴾ مِن مُؤْمِن وفِي قِراءَة بِالرَّفْعِ فَكانَ تامَّة ﴿يُضاعِفها﴾ مِن عَشْر إلى أكْثَر مِن سَبْعمِائَةِ وفِي قِراءَة يُضَعِّفها بِالتَّشْدِيدِ ﴿ويُؤْتِ مِن لَدُنْه﴾ مِن عِنْده مَعَ المُضاعَفَة ﴿أجْرًا عَظِيمًا﴾ لا يَقْدِرهُ أحَد"],[41,41,"﴿فَكَيْفَ﴾ حال الكُفّار ﴿إذا جِئْنا مِن كُلّ أُمَّة بِشَهِيدٍ﴾ يَشْهَد عَلَيْها بِعَمَلِها وهُوَ نَبِيّها ﴿وجِئْنا بِك﴾ يا مُحَمَّد"],[42,42,"﴿يَوْمئِذٍ﴾ يَوْم المَجِيء ﴿يَوَدّ الَّذِينَ كَفَرُوا وعَصَوْا الرَّسُول لَوْ﴾ أيْ أنْ ﴿تُسَوّى﴾ بِالبِناءِ لِلْمَفْعُولِ والفاعِل مَعَ حَذْف إحْدى التّاءَيْنِ فِي الأَصْل ومَعَ إدْغامها فِي السِّين أيْ تَتَسَوّى ﴿بِهِمْ الأَرْض﴾ بِأَنْ يَكُونُوا تُرابًا مِثْلها لِعِظَمِ هَوْله كَما فِي آيَة أُخْرى ﴿ويَقُول الكافِر يا لَيْتَنِي كُنْت تُرابًا﴾ ﴿ولا يَكْتُمُونَ اللَّه حَدِيثًا﴾ عَمّا عَمِلُوهُ وفِي وقْت آخَر يَكْتُمُونَهُ ويَقُولُونَ ﴿واللَّه رَبّنا ما كُنّا مُشْرِكِينَ﴾"],[43,43,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَقْرَبُوا الصَّلاة﴾ أيْ لا تُصَلُّوا ﴿وأَنْتُمْ سُكارى﴾ مِن الشَّراب لِأَنَّ سَبَب نُزُولها صَلاة جَماعَة فِي حال سُكْر ﴿حَتّى تَعْلَمُوا ما تَقُولُونَ﴾ بِأَنْ تَصِحُّوا ﴿ولا جُنُبًا﴾ بِإيلاجٍ أوْ إنْزال ونَصْبه عَلى الحال وهُوَ يُطْلَق عَلى المُفْرَد وغَيْره ﴿إلّا عابِرِي﴾ مُجْتازِي ﴿سَبِيل﴾ طَرِيق أيْ مُسافِرِينَ ﴿حَتّى تَغْتَسِلُوا﴾ فَلَكُمْ أنْ تُصَلُّوا، واسْتِثْناء المُسافِر لِأَنَّ لَهُ حُكْمًا آخَر سَيَأْتِي وقِيلَ المُراد النَّهْي عَنْ قُرْبان مَواضِع الصَّلاة أيْ المَساجِد إلّا عُبُورها مِن غَيْر مُكْث ﴿وإنْ كُنْتُمْ مَرْضى﴾ مَرَضًا يَضُرّهُ الماء ﴿أوْ عَلى سَفَر﴾ أيْ مُسافِرِينَ وأَنْتُمْ جُنُب أوْ مُحْدِثُونَ ﴿أوْ جاءَ أحَد مِنكُمْ مِن الغائِط﴾ هُوَ المَكان المُعَدّ لِقَضاءِ الحاجَة أيْ أحْدَث ﴿أوْ لامَسْتُمْ النِّساء﴾ وفِي قِراءَة بِلا ألِف وكِلاهُما بِمَعْنى اللَّمْس هُوَ الجَسّ بِاليَدِ قالَهُ ابْن عُمَر وعَلَيْهِ الشّافِعِيّ وأُلْحِق بِهِ الجَسّ بِباقِي البَشَرَة وعَنْ ابْن عَبّاس هُوَ الجِماع ﴿فَلَمْ تَجِدُوا ماء﴾ تَتَطَهَّرُونَ بِهِ لِلصَّلاةِ بَعْد الطَّلَب والتَّفْتِيش وهُوَ راجِع إلى ما عَدا المَرْضى ﴿فَتَيَمَّمُوا﴾ اقْصِدُوا بَعْد دُخُول الوَقْت ﴿صَعِيدًا طَيِّبًا﴾ تُرابًا طاهِرًا فاضْرِبُوا بِهِ ضَرْبَتَيْنِ ﴿فامْسَحُوا بِوُجُوهِكُمْ وأَيْدِيكُمْ﴾ مَعَ المِرْفَقَيْنِ مِنهُ ومَسَحَ يَتَعَدّى بِنَفْسِهِ وبِالحَرْفِ"],[44,44,"﴿ألَمْ تَرَ إلى الَّذِينَ أُوتُوا نَصِيبًا﴾ حَظًّا ﴿مِن الكِتاب﴾ وهُمْ اليَهُود ﴿يَشْتَرُونَ الضَّلالَة﴾ بِالهُدى ﴿ويُرِيدُونَ أنْ تَضِلُّوا السَّبِيل﴾ تُخْطِئُوا الطَّرِيق الحَقّ لِتَكُونُوا مِثْلهمْ"],[45,45,"﴿واللَّه أعْلَم بِأَعْدائِكُمْ﴾ مِنكُمْ فَيُخْبِركُمْ بِهِمْ لِتَجْتَنِبُوهُمْ ﴿وكَفى بِاللَّهِ ولِيًّا﴾ حافِظًا لَكُمْ مِنهُمْ ﴿وكَفى بِاللَّهِ نَصِيرًا﴾ مانِعًا لَكُمْ مِن كَيْدهمْ"],[46,46,"﴿مِن الَّذِينَ هادُوا﴾ قَوْم ﴿يُحَرِّفُونَ﴾ يُغَيِّرُونَ ﴿الكَلِم﴾ الَّذِي أنْزَلَ اللَّه فِي التَّوْراة مِن نَعْت مُحَمَّد ﷺ ﴿عَنْ مَواضِعه﴾ الَّتِي وُضِعَ عَلَيْها ﴿ويَقُولُونَ﴾ لِلنَّبِيِّ ﷺ إذا أمَرَهُمْ بِشَيْءٍ ﴿سَمِعْنا﴾ قَوْلك ﴿وعَصَيْنا﴾ أمْرك ﴿واسْمَعْ غَيْر مُسْمَع﴾ حال بِمَعْنى الدُّعاء أيْ لا سَمِعْت ﴿و﴾ يَقُولُونَ لَهُ ﴿راعِنا﴾ وقَدْ نُهِيَ عَنْ خِطابه بِها وهِيَ كَلِمَة سَبّ بِلُغَتِهِمْ ﴿لَيًّا﴾ تَحْرِيفًا ﴿بِأَلْسِنَتِهِمْ وطَعْنًا﴾ قَدْحًا ﴿فِي الدِّين﴾ الإسْلام ﴿ولَوْ أنَّهُمْ قالُوا سَمِعْنا وأَطَعْنا﴾ بَدَل وعَصَيْنا ﴿واسْمَعْ﴾ فَقَطْ ﴿وانْظُرْنا﴾ اُنْظُرْ إلَيْنا بَدَل راعِنا ﴿لَكانَ خَيْرًا لَهُمْ﴾ مِمّا قالُوهُ ﴿وأَقْوَم﴾ أعْدَل مِنهُ ﴿ولَكِنْ لَعَنَهُمْ اللَّه﴾ أبْعَدهمْ عَنْ رَحْمَته ﴿بِكُفْرِهِمْ فَلا يُؤْمِنُونَ إلّا قَلِيلًا﴾ مِنهُمْ كَعَبْدِ اللَّه بْن سَلام وأَصْحابه"],[47,47,"﴿يا أيّها الَّذِينَ أُوتُوا الكِتاب آمِنُوا بِما نَزَّلْنا﴾ مِن القُرْآن ﴿مُصَدِّقًا لِما مَعَكُمْ﴾ مِن التَّوْراة ﴿مِن قَبْل أنْ نَطْمِس وُجُوهًا﴾ نَمْحُو ما فِيها مِن العَيْن والأَنْف والحاجِب ﴿فَنَرُدّها عَلى أدْبارها﴾ فَنَجْعَلها كالأَقْفاءِ لَوْحًا واحِدًا ﴿أوْ نَلْعَنهُمْ﴾ نَمْسَخهُمْ قِرَدَة ﴿كَما لَعَنّا﴾ مَسَخْنا ﴿أصْحاب السَّبْت﴾ مِنهُمْ ﴿وكانَ أمْر اللَّه﴾ قَضاؤُهُ ﴿مَفْعُولًا﴾ ولَمّا نَزَلَتْ أسْلَمَ عَبْد اللَّه بْن سَلام فَقِيلَ كانَ وعِيدًا بِشَرْطٍ فَلَمّا أسْلَمَ بَعْضهمْ رُفِعَ وقِيلَ يَكُون طَمْس ومَسْخ قَبْل قِيام السّاعَة\" ﴿﴾"],[48,48,"﴿إنّ اللَّه لا يَغْفِر أنْ يُشْرَك﴾ أيْ الإشْراك ﴿بِهِ ويَغْفِر ما دُون﴾ سِوى ذَلِكَ مِن الذُّنُوب ﴿لِمَن يَشاء﴾ المَغْفِرَة لَهُ بِأَنْ يُدْخِلهُ الجَنَّة بِلا عَذاب ومَن شاءَ عَذَّبَهُ مِن المُؤْمِنِينَ بِذُنُوبِهِ ثُمَّ يُدْخِلهُ الجَنَّة ﴿ومَن يُشْرِك بِاللَّهِ فَقَدْ افْتَرى إثْمًا﴾ ذَنْبًا ﴿عَظِيمًا﴾ كَبِيرًا"],[49,49,"﴿ألَمْ تَرَ إلى الَّذِينَ يُزَكُّونَ أنْفُسهمْ﴾ وهُمْ اليَهُود حَيْثُ قالُوا نَحْنُ أبْناء اللَّه وأَحِبّاؤُهُ أيْ لَيْسَ الأَمْر بِتَزْكِيَتِهِمْ أنْفُسهمْ ﴿بَلْ اللَّه يُزَكِّي﴾ يُطَهِّر ﴿مَن يَشاء﴾ بِالإيمانِ ﴿ولا يُظْلَمُونَ﴾ يُنْقَصُونَ مِن أعْمالهمْ ﴿فَتِيلًا﴾ قَدْر قِشْرَة النَّواة"],[50,50,"﴿اُنْظُرْ﴾ مُتَعَجِّبًا ﴿كَيْفَ يَفْتَرُونَ عَلى اللَّه الكَذِب﴾ بِذَلِكَ ﴿وكَفى بِهِ إثْمًا مُبِينًا﴾ بَيِّنًا"],[51,51,"ونَزَلَ فِي كَعْب بْن الأَشْرَف ونَحْوه مِن عُلَماء اليَهُود لَمّا قَدِمُوا مَكَّة وشاهَدُوا قَتْلى بَدْر وحَرَّضُوا المُشْرِكِينَ عَلى الأَخْذ بِثَأْرِهِمْ ومُحارَبَة النَّبِيّ ﷺ ﴿ألَمْ تَرَ إلى الَّذِينَ أُوتُوا نَصِيبًا مِن الكِتاب يُؤْمِنُونَ بِالجِبْتِ والطّاغُوت﴾ صَنَمانِ لِقُرَيْشٍ، ﴿ويَقُولُونَ لِلَّذِينَ كَفَرُوا﴾ أبِي سُفْيان وأَصْحابه حِين قالُوا لَهُمْ: أنَحْنُ أهْدى سَبِيلًا ونَحْنُ وُلاة البَيْت نَسْقِي الحاجّ ونُقْرِي الضَّيْف ونَفُكّ العانِي ونَفْعَل أمْ مُحَمَّد، وقَدْ خالَفَ دِين آبائِهِ وقَطْع الرَّحِم وفارَقَ الحَرَم؟ ﴿هَؤُلاءِ﴾ أيْ أنْتُمْ ﴿أهْدى مِن الَّذِينَ آمَنُوا سَبِيلًا﴾ أقْوَم طَرِيقًا"],[52,52,"﴿أُولَئِكَ الَّذِينَ لَعَنَهُمْ اللَّه ومَن يَلْعَن﴾ ـه ﴿اللَّه فَلَنْ تَجِد لَهُ نَصِيرًا﴾ مانِعًا مِن عَذابه"],[53,53,"﴿أمْ﴾ بَلْ ﴿لَهُمْ نَصِيب مِن المُلْك﴾ أيْ لَيْسَ لَهُمْ شَيْء مِنهُ ولَوْ كانَ ﴿فَإذًا لا يُؤْتُونَ النّاس نَقِيرًا﴾ أيْ شَيْئًا تافِهًا قَدْر النَّقْرَة فِي ظَهْر النَّواة لِفَرْطِ بُخْلهمْ"],[54,54,"﴿أمْ﴾ بَلْ ﴿يَحْسُدُونَ النّاس﴾ أيْ النَّبِيّ ﷺ ﴿عَلى ما آتاهُمْ اللَّه مِن فَضْله﴾ مِن النُّبُوَّة وكَثْرَة النِّساء أيْ يَتَمَنَّوْنَ زَواله عَنْهُ ويَقُولُونَ لَوْ كانَ نَبِيًّا لاشْتَغَلَ عَنْ النِّساء ﴿فَقَدْ آتَيْنا آل إبْراهِيم﴾ جَدّه كَمُوسى وداوُد وسُلَيْمان ﴿الكِتاب والحِكْمَة﴾ والنُّبُوَّة ﴿وآتَيْناهُمْ مُلْكًا عَظِيمًا﴾ فَكانَ لِداوُدَ تِسْع وتِسْعُونَ امْرَأَة ولِسُلَيْمان ألْف ما بَيْن حُرَّة وسُرِّيَّة"],[55,55,"﴿فَمِنهُمْ مَن آمَنَ بِهِ﴾ بِمُحَمَّدٍ ﷺ ﴿ومِنهُمْ مَن صَدَّ﴾ أعْرَضَ ﴿عَنْهُ﴾ فَلَمْ يُؤْمِن ﴿وكَفى بِجَهَنَّم سَعِيرًا﴾ عَذابًا لِمَن لا يُؤْمِن"],[56,56,"﴿إنّ الَّذِينَ كَفَرُوا بِآياتِنا سَوْف نُصْلِيهِمْ﴾ نُدْخِلهُمْ ﴿نارًا﴾ يَحْتَرِقُونَ فِيها ﴿كُلَّما نَضِجَتْ﴾ احْتَرَقَتْ ﴿جُلُودهمْ بَدَّلْناهُمْ جُلُودًا غَيْرها﴾ بِأَنْ تُعاد إلى حالها الأَوَّل غَيْر مُحْتَرِقَة ﴿لِيَذُوقُوا العَذاب﴾ لِيُقاسُوا شِدَّته ﴿إنّ اللَّه كانَ عَزِيزًا﴾ لا يُعْجِزهُ شَيْء ﴿حَكِيمًا﴾ فِي خَلْقه"],[57,57,"﴿والَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات سَنُدْخِلُهُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها﴾ \"أبدا لهم فيها\" ﴿أزْواج مُطَهَّرَة﴾ مِن الحَيْض وكُلّ قَذَر ﴿ونُدْخِلهُمْ ظِلًّا ظَلِيلًا﴾ دائِمًا لا تَنْسَخهُ شَمْس وهُوَ ظِلّ الجَنَّة"],[58,58,"﴿إنّ اللَّه يَأْمُركُمْ أنْ تُؤَدُّوا الأَمانات﴾ أيْ ما اُؤْتُمِنَ عَلَيْهِ مِن الحُقُوق ﴿إلى أهْلها﴾ نَزَلَتْ لَمّا أخَذَ عَلِيّ رَضِيَ اللَّه عَنْهُ مِفْتاح الكَعْبَة مِن عُثْمان بْن طَلْحَة الحجبي سادِنها قَسْرًا لَمّا قَدِمَ النَّبِيّ ﷺ مَكَّة عام الفَتْح ومَنَعَهُ وقالَ لَوْ عَلِمْت أنَّهُ رَسُول اللَّه لَمْ أمْنَعهُ فَأَمَرَ رَسُول اللَّه ﷺ بِرَدِّهِ إلَيْهِ وقالَ هاكَ خالِدَة تالِدَة فَعَجِبَ مِن ذَلِكَ فَقَرَأَ لَهُ عَلِيّ الآيَة فَأَسْلَمَ وأَعْطاهُ عِنْد مَوْته لِأَخِيهِ شَيْبَة فَبَقِيَ فِي ولَده والآيَة وإنْ ورَدَتْ عَلى سَبَب خاصّ فَعُمُومها مُعْتَبَر بِقَرِينَةِ الجَمْع ﴿وإذا حَكَمْتُمْ بَيْن النّاس﴾ يَأْمُركُمْ ﴿أنْ تَحْكُمُوا بِالعَدْلِ إنّ اللَّه نِعِمّا﴾ فِيهِ إدْغام مِيم نِعْمَ فِي ما النَّكِرَة المَوْصُوفَة أيْ نِعْمَ شَيْئًا ﴿يَعِظكُمْ بِهِ﴾ تَأْدِيَة الأَمانَة والحُكْم بِالعَدْلِ ﴿إنّ اللَّه كانَ سَمِيعًا﴾ لِما يُقال ﴿بَصِيرًا﴾ بِما يُفْعَل"],[59,59,"﴿يا أيّها الَّذِينَ آمَنُوا أطِيعُوا اللَّه وأَطِيعُوا الرَّسُول وأُولِي﴾ أصْحاب ﴿الأَمْر﴾ أيْ الوُلاة ﴿مِنكُمْ﴾ إذا أمَرُوكُمْ بِطاعَةِ اللَّه ورَسُوله ﴿فَإنْ تَنازَعْتُمْ﴾ اخْتَلَفْتُمْ ﴿فِي شَيْء فَرُدُّوهُ إلى اللَّه﴾ أيْ إلى كِتابه ﴿والرَّسُول﴾ مُدَّة حَياته وبَعْده إلى سُنَّته أيْ اكْشِفُوا عَلَيْهِ مِنهُما ﴿إنْ كُنْتُمْ تُؤْمِنُونَ بِاللَّهِ واليَوْم الآخِر ذَلِكَ﴾ أيْ الرَّدّ إلَيْهِما ﴿خَيْر﴾ لَكُمْ مِن التَّنازُع والقَوْل بِالرَّأْيِ ﴿وأَحْسَن تَأْوِيلًا﴾ مَآلًا"],[60,60,"ونَزَلَ لَمّا اخْتَصَمَ يَهُودِيّ ومُنافِق فَدَعا المُنافِق إلى كَعْب بْن الأَشْرَف لِيَحْكُم بَيْنهما ودَعا اليَهُودِيّ إلى النَّبِيّ ﷺ فَأَتَياهُ فَقَضى لِلْيَهُودِيِّ فَلَمْ يَرْضَ المُنافِق وأَتَيا عُمَر فَذَكَر اليَهُودِيّ ذَلِكَ فَقالَ لِلْمُنافِقِ أكَذَلِكَ قالَ نَعَمْ فَقَتَلَهُ ﴿ألَمْ تَرَ إلى الَّذِينَ يَزْعُمُونَ أنَّهُمْ آمَنُوا بِما أُنْزِلَ إلَيْك وما أُنْزِلَ مِن قَبْلك يُرِيدُونَ أنْ يَتَحاكَمُوا إلى الطّاغُوت﴾ الكَثِير الطُّغْيان وهُوَ كَعْب بْن الأَشْرَف ﴿وقَدْ أُمِرُوا أنْ يَكْفُرُوا بِهِ﴾ ولا يُوالُوهُ ﴿ويُرِيد الشَّيْطان أنْ يُضِلّهُمْ ضَلالًا بَعِيدًا﴾ عَنْ الحَقّ"],[61,61,"﴿وإذا قِيلَ لَهُمْ تَعالَوْا إلى ما أنْزَلَ اللَّه﴾ فِي القُرْآن مِن الحُكْم ﴿وإلى الرَّسُول﴾ لِيَحْكُم بَيْنكُمْ ﴿رَأَيْت المُنافِقِينَ يَصُدُّونَ﴾ يَعْرِضُونَ ﴿عَنْك﴾ إلى غَيْرك"],[62,62,"﴿فَكَيْفَ﴾ يَصْنَعُونَ ﴿إذا أصابَتْهُمْ مُصِيبَة﴾ عُقُوبَة ﴿بِما قَدَّمَتْ أيْدِيهمْ﴾ مِن الكُفْر والمَعاصِي أيْ أيَقْدِرُونَ عَلى الإعْراض والفِرار مِنها ؟ لا ﴿ثُمَّ جاءُوك﴾ مَعْطُوف عَلى يَصُدُّونَ ﴿يَحْلِفُونَ بِاللَّهِ إنْ﴾ ما ﴿أرَدْنا﴾ بِالمُحاكَمَةِ إلى غَيْرك ﴿إلّا إحْسانًا﴾ صُلْحًا ﴿وتَوْفِيقًا﴾ تَأْلِيفًا بَيْن الخَصْمَيْنِ بِالتَّقْرِيبِ فِي الحُكْم دُون الحَمْل عَلى مُرّ الحَقّ"],[63,63,"﴿أُولَئِكَ الَّذِينَ يَعْلَم اللَّه ما فِي قُلُوبهمْ﴾ مِن النِّفاق وكَذِبهمْ فِي عُذْرهمْ ﴿فَأَعْرِضْ عَنْهُمْ﴾ بِالصَّفْحِ ﴿وعِظْهُمْ﴾ خَوِّفْهُمْ اللَّه ﴿وقُلْ لَهُمْ فِي﴾ شَأْن ﴿أنْفُسهمْ قَوْلًا بَلِيغًا﴾ مُؤَثِّرًا فِيهِمْ أيْ اُزْجُرْهُمْ لِيَرْجِعُوا عَنْ كُفْرهمْ"],[64,64,"﴿وما أرْسَلْنا مِن رَسُول إلّا لِيُطاعَ﴾ فِيما يَأْمُر بِهِ ويَحْكُم ﴿بِإذْنِ اللَّه﴾ بِأَمْرِهِ لا لِيُعْصى ويُخالَف ﴿ولَوْ أنَّهُمْ إذْ ظَلَمُوا أنْفُسهمْ﴾ بِتَحاكُمِهِمْ إلى الطّاغُوت ﴿جاءُوك﴾ تائِبِينَ ﴿فاسْتَغْفَرُوا اللَّه واسْتَغْفَرَ لَهُمْ الرَّسُول﴾ فِيهِ التِفات عَنْ الخِطاب تَفْخِيمًا لِشَأْنِهِ ﴿لَوَجَدُوا اللَّه تَوّابًا﴾ عَلَيْهِمْ ﴿رَحِيمًا﴾ بِهِمْ"],[65,65,"﴿فَلا ورَبّك﴾ لا زائِدَة ﴿لا يُؤْمِنُونَ حَتّى يُحَكِّمُوك فِيما شَجَرَ﴾ اخْتَلَطَ ﴿بَيْنهمْ ثُمَّ لا يَجِدُوا فِي أنْفُسهمْ حَرَجًا﴾ ضِيقًا أوْ شَكًّا ﴿مِمّا قَضَيْت﴾ بِهِ ﴿ويُسَلِّمُوا﴾ يَنْقادُوا لِحُكْمِك ﴿تَسْلِيمًا﴾ مِن غَيْر مُعارَضَة"],[66,66,"﴿ولَوْ أنّا كَتَبْنا عَلَيْهِمْ أنْ﴾ مُفَسِّرَة ﴿اُقْتُلُوا أنْفُسكُمْ أوْ اُخْرُجُوا مِن دِياركُمْ﴾ كَما كَتَبْنا عَلى بَنِي إسْرائِيل ﴿ما فَعَلُوهُ﴾ أيْ المَكْتُوب عَلَيْهِمْ ﴿إلّا قَلِيل﴾ بِالرَّفْعِ عَلى البَدَل والنَّصْب عَلى الِاسْتِثْناء ﴿مِنهُمْ ولَوْ أنَّهُمْ فَعَلُوا ما يُوعَظُونَ بِهِ﴾ مِن طاعَة الرَّسُول ﷺ ﴿لَكانَ خَيْرًا لَهُمْ وأَشَدّ تَثْبِيتًا﴾ تَحْقِيقًا لِإيمانِهِمْ"],[67,67,"﴿وإذًا﴾ أيْ لَوْ تَثَبَّتُوا ﴿لَآتَيْناهُمْ مِن لَدُنّا﴾ مِن عِنْدنا ﴿أجْرًا عَظِيمًا﴾ هُوَ الجَنَّة"],[68,68,"﴿ولَهَدَيْناهُمْ صِراطًا مُسْتَقِيمًا﴾ قالَ بَعْض الصَّحابَة لِلنَّبِيِّ ﷺ: كَيْفَ نَراك فِي الجَنَّة وأَنْت فِي الدَّرَجات العُلى ونَحْنُ أسْفَل مِنك ؟ فَنَزَلَ"],[69,69,"﴿ومَن يُطِعْ اللَّه والرَّسُول﴾ فِيما أمَرَ بِهِ ﴿فَأُولَئِكَ مَعَ الَّذِينَ أنْعَمَ اللَّه عَلَيْهِمْ مِن النَّبِيِّينَ والصِّدِّيقِينَ﴾ أفاضِل أصْحاب الأَنْبِياء لِمُبالَغَتِهِمْ فِي الصِّدْق والتَّصْدِيق ﴿والشُّهَداء﴾ القَتْلى فِي سَبِيل اللَّه ﴿والصّالِحِينَ﴾ غَيْر مَن ذُكِرَ ﴿وحَسُنَ أُولَئِكَ رَفِيقًا﴾ رُفَقاء فِي الجَنَّة بِأَنْ يَسْتَمْتِع فِيها بِرُؤْيَتِهِمْ وزِيارَتهمْ والحُضُور مَعَهُمْ وإنْ كانَ مَقَرّهمْ فِي الدَّرَجات العالِيَة بِالنِّسْبَةِ إلى غَيْرهمْ"],[70,70,"﴿ذَلِكَ﴾ أيْ كَوْنهمْ مَعَ مَن ذُكِرَ مُبْتَدَأ خَبَره ﴿الفَضْل مِن اللَّه﴾ تَفَضَّلَ بِهِ عَلَيْهِمْ لا أنَّهُمْ نالُوهُ بِطاعَتِهِمْ ﴿وكَفى بِاللَّهِ عَلِيمًا﴾ بِثَوابِ الآخِرَة أيْ فَثِقُوا بِما أخْبَرَكُمْ بِهِ ﴿ولا يُنَبِّئك مِثْل خَبِير﴾"],[71,71,"﴿يا أيّها الَّذِينَ آمَنُوا خُذُوا حِذْركُمْ﴾ مِن عَدُوّكُمْ أيْ احْتَرِزُوا مِنهُ وتَيَقَّظُوا لَهُ ﴿فانْفِرُوا﴾ انْهَضُوا إلى قِتاله ﴿ثُبات﴾ مُتَفَرِّقِينَ سَرِيَّة بَعْد أُخْرى ﴿أوْ انْفِرُوا جَمِيعًا﴾ مُجْتَمِعِينَ"],[72,72,"﴿وإنَّ مِنكُمْ لَمَن لَيُبَطِّئَن﴾ لَيَتَأَخَّرَن عَنْ القِتال كَعَبْدِ اللَّه بْن أُبَيٍّ المُنافِق وأَصْحابه وجَعْله مِنهُمْ مِن حَيْثُ الظّاهِر واللّام فِي الفِعْل لِلْقَسَمِ ﴿فَإنْ أصابَتْكُمْ مُصِيبَة﴾ كَقَتْلٍ وهَزِيمَة ﴿قالَ قَدْ أنْعَمَ اللَّه عَلَيَّ إذْ لَمْ أكُنْ مَعَهُمْ شَهِيدًا﴾ حاضِرًا فَأُصاب"],[73,73,"﴿ولَئِنْ﴾ لام قَسَم ﴿أصابَكُمْ فَضْل مِن اللَّه﴾ كَفَتْحٍ وغَنِيمَة ﴿لَيَقُولَن﴾ نادِمًا ﴿كَأَنْ﴾ مُخَفَّفَة واسْمها مَحْذُوف أيْ كَأَنَّهُ ﴿لَمْ يَكُنْ﴾ بِالياءِ والتّاء ﴿بَيْنكُمْ وبَيْنه مَوَدَّة﴾ مَعْرِفَة وصَداقَة وهَذا راجِع إلى قَوْله قَدْ أنْعَمَ اللَّه عَلَيَّ. اعْتَرَضَ بِهِ بَيْن القَوْل ومَقُوله وهُوَ ﴿يا﴾ لِلتَّنْبِيهِ ﴿لَيْتَنِي كُنْت مَعَهُمْ فَأَفُوز فَوْزًا عَظِيمًا﴾ آخُذ حَظًّا وافِرًا مِن الغَنِيمَة"],[74,74,"﴿فَلْيُقاتِلْ فِي سَبِيل اللَّه﴾ لِإعْلاءِ دِينه ﴿الَّذِينَ يَشْرُونَ﴾ يَبِيعُونَ ﴿الحَياة الدُّنْيا بِالآخِرَةِ ومَن يُقاتِل فِي سَبِيل اللَّه فَيُقْتَل﴾ يُسْتَشْهَد ﴿أوْ يَغْلِب﴾ يَظْفَر بِعَدُوِّهِ ﴿فَسَوْفَ نُؤْتِيه أجْرًا عَظِيمًا﴾ ثَوابًا جَزِيلًا"],[75,75,"﴿ومالَكُمْ لا تُقاتِلُونَ﴾ اسْتِفْهام تَوْبِيخ أيْ لا مانِع لَكُمْ مِن القِتال ﴿فِي سَبِيل اللَّه﴾ وفِي تَخْلِيص ﴿المُسْتَضْعَفِينَ مِن الرِّجال والنِّساء والوِلْدان﴾ الَّذِينَ حَبَسَهُمْ الكُفّار عَنْ الهِجْرَة وآذَوْهُمْ قالَ ابْن عَبّاس رَضِيَ اللَّه عَنْهُما: كُنْت أنا وأُمِّي مِنهُمْ ﴿الَّذِينَ يَقُولُونَ﴾ داعِينَ يا ﴿رَبّنا أخْرِجْنا مِن هَذِهِ القَرْيَة﴾ مَكَّة ﴿الظّالِم أهْلها﴾ بِالكُفْرِ ﴿واجْعَلْ لَنا مِن لَدُنْك﴾ مِن عِنْدك ﴿ولِيًّا﴾ يَتَوَلّى أُمُورنا ﴿واجْعَلْ لَنا مِن لَدُنْك نَصِيرًا﴾ يَمْنَعنا مِنهُمْ وقَدْ اسْتَجابَ اللَّه دُعاءَهُمْ فَيَسَّرَ لِبَعْضِهِمْ الخُرُوج وبَقِيَ بَعْضهمْ إلى أنْ فُتِحَتْ مَكَّة ووَلّى ﷺ عَتّاب بْن أسِيد فَأَنْصَفَ مَظْلُومهمْ مِن ظالِمهمْ"],[76,76,"﴿الَّذِينَ آمَنُوا يُقاتِلُونَ فِي سَبِيل اللَّه والَّذِينَ كَفَرُوا يُقاتِلُونَ فِي سَبِيل الطّاغُوت﴾ الشَّيْطان ﴿فَقاتِلُوا أوْلِياء الشَّيْطان﴾ أنْصار دِينه تَغْلِبُوهُمْ لِقُوَّتِكُمْ بِاللَّهِ ﴿إنّ كَيْد الشَّيْطان﴾ بِالمُؤْمِنِينَ ﴿كانَ ضَعِيفًا﴾ واهِيًا لا يُقاوَم كَيْد اللَّه بِالكافِرِينَ"],[77,77,"﴿ألَمْ تَرَ إلى الَّذِينَ قِيلَ لَهُمْ كُفُّوا أيْدِيكُمْ﴾ عَنْ قِتال الكُفّار لَمّا طَلَبُوهُ بِمَكَّة لِأَذى الكُفّار لَهُمْ وهُمْ جَماعَة مِن الصَّحابَة ﴿وأَقِيمُوا الصَّلاة وآتُوا الزَّكاة فَلَمّا كُتِبَ﴾ فُرِضَ ﴿عَلَيْهِمْ القِتال إذا فَرِيق مِنهُمْ يَخْشَوْنَ﴾ يَخافُونَ ﴿النّاس﴾ الكُفّار أيْ عَذابهمْ بِالقَتْلِ ﴿كَخَشْيَةِ﴾ كَخَشْيَتِهِمْ عَذاب ﴿اللَّه أوْ أشَدّ خَشْيَة﴾ مِن خَشْيَتهمْ لَهُ ونَصْب أشَدّ عَلى الحال وجَواب لِما دَلَّ عَلَيْهِ إذا وما بَعْدها أيْ فاجَأَتْهُمْ الخَشْيَة ﴿وقالُوا﴾ جَزَعًا مِن المَوْت ﴿رَبّنا لِمَ كَتَبْت عَلَيْنا القِتال لَوْلا﴾ هَلّا ﴿أخَّرْتنا إلى أجَل قَرِيب قُلْ﴾ لَهُمْ ﴿مَتاع الدُّنْيا﴾ ما يَتَمَتَّع بِهِ فِيها أوْ الِاسْتِمْتاع بِها ﴿قَلِيل﴾ آيِل إلى الفَناء ﴿والآخِرَة﴾ أيْ الجَنَّة ﴿خَيْر لِمَن اتَّقى﴾ عِقاب اللَّه بِتَرْكِ مَعْصِيَته ﴿ولا تُظْلَمُونَ﴾ بِالتّاءِ والياء تُنْقَصُونَ مِن أعْمالكُمْ ﴿فَتِيلًا﴾ قَدْر قِشْرَة النَّواة فَجاهِدُوا"],[78,78,"﴿أيْنَما تَكُونُوا يُدْرِككُمْ المَوْت ولَوْ كُنْتُمْ فِي بُرُوج﴾ حُصُون ﴿مُشَيَّدَة﴾ مُرْتَفِعَة فَلا تَخْشَوْا القِتال خَوْف المَوْت ﴿وإنْ تُصِبْهُمْ﴾ أيْ اليَهُود ﴿حَسَنَة﴾ خِصْب وسِعَة ﴿يَقُولُوا هَذِهِ مِن عِنْد اللَّه وإنْ تُصِبْهُمْ سَيِّئَة﴾ جَدْب وبَلاء كَما حَصَلَ لَهُمْ عِنْد قُدُوم النَّبِيّ ﷺ المَدِينَة ﴿يَقُولُوا هَذِهِ مِن عِنْدك﴾ يا مُحَمَّد أيْ بِشُؤْمِك ﴿قُلْ﴾ لَهُمْ ﴿كُلّ﴾ مِن الحَسَنَة والسَّيِّئَة ﴿مِن عِنْد اللَّه﴾ مِن قِبَله ﴿لا يَكادُونَ يَفْقُهُونَ﴾ أيْ لا يُقارِبُونَ أنْ يَفْهَمُوا ﴿حَدِيثًا﴾ يُلْقى إلَيْهِمْ وما اسْتِفْهام تَعْجِيب مِن فَرْط جَهْلهمْ ونَفْي مُقارَبَة الفِعْل أشَدّ مِن نَفْيه"],[79,79,"﴿ما أصابَك﴾ أيّها الإنْسان ﴿مِن حَسَنَة﴾ خَيْر ﴿فَمِن اللَّه﴾ أتَتْك فَضْلًا مِنهُ ﴿وما أصابَك مِن سَيِّئَة﴾ بَلِيَّة ﴿فَمِن نَفْسك﴾ أتَتْك حَيْثُ ارْتَكَبْت ما يَسْتَوْجِبها مِن الذُّنُوب ﴿وأَرْسَلْناك﴾ يا مُحَمَّد ﴿لِلنّاسِ رَسُولًا﴾ حال مُؤَكِّدَة ﴿وكَفى بِاللَّهِ شَهِيدًا﴾ عَلى رِسالَتك"],[80,80,"﴿مَن يُطِعْ الرَّسُول فَقَدْ أطاعَ اللَّه ومَن تَوَلّى﴾ أعْرَض عَنْ طاعَتك فَلا يُهِمَّنك ﴿فَما أرْسَلْناك عَلَيْهِمْ حَفِيظًا﴾ حافِظًا لِأَعْمالِهِمْ بَلْ نَذِيرًا وإلَيْنا أمْرهمْ فَنُجازِيهِمْ وهَذا قَبْل الأَمْر بِالقِتالِ"],[81,81,"﴿ويَقُولُونَ﴾ أيْ المُنافِقُونَ إذا جاءُوك أُمِرْنا ﴿طاعَة﴾ لَك ﴿فَإذا بَرَزُوا﴾ خَرَجُوا ﴿مِن عِنْدك بَيَّتَ طائِفَة مِنهُمْ﴾ بِإدْغامِ التّاء فِي الطّاء وتَرْكه أيْ أضْمَرَتْ ﴿غَيْر الَّذِي تَقُول﴾ لَك فِي حُضُورك مِن الطّاعَة أيْ عِصْيانك ﴿واللَّه يَكْتُب﴾ يَأْمُر بِكَتْبِ ﴿ما يُبَيِّتُونَ﴾ فِي صَحائِفهمْ لِيُجازَوْا عَلَيْهِ ﴿فَأَعْرِضْ عَنْهُمْ﴾ بِالصَّفْحِ ﴿وتَوَكَّلْ عَلى اللَّه﴾ ثِقْ بِهِ فَإنَّهُ كافِيك ﴿وكَفى بِاللَّهِ وكِيلًا﴾ مُفَوَّضًا إلَيْهِ"],[82,82,"﴿أفَلا يَتَدَبَّرُونَ﴾ يَتَأَمَّلُونَ ﴿القُرْآن﴾ وما فِيهِ مِن المَعانِي البَدِيعَة ﴿ولَوْ كانَ مِن عِنْد غَيْر اللَّه لَوَجَدُوا فِيهِ اخْتِلافًا كَثِيرًا﴾ تَناقُضًا فِي مَعانِيه وتَبايُنًا فِي نَظْمه"],[83,83,"﴿وإذا جاءَهُمْ أمْر﴾ عَنْ سَرايا النَّبِيّ ﷺ بِما حَصَلَ لَهُمْ ﴿مِن الأَمْن﴾ بِالنَّصْرِ ﴿أوْ الخَوْف﴾ بِالهَزِيمَةِ ﴿أذاعُوا بِهِ﴾ أفْشَوْهُ نَزَلَ فِي جَماعَة مِن المُنافِقِينَ أوْ فِي ضُعَفاء المُؤْمِنِينَ كانُوا يَفْعَلُونَ ذَلِكَ فَتَضْعُف قُلُوب المُؤْمِنِينَ ويَتَأَذّى النَّبِيّ ﴿ولَوْ رَدُّوهُ﴾ أيْ الخَبَر ﴿إلى الرَّسُول وإلى أُولِي الأَمْر مِنهُمْ﴾ أيْ ذَوِي الرَّأْي مِن أكابِر الصَّحابَة أيْ لَوْ سَكَتُوا عَنْهُ حَتّى يُخْبِرُوا بِهِ ﴿لَعَلِمَهُ﴾ هَلْ هُوَ مِمّا يَنْبَغِي أنْ يُذاع أوْ لا ﴿الَّذِينَ يَسْتَنْبِطُونَهُ﴾ يَتَّبِعُونَهُ ويَطْلُبُونَ عِلْمه وهُمْ المُذِيعُونَ ﴿مِنهُمْ﴾ مِن الرَّسُول وأُولِي الأَمْر ﴿ولَوْلا فَضْل اللَّه عَلَيْكُمْ﴾ بِالإسْلامِ ﴿ورَحْمَته﴾ لَكُمْ بِالقُرْآنِ ﴿لاتَّبَعْتُمْ الشَّيْطان﴾ فِيما يَأْمُركُمْ بِهِ مِن الفَواحِش"],[84,84,"﴿فَقاتِل﴾ يا مُحَمَّد ﴿فِي سَبِيل اللَّه لا تُكَلَّف إلّا نَفْسك﴾ فَلا تَهْتَمّ بِتَخَلُّفِهِمْ عَنْك المَعْنى قاتِل ولَوْ وحْدك فَإنَّك مَوْعُود بِالنَّصْرِ ﴿وحَرِّضْ المُؤْمِنِينَ﴾ حُثَّهُمْ عَلى القِتال ورَغِّبْهُمْ فِيهِ ﴿عَسى اللَّه أنْ يَكُفّ بَأْس﴾ حَرْب ﴿الَّذِينَ كَفَرُوا واللَّه أشَدّ بَأْسًا﴾ مِنهُمْ ﴿وأَشَدّ تَنْكِيلًا﴾ تَعْذِيبًا مِنهُمْ فَقالَ رَسُول اللَّه ﷺ (والَّذِي نَفْسِي بِيَدِهِ لَأَخْرُجَن ولَوْ وحْدِي) فَخَرَجَ بِسَبْعِينَ راكِبًا إلى بَدْر الصُّغْرى فَكَفّ اللَّه بَأْس الكُفّار بِإلْقاءِ الرُّعْب فِي قُلُوبهمْ ومَنع أبِي سُفْيان عَنْ الخُرُوج كَما تَقَدَّمَ فِي آل عِمْران"],[85,85,"﴿مَن يَشْفَع﴾ بَيْن النّاس ﴿شَفاعَة حَسَنَة﴾ مُوافِقَة لِلشَّرْعِ ﴿يَكُنْ لَهُ نَصِيب﴾ مِن الأَجْر ﴿مِنها﴾ بِسَبَبِها ﴿ومَن يَشْفَع شَفاعَة سَيِّئَة﴾ مُخالِفَة لَهُ ﴿يَكُنْ لَهُ كِفْل﴾ نَصِيب مِن الوِزْر ﴿مِنها﴾ بِسَبَبِها ﴿وكانَ اللَّه عَلى كُلّ شَيْء مُقِيتًا﴾ مُقْتَدِرًا فَيُجازِي كُلّ أحَد بِما عَمِلَ"],[86,86,"﴿وإذا حُيِّيتُمْ بِتَحِيَّةٍ﴾ كَأَنْ قِيلَ لَكُمْ سَلام عَلَيْكُمْ ﴿فَحَيُّوا﴾ المُحَيِّي ﴿بِأَحْسَن مِنها﴾ بِأَنْ تَقُولُوا لَهُ عَلَيْك السَّلام ورَحْمَة اللَّه وبَرَكاته ﴿أوْ رُدُّوها﴾ بِأَنْ تَقُولُوا لَهُ كَما قالَ أيْ الواجِب أحَدهما والأَوَّل أفْضَل ﴿إنّ اللَّه كانَ عَلى كُلّ شَيْء حَسِيبًا﴾ مُحاسِبًا فَيُجازِي عَلَيْهِ ومِنهُ رَدّ السَّلام وخَصَّتْ السُّنَّة الكافِر والمُبْتَدِع والفاسِق والمُسَلِّم عَلى قاضِي الحاجَة ومَن فِي الحَمّام والآكِل فَلا يَجِب الرَّدّ عَلَيْهِمْ بَلْ يُكْرَه فِي غَيْر الأَخِير ويُقال لِلْكافِرِ وعَلَيْك"],[87,87,"﴿اللَّه لا إلَه إلّا هُوَ﴾ واللَّه ﴿لَيَجْمَعَنكُمْ﴾ مِن قُبُوركُمْ ﴿إلى﴾ فِي ﴿يَوْم القِيامَة لا رَيْب﴾ لا شَكَّ ﴿وفِيهِ مِن﴾ أيْ لا أحَد ﴿أصْدَق مِن اللَّه حَدِيثًا﴾ قَوْلًا"],[88,88,"ولَمّا رَجَعَ ناس مِن أُحُد اخْتَلَفَ النّاس فِيهِمْ فَقالَ فَرِيق اُقْتُلْهُمْ وقالَ فَرِيق: لا فَنَزَلَ: ﴿فَما لَكُمْ﴾ ما شَأْنكُمْ صِرْتُمْ ﴿فِي المُنافِقِينَ فِئَتَيْنِ﴾ فِرْقَتَيْنِ ﴿واللَّه أرْكَسَهُمْ﴾ رَدَّهُمْ ﴿بِما كَسَبُوا﴾ مِن الكُفْر والمَعاصِي ﴿أتُرِيدُونَ أنْ تَهْدُوا مَن أضَلَّ اللَّه ومَن يُضْلِلْ اللَّه﴾ أيْ تَعُدُّوهُمْ مِن جُمْلَة المُهْتَدِينَ والِاسْتِفْهام فِي المَوْضِعَيْنِ لِلْإنْكارِ ﴿فَلَنْ تَجِد لَهُ سَبِيلًا﴾ طَرِيقًا إلى الهُدى"],[89,89,"﴿ودُّوا﴾ تَمَنَّوْا ﴿لَوْ تَكْفُرُونَ كَما كَفَرُوا فَتَكُونُونَ﴾ أنْتُمْ وهُمْ ﴿سَواء﴾ فِي الكُفْر ﴿فَلا تَتَّخِذُوا مِنهُمْ أوْلِياء﴾ تُوالُونَهُمْ وإنْ أظَهَرُوا الإيمان ﴿حَتّى يُهاجِرُوا فِي سَبِيل اللَّه﴾ هِجْرَة صَحِيحَة تُحَقِّق إيمانهمْ ﴿فَإنْ تَوَلَّوْا﴾ وأَقامُوا عَلى ما هُمْ عَلَيْهِ ﴿فَخُذُوهُمْ﴾ بِالأَسْرِ ﴿واقْتُلُوهُمْ حَيْثُ وجَدْتُمُوهُمْ ولا تَتَّخِذُوا مِنهُمْ ولِيًّا﴾ تُوالُونَهُ ﴿ولا نَصِيرًا﴾ تَنْتَصِرُونَ بِهِ عَلى عَدُوّكُمْ"],[90,90,"﴿إلّا الَّذِينَ يَصِلُونَ﴾ يَلْجَئُونَ ﴿إلى قَوْم بَيْنكُمْ وبَيْنهمْ مِيثاق﴾ عَهْد بِالأَمانِ لَهُمْ ولِمَن وصَلَ إلَيْهِمْ كَما عاهَدَ النَّبِيّ صَلّى اللَّه عَلَيْهِ سَلَّمَ هِلال بْن عُوَيْمِر الأَسْلَمِيّ ﴿أوْ﴾ الَّذِينَ ﴿جاءُوكُمْ﴾ وقَدْ ﴿حَصِرَتْ﴾ ضاقَتْ ﴿صُدُورهمْ﴾ عَنْ ﴿أنْ يُقاتِلُوكُمْ﴾ مَعَ قَوْمهمْ ﴿أوْ يُقاتِلُوا قَوْمهمْ﴾ مَعَكُمْ أيْ مُمْسِكِينَ عَنْ قِتالكُمْ وقِتالهمْ فَلا تَتَعَرَّضُوا إلَيْهِمْ بِأَخَذٍ ولا قَتْل وهَذا وما بَعْده مَنسُوخ بِآيَةِ السَّيْف ﴿ولَوْ شاءَ اللَّه﴾ تَسْلِيطهمْ عَلَيْكُمْ ﴿لَسَلَّطَهُمْ عَلَيْكُمْ﴾ بِأَنْ يُقَوِّي قُلُوبهمْ ﴿فَلَقاتَلُوكُمْ﴾ ولَكِنَّهُ لَمْ يَشَأْهُ فَأَلْقى فِي قُلُوبهمْ الرُّعْب ﴿فَإنْ اعْتَزَلُوا فَلَمْ يُقاتِلُوكُمْ وأَلْقَوْا إلَيْكُمْ السَّلَم﴾ الصُّلْح أيْ انْقادُوا ﴿فَما جَعَلَ اللَّه لَكُمْ عَلَيْهِمْ سَبِيلًا﴾ طَرِيقًا بِالأَخْذِ والقَتْل"],[91,91,"﴿سَتَجِدُونَ آخَرِينَ يُرِيدُونَ أنْ يَأْمَنُوكُمْ﴾ بِإظْهارِ الإيمان عِنْدكُمْ ﴿ويَأْمَنُوا قَوْمهمْ﴾ بِالكُفْرِ إذا رَجَعُوا إلَيْهِمْ وهُمْ أسَد وغَطَفان ﴿كُلَّما رُدُّوا إلى الفِتْنَة﴾ دَعَوْا إلى الشِّرْك ﴿أُرْكِسُوا فِيها﴾ وقَعُوا أشَدّ وُقُوع ﴿فَإنْ لَمْ يَعْتَزِلُوكُمْ﴾ بِتَرْكِ قِتالكُمْ ﴿ويُلْقَوْا إلَيْكُمْ السَّلَم﴾ ولَمْ يُلْقَوْا إلَيْكُمْ السَّلَم ﴿ويَكُفُّوا أيْدِيهمْ﴾ ولَمْ يَكُفُّوا أيْدِيهمْ عَنْكُمْ ﴿فَخُذُوهُمْ﴾ بِالأَسْرِ ﴿واقْتُلُوهُمْ حَيْثُ ثَقِفْتُمُوهُمْ﴾ وجَدْتُمُوهُمْ ﴿وأُوْلَئِكُمْ جَعَلْنا لَكُمْ عَلَيْهِمْ سُلْطانًا مُبِينًا﴾ بُرْهانًا بَيِّنًا ظاهِرًا عَلى قَتْلهمْ وسَبْيهمْ لِغَدْرِهِمْ"],[92,92,"﴿وما كانَ لِمُؤْمِنٍ أنْ يَقْتُل مُؤْمِنًا﴾ أيْ ما يَنْبَغِي أنْ يَصْدُر مِنهُ قَتْل لَهُ ﴿إلّا خَطَأ﴾ مُخْطِئًا فِي قَتْله مِن غَيْر قَصْد ﴿ومَن قَتَلَ مُؤْمِنًا خَطَأ﴾ بِأَنْ قَصَدَ رَمْي غَيْره كَصَيْدٍ أوْ شَجَرَة فَأَصابَهُ أوْ ضَرَبَهُ بِما لا يَقْتُل غالِبًا ﴿فَتَحْرِير﴾ عِتْق ﴿رَقَبَة﴾ نَسَمَة ﴿مُؤْمِنَة﴾ عَلَيْهِ ﴿ودِيَة مُسَلَّمَة﴾ مُؤَدّاة ﴿إلى أهْله﴾ أيْ ورَثَة المَقْتُول ﴿إلّا أنْ يَصَّدَّقُوا﴾ يَتَصَدَّقُوا عَلَيْهِ بِها بِأَنْ يَعْفُوا عَنْها وبَيَّنَتْ السُّنَّة أنَّها مِائَة مِن الإبِل عِشْرُونَ بِنْت مَخاض وكَذا بَنات لَبُون وبَنُو لَبُون وحِقاق وجِذاع وأَنَّها عَلى عاقِلَة القاتِل وهُمْ عَصَبَته فِي الأَصْل والفَرْع مُوَزَّعَة عَلَيْهِمْ عَلى ثَلاث سِنِينَ عَلى الغَنِيّ مِنهُمْ نِصْف دِينار والمُتَوَسِّط رُبُع كُلّ سَنَة فَإنْ لَمْ يَفُوا فَمِن بَيْت المال فَإنْ تَعَذَّرَ فَعَلى الجانِي ﴿فَإنْ كانَ﴾ المَقْتُول ﴿مِن قَوْم عَدُوّ﴾ حَرْب ﴿لَكُمْ وهُوَ مُؤْمِن فَتَحْرِير رَقَبَة مُؤْمِنَة﴾ عَلى قاتِله كَفّارَة ولا دِيَة تُسَلَّم إلى أهْله لِحِرابَتِهِمْ ﴿وإنْ كانَ﴾ المَقْتُول ﴿مِن قَوْم بَيْنكُمْ وبَيْنهمْ مِيثاق﴾ عَهْد كَأَهْلِ الذِّمَّة ﴿فَدِيَة﴾ لَهُ ﴿مُسَلَّمَة إلى أهْله﴾ وهِيَ ثُلُث دِيَة المُؤْمِن إنْ كانَ يَهُودِيًّا أوْ نَصْرانِيًّا وثُلُثا عُشْرها إنْ كانَ مَجُوسِيًّا ﴿وتَحْرِير رَقَبَة مُؤْمِنَة﴾ عَلى قاتِله ﴿فَمَن لَمْ يَجِد﴾ الرَّقَبَة بِأَنْ فَقَدَها وما يُحَصِّلها بِهِ ﴿فَصِيام شَهْرَيْنِ مُتَتابِعَيْنِ﴾ عَلَيْهِ كَفّارَة ولَمْ يَذْكُر اللَّه تَعالى الِانْتِقال إلى الطَّعام كالظِّهارِ وبِهِ أخَذَ الشّافِعِيّ فِي أصَحّ قَوْلَيْهِ ﴿تَوْبَة مِن اللَّه﴾ مَصْدَر مَنصُوب بِفِعْلِهِ المُقَدَّر ﴿وكانَ اللَّه عَلِيمًا﴾ بِخَلْقِهِ ﴿حَكِيمًا﴾ فِيما دَبَّرَهُ لَهُمْ"],[93,93,"﴿ومَن يَقْتُل مُؤْمِنًا مُتَعَمِّدًا﴾ بِأَنْ يَقْصِد قَتْله بِما يَقْتُل غالِبًا بِإيمانِهِ ﴿فَجَزاؤُهُ جَهَنَّم خالِدًا فِيها وغَضِبَ اللَّه عَلَيْهِ ولَعَنَهُ﴾ أبْعَدَهُ مِن رَحْمَته ﴿وأَعَدَّ لَهُ عَذابًا عَظِيمًا﴾ فِي النّار وهَذا مُؤَوَّل بِمَن يَسْتَحِلّهُ أوْ بِأَنَّ هَذا جَزاؤُهُ إنْ جُوزِيَ ولا بِدْع فِي خَلْف الوَعِيد لِقَوْلِهِ ﴿ويَغْفِر ما دُون ذَلِكَ لِمَن يَشاء﴾ وعَنْ ابْن عَبّاس أنَّها عَلى ظاهِرها وأَنَّها ناسِخَة لِغَيْرِها مِن آيات المَغْفِرَة وبَيَّنَتْ آيَة البَقَرَة أنَّ قاتِل العَمْد يُقْتَل بِهِ وأَنَّ عَلَيْهِ الدِّيَة إنْ عُفِيَ عَنْهُ وسَبَقَ قَدْرها وبَيَّنَتْ السُّنَّة أنَّ بَيْن العَمْد والخَطَأ قَتْلًا يُسَمّى شِبْه العَمْد وهُوَ أنْ يَقْتُلهُ بِما لا يَقْتُل غالِبًا فَلا قِصاص فِيهِ بَلْ دِيَة كالعَمْدِ فِي الصِّفَة والخَطَأ فِي التَّأْجِيل والحَمْل وهُوَ العَمْد أوْلى بِالكَفّارَةِ مِن الخَطَأ"],[94,94,"ونَزَلَ لَمّا مَرَّ نَفَر مِن الصَّحابَة بِرَجُلٍ مِن بَنِي سُلَيْم وهُوَ يَسُوق غَنَمًا فَسَلَّمَ عَلَيْهِمْ فَقالُوا ما سَلَّمَ عَلَيْنا إلّا تَقِيَّة فَقَتَلُوهُ واسْتاقُوا غَنَمه ﴿يا أيّها الَّذِينَ آمَنُوا إذا ضَرَبْتُمْ﴾ سافَرْتُمْ لِلْجِهادِ، ﴿فِي سَبِيل اللَّه فَتَبَيَّنُوا﴾ وفِي قِراءَة فَتَثَبَّتُوا فِي المَوْضِعَيْنِ ﴿ولا تَقُولُوا لِمَن ألْقى إلَيْكُمْ السَّلام﴾ بِأَلِفٍ أوْ دُونها أيْ التَّحِيَّة أوْ الِانْقِياد بِكَلِمَةِ الشَّهادَة الَّتِي هِيَ أمارَة عَلى الإسْلام ﴿لَسْت مُؤْمِنًا﴾ إنّما قُلْت هَذا تَقِيَّة لِنَفْسِك ومالِك فَتَقْتُلُوهُ ﴿تَبْتَغُونَ﴾ تَطْلُبُونَ لِذَلِكَ ﴿عَرَض الحَياة الدُّنْيا﴾ مَتاعها مِن الغَنِيمَة ﴿فَعِنْد اللَّه مَغانِم كَثِيرَة﴾ تُغْنِيكُمْ عَنْ قَتْل مِثْله لِمالِهِ ﴿كَذَلِك كُنْتُمْ مِن قَبْل﴾ تُعْصَم دِماؤُكُمْ وأَمْوالكُمْ بِمُجَرَّدِ قَوْلكُمْ الشَّهادَة ﴿فَمَنَّ اللَّه عَلَيْكُمْ﴾ بِالِاشْتِهارِ بِالإيمانِ والِاسْتِقامَة ﴿فَتَبَيَّنُوا﴾ أنْ تَقْتُلُوا مُؤْمِنًا وافْعَلُوا بِالدّاخِلِ فِي الإسْلام كَما فُعِلَ بِكُمْ ﴿إنّ اللَّه كانَ بِما تَعْمَلُونَ خَبِيرًا﴾ فَيُجازِيكُمْ بِهِ"],[95,95,"﴿لا يَسْتَوِي القاعِدُونَ مِن المُؤْمِنِينَ﴾ عَنْ الجِهاد ﴿غَيْر أُولِي الضَّرَر﴾ بِالرَّفْعِ صِفَة والنَّصْب اسْتِثْناء مِن زَمانَة أوْ عَمًى ونَحْوه ﴿والمُجاهِدُونَ فِي سَبِيل اللَّه بِأَمْوالِهِمْ وأَنْفُسهمْ فَضَّلَ اللَّه المُجاهِدِينَ بِأَمْوالِهِمْ وأَنْفُسهمْ عَلى القاعِدِينَ﴾ لِضَرَرٍ ﴿دَرَجَة﴾ فَضِيلَة لِاسْتِوائِهِما فِي النِّيَّة وزِيادَة المُجاهِدِينَ بِالمُباشَرَةِ ﴿وكُلًّا﴾ مِن الفَرِيقَيْنِ ﴿وعَدَ اللَّه الحُسْنى﴾ الجَنَّة ﴿وفَضَّلَ اللَّه المُجاهِدِينَ عَلى القاعِدِينَ﴾ لِغَيْرِ ضَرَر ﴿أجْرًا عَظِيمًا﴾"],[96,96,"﴿دَرَجات مِنهُ﴾ مَنازِل بَعْضها فَوْق بَعْض مِن الكَرامَة ﴿ومَغْفِرَة ورَحْمَة﴾ مَنصُوبانِ بِفِعْلِهِما المُقَدَّر ﴿وكانَ اللَّه غَفُورًا﴾ لِأَوْلِيائِهِ ﴿رَحِيمًا﴾ بِأَهْلِ طاعَته"],[97,97,"﴿إنّ الَّذِينَ تَوَفّاهُمْ المَلائِكَة ظالِمِي أنْفُسهمْ﴾ بِالمُقامِ مَعَ الكُفّار وتَرْك الهِجْرَة ونَزَلَ فِي جَماعَة أسْلَمُوا ولَمْ يُهاجِرُوا فَقُتِلُوا يَوْم بَدْر مَعَ الكُفّار: ﴿قالُوا﴾ لَهُمْ مُوَبِّخِينَ ﴿فِيمَ كُنْتُمْ﴾ أيْ فِي شَيْء كُنْتُمْ فِي أمْر دِينكُمْ ﴿قالُوا﴾ مُعْتَذِرِينَ ﴿كُنّا مُسْتَضْعَفِينَ﴾ عاجِزِينَ عَنْ إقامَة الدِّين ﴿فِي الأَرْض﴾ أرْض مَكَّة ﴿قالُوا﴾ لَهُمْ تَوْبِيخًا ﴿ألَمْ تَكُنْ أرْض اللَّه واسِعَة فَتُهاجِرُوا فِيها﴾ مِن أرْض الكُفْر إلى بَلَد آخَر كَما فَعَلَ خَيْركُمْ ﴿فَأُولَئِكَ مَأْواهُمْ جَهَنَّم وساءَتْ مَصِيرًا﴾ هِيَ"],[98,98,"﴿إلّا المُسْتَضْعَفِينَ مِن الرِّجال والنِّساء والوِلْدان﴾ الَّذِينَ ﴿لا يَسْتَطِيعُونَ حِيلَة﴾ الَّذِينَ لا قُوَّة لَهُمْ عَلى الهِجْرَة ولا نَفَقَة ﴿ولا يَهْتَدُونَ سَبِيلًا﴾ طَرِيقًا إلى أرْض الهِجْرَة"],[100,100,"﴿ومَن يُهاجِر فِي سَبِيل اللَّه يَجِد فِي الأَرْض مُراغَمًا﴾ مُهاجِرًا ﴿كَثِيرًا وسَعَة﴾ فِي الرِّزْق ﴿ومَن يَخْرُج مِن بَيْته مُهاجِرًا إلى اللَّه ورَسُوله ثُمَّ يُدْرِكهُ المَوْت﴾ فِي الطَّرِيق كَما وقَعَ لجندع بْن ضَمْرَة اللَّيْثِيّ ﴿فَقَدْ وقَعَ﴾ ثَبَتَ"],[101,101,"﴿وإذا ضَرَبْتُمْ﴾ سافَرْتُمْ ﴿فِي الأَرْض فَلَيْسَ عَلَيْكُمْ جُناح﴾ فِي ﴿أنْ تَقْصُرُوا مِن الصَّلاة﴾ بِأَنْ تَرُدُّوها مِن أرْبَع إلى اثْنَتَيْنِ ﴿إنْ خِفْتُمْ أنْ يَفْتِنكُمْ﴾ أيْ يَنالكُمْ بِمَكْرُوهٍ ﴿الَّذِينَ كَفَرُوا﴾ بَيان لِلْواقِعِ إذْ ذاكَ فَلا مَفْهُوم لَهُ وبَيَّنَتْ السُّنَّة أنَّ المُراد بِالسَّفَرِ الطَّوِيل وهُوَ أرْبَع بُرُد وهِيَ مَرْحَلَتانِ. ويُؤْخَذ مِن قَوْله تَعالى: ﴿فَلَيْسَ عَلَيْكُمْ جُناح﴾ أنَّهُ رُخْصَة لا واجِب وعَلَيْهِ الشّافِعِيّ ﴿إنّ الكافِرِينَ كانُوا لَكُمْ عَدُوًّا مُبِينًا﴾ بَيِّنِي العَداوَة"],[102,102,"﴿وإذا كُنْت فِيهِمْ﴾ يا مُحَمَّد حاضِرًا ﴿فِيهِمْ﴾ وأَنْتُمْ تَخافُونَ العَدُوّ ﴿فَأَقَمْت لَهُمْ الصَّلاة﴾ وهَذا جَرْي عَلى عادَة القُرْآن فِي الخِطاب ﴿فَلْتَقُمْ طائِفَة مِنهُمْ مَعَك﴾ وتَتَأَخَّر طائِفَة ﴿ولْيَأْخُذُوا﴾ أيْ الطّائِفَة الَّتِي قامَتْ مَعَك ﴿أسْلِحَتهمْ﴾ مَعَهُمْ ﴿فَإذا سَجَدُوا﴾ أيْ صَلَّوْا ﴿فَلْيَكُونُوا﴾ أيْ الطّائِفَة الأُخْرى ﴿مِن ورائِكُمْ﴾ يَحْرُسُونَ إلى أنْ تَقْضُوا الصَّلاة وتَذْهَب هَذِهِ الطّائِفَة تَحْرُس ﴿ولْتَأْتِ طائِفَة أُخْرى لَمْ يُصَلُّوا فَلْيُصَلُّوا مَعَك ولْيَأْخُذُوا حِذْرهمْ وأَسْلِحَتهمْ﴾ مَعَهُمْ إلى أنْ تَقْضُوا الصَّلاة وقَدْ فَعَلَ النَّبِيّ ﷺ كَذَلِك بِبَطْنِ نَخْل رَواهُ الشَّيْخانِ ﴿ودَّ الَّذِينَ كَفَرُوا لَوْ تَغْفُلُونَ﴾ إذا قُمْتُمْ إلى الصَّلاة ﴿عَنْ أسْلِحَتكُمْ وأَمْتِعَتكُمْ فَيَمِيلُونَ عَلَيْكُمْ مَيْلَة واحِدَة﴾ بِأَنْ يَحْمِلُوا عَلَيْكُمْ فَيَأْخُذُوكُمْ وهَذا عِلَّة الأَمْر بِأَخْذِ السِّلاح ﴿ولا جُناح عَلَيْكُمْ إنْ كانَ بِكُمْ أذًى مِن مَطَر أوْ كُنْتُمْ مَرْضى أنْ تَضَعُوا أسْلِحَتكُمْ﴾ فَلا تَحْمِلُوها وهَذا يُفِيد إيجاب حَمْلها عِنْد عَدَم العُذْر وهُوَ أحَد قَوْلَيْنِ لِلشّافِعِيِّ والثّانِي أنَّهُ سُنَّة ورَجَحَ ﴿وخُذُوا حِذْركُمْ﴾ مِن العَدُوّ أيْ احْتَرِزُوا مِنهُ ما اسْتَطَعْتُمْ ﴿إنّ اللَّه أعَدَّ لِلْكافِرِينَ عَذابًا مُهِينًا﴾ ذا إهانَة"],[103,103,"﴿فَإذا قَضَيْتُمْ الصَّلاة﴾ فَرَغْتُمْ مِنها ﴿فاذْكُرُوا اللَّه﴾ بِالتَّهْلِيلِ والتَّسْبِيح ﴿قِيامًا وقُعُودًا وعَلى جُنُوبكُمْ﴾ مُضْطَجِعِينَ أيْ فِي كُلّ حال ﴿فَإذا اطْمَأْنَنْتُمْ﴾ أمِنتُمْ ﴿فَأَقِيمُوا الصَّلاة﴾ أدُّوها بِحُقُوقِها ﴿إنّ الصَّلاة كانَتْ عَلى المُؤْمِنِينَ كِتابًا﴾ مَكْتُوبًا أيْ مَفْرُوضًا ﴿مَوْقُوتًا﴾ أيْ مُقَدَّرًا وقْتها فَلا تُؤَخَّر عَنْهُ ونَزَلَ لَمّا بَعَثَ ﷺ طائِفَة فِي طَلَب أبِي سُفْيان وأَصْحابه لَمّا رَجَعُوا مِن أُحُد فَشَكَوْا الجِراحات"],[104,104,"﴿ولا تَهِنُوا﴾ تَضْعُفُوا ﴿فِي ابْتِغاء القَوْم﴾ طَلَب الكُفّار لِتُقاتِلُوهُمْ ﴿إنْ تَكُونُوا تَأْلَمُونَ﴾ تَجِدُونَ ألَم الجِراح ﴿فَإنَّهُمْ يَأْلَمُونَ كَما تَأْلَمُونَ﴾ أيْ مِثْلكُمْ ولا يَجْبُنُونَ عَلى قِتالكُمْ ﴿وتَرْجُونَ﴾ أنْتُمْ ﴿مِن اللَّه﴾ مِن النَّصْر والثَّواب عَلَيْهِ ﴿ما لا يَرْجُونَ﴾ هُمْ فَأَنْتُمْ تَزِيدُونَ عَلَيْهِمْ بِذَلِكَ فَيَنْبَغِي أنْ تَكُونُوا أرْغَب مِنهُمْ فِيهِ ﴿وكانَ اللَّه عَلِيمًا﴾ بِكُلِّ شَيْء ﴿حَكِيمًا﴾ فِي صُنْعه"],[105,105,"وسَرَقَ طُعْمَة بْن أُبَيْرِق دِرْعًا وخَبَّأَها عِنْد يَهُودِيّ فَوُجِدَتْ عِنْده فَرَماهُ طُعْمَة بِها وحَلَفَ أنَّهُ ما سَرَقَها فَسَأَلَ قَوْمه النَّبِيّ ﷺ أنْ يُجادِل عَنْهُ ويُبْرِّئهُ فَنَزَلَ ﴿إنّا أنْزَلْنا إلَيْك الكِتاب﴾ القُرْآن ﴿بِالحَقِّ﴾ مُتَعَلِّق بِأَنْزَل ﴿لِتَحْكُم بَيْن النّاس بِما أراك اللَّه﴾ أعْلَمك فِيهِ ﴿ولا تَكُنْ لِلْخائِنِينَ﴾ كَطُعْمَةَ ﴿خَصِيمًا﴾ مُخاصِمًا عَنْهُمْ"],[106,106,"﴿واسْتَغْفِرْ اللَّه﴾ مِمّا هَمَمْت بِهِ"],[107,107,"﴿ولا تُجادِل عَنْ الَّذِينَ يَخْتانُونَ أنْفُسهمْ﴾ يَخُونُونَها بِالمَعاصِي لِأَنَّ وبال خِيانَتهمْ عَلَيْهِمْ ﴿إنّ اللَّه لا يُحِبّ مَن كانَ خَوّانًا﴾ كَثِير الخِيانَة ﴿أثِيمًا﴾ أيْ يُعاقِبهُ"],[108,108,"﴿يَسْتَخْفُونَ﴾ أيْ طُعْمَة وقَوْمه حَياء ﴿مِن النّاس ولا يَسْتَخْفُونَ مِن اللَّه وهُوَ مَعَهُمْ﴾ بِعِلْمِهِ ﴿إذْ يُبَيِّتُونَ﴾ يُضْمِرُونَ ﴿ما لا يَرْضى مِن القَوْل﴾ مِن عَزْمهمْ عَلى الحَلِف عَلى نَفْي السَّرِقَة ورَمْي اليَهُودِيّ بِها ﴿وكانَ اللَّه بِما يَعْمَلُونَ مُحِيطًا﴾ عِلْمًا"],[109,109,"﴿ها أنْتُمْ﴾ يا ﴿هَؤُلاءِ﴾ خِطاب لِقَوْمِ طُعْمَةٍ ﴿جادَلْتُمْ﴾ خاصَمْتُمْ ﴿عَنْهُمْ﴾ أيْ عَنْ طُعْمَة وذَوِيهِ وقُرِئَ عَنْهُ ﴿فِي الحَياة الدُّنْيا فَمَن يُجادِل اللَّه عَنْهُمْ يَوْم القِيامَة﴾ إذا عَذَّبَهُمْ ﴿أمْ مَن يَكُون عَلَيْهِمْ وكِيلًا﴾ يَتَوَلّى أمْرهمْ ويَذُبّ عَنْهُمْ أيْ لا أحَد يَفْعَل ذَلِكَ"],[110,110,"﴿ومَن يَعْمَل سُوءًا﴾ ذَنْبًا يَسُوء بِهِ غَيْره كَرَمْيِ طُعْمَة اليَهُودِيّ ﴿أوْ يَظْلِم نَفْسه﴾ يَعْمَل ذَنْبًا قاصِرًا عَلَيْهِ ﴿ثُمَّ يَسْتَغْفِر اللَّه﴾ مِنهُ أيْ يَتُبْ ﴿يَجِد اللَّه غَفُورًا﴾ لَهُ ﴿رَحِيمًا﴾ بِهِ"],[111,111,"﴿ومَن يَكْسِب إثْمًا﴾ ذَنْبًا ﴿فَإنَّما يَكْسِبهُ عَلى نَفْسه﴾ لِأَنَّ وباله عَلَيْها ولا يَضُرّ غَيْره ﴿وكانَ اللَّه عَلِيمًا حَكِيمًا﴾ فِي صُنْعه"],[112,112,"﴿ومَن يَكْسِب خَطِيئَة﴾ ذَنْبًا صَغِيرًا ﴿أوْ إثْمًا﴾ ذَنْبًا كَبِيرًا ﴿ثُمَّ يَرْمِ بِهِ بَرِيئًا﴾ مِنهُ ﴿فَقَدْ احْتَمَلَ﴾ تَحَمَّلَ ﴿بُهْتانًا﴾ بِرَمْيِهِ ﴿وإثْمًا مُبِينًا﴾ بَيِّنًا يَكْسِبهُ"],[113,113,"﴿ولَوْلا فَضْل اللَّه عَلَيْك﴾ يا مُحَمَّد ﴿ورَحْمَته﴾ بِالعِصْمَةِ ﴿لَهَمَّتْ﴾ أضْمَرَتْ ﴿طائِفَة مِنهُمْ﴾ مِن قَوْم طُعْمَة ﴿أنْ يُضِلُّوك﴾ عَنْ القَضاء بِالحَقِّ بِتَلْبِيسِهِمْ عَلَيْك ﴿وما يُضِلُّونَ إلّا أنْفُسهمْ وما يَضُرُّونَك مِن﴾ زائِدَة ﴿شَيْء﴾ لِأَنَّ وبال إضْلالهمْ عَلَيْهِمْ ﴿وأَنْزَلَ اللَّه عَلَيْك الكِتاب﴾ القُرْآن ﴿والحِكْمَة﴾ ما فِيهِ مِن الأَحْكام ﴿وعَلَّمَك ما لَمْ تَكُنْ تَعْلَم﴾ مِن الأَحْكام والغَيْب ﴿وكانَ فَضْل اللَّه عَلَيْك﴾ بِذَلِكَ وغَيْره"],[114,114,"﴿لا خَيْر فِي كَثِير مِن نَجْواهُمْ﴾ أيْ النّاس أيْ ما يَتَناجَوْنَ فِيهِ ويَتَحَدَّثُونَ ﴿إلّا﴾ نَجْوى ﴿مَن أمَرَ بِصَدَقَةٍ أوْ مَعْرُوف﴾ عَمَل بِرّ ﴿أوْ إصْلاح بَيْن النّاس ومَن يَفْعَل ذَلِكَ﴾ المَذْكُور ﴿ابْتِغاء﴾ طَلَب ﴿مَرْضاة اللَّه﴾ لا غَيْره مِن أُمُور الدُّنْيا. ﴿فَسَوْفَ نُؤْتِيه﴾ بِالنُّونِ والياء أيْ اللَّه"],[115,115,"﴿ومَن يُشاقِقْ﴾ يُخالِف ﴿الرَّسُول﴾ فِيما جاءَ بِهِ مِن الحَقّ ﴿مِن بَعْد ما تَبَيَّنَ لَهُ الهُدى﴾ ظَهَرَ لَهُ الحَقّ بِالمُعْجِزاتِ ﴿ويَتَّبِع﴾ طَرِيقًا ﴿غَيْر سَبِيل المُؤْمِنِينَ﴾ أيْ طَرِيقهمْ الَّذِي هُمْ عَلَيْهِ مِن الدِّين بِأَنْ يَكْفُر ﴿نُوَلِّهِ ما تَوَلّى﴾ نَجْعَلهُ والِيًا لِما تَوَلّاهُ مِن الضَّلال بِأَنْ نُخَلِّي بَيْنه وبَيْنه فِي الدُّنْيا ﴿ونُصْلِهِ﴾ نُدْخِلهُ فِي الآخِرَة ﴿جَهَنَّم﴾ فَيَحْتَرِق فِيها ﴿وساءَتْ مَصِيرًا﴾ مَرْجِعًا هِيَ"],[116,116,"﴿إنّ اللَّه لا يَغْفِر أنْ يُشْرَك بِهِ ويَغْفِر ما دُون ذَلِكَ لِمَن يَشاء ومَن يُشْرِك بِاللَّهِ فَقَدْ ضَلَّ ضَلالًا بَعِيدًا﴾ عَنْ الحَقّ"],[117,117,"﴿إنْ﴾ ما ﴿يَدْعُونَ﴾ يَعْبُد المُشْرِكُونَ ﴿مِن دُونه﴾ أيْ اللَّه أيْ غَيْره ﴿إلّا إناثًا﴾ أصْنامًا مُؤَنَّثَة كاللّاتِي والعُزّى ومَناة ﴿وإنْ﴾ ما ﴿يَدْعُونَ﴾ يَعْبُدُونَ بِعِبادَتِها ﴿إلّا شَيْطانًا مَرِيدًا﴾ خارِجًا عَنْ الطّاعَة لِطاعَتِهِمْ لَهُ فِيها وهُوَ إبْلِيس"],[118,118,"﴿لَعَنَهُ اللَّه﴾ أبْعَده عَنْ رَحْمَته ﴿وقالَ﴾ أيْ الشَّيْطان ﴿لَأَتَّخِذَن﴾ لَأَجْعَلَن لِي ﴿مِن عِبادك نَصِيبًا﴾ حَظًّا ﴿مَفْرُوضًا﴾ مَقْطُوعًا أدْعُوهُمْ إلى طاعَتِي"],[119,119,"﴿ولَأُضِلَّنهُمْ﴾ عَنْ الحَقّ بِالوَسْوَسَةِ ﴿ولَأُمَنِّيَنّهم﴾ أُلْقِي فِي قُلُوبهمْ طُول الحَياة وأَنْ لا بَعْث ولا حِساب ﴿ولَآمُرَنهُمْ فَلَيُبَتِّكُنَّ﴾ يُقَطِّعُنَّ ﴿آذان الأَنْعام﴾ وقَدْ فَعَلَ ذَلِكَ بِالبَحائِرِ ﴿ولَآمُرَنهُمْ فَلَيُغَيِّرُنَّ خَلْق اللَّه﴾ دِينه بِالكُفْرِ وإحْلال ما حَرَّمَ اللَّه وتَحْرِيم ما أحَلَّ ﴿ومَن يَتَّخِذ الشَّيْطان ولِيًّا﴾ يَتَوَلّاهُ يُطِيعهُ ﴿مِن دُون اللَّه﴾ أيْ غَيْره ﴿فَقَدْ خَسِرَ خُسْرانًا مُبِينًا﴾ بَيِّنًا لِمَصِيرِهِ إلى النّار المُؤَبَّدَة عَلَيْهِ"],[120,120,"﴿يَعِدهُمْ﴾ طُول العُمُر ﴿ويُمَنِّيهِمْ﴾ نَيْل الآمال فِي الدُّنْيا وأَنْ لا بَعْث ولا جَزاء ﴿وما يَعِدهُمْ الشَّيْطان﴾ بِذَلِكَ ﴿إلّا غُرُورًا﴾ باطِلًا"],[121,121,"﴿أُولَئِكَ مَأْواهُمْ جَهَنَّم ولا يَجِدُونَ عَنْها مَحِيصًا﴾ مَعْدِلًا"],[122,122,"﴿والَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات سَنُدْخِلُهُمْ جَنّات تَجْرِي مِن تَحْتها الأَنْهار خالِدِينَ فِيها أبَدًا وعْد اللَّه حَقًّا﴾ أيْ وعَدَهُمْ اللَّه ذَلِكَ وحَقّه حَقًّا ﴿ومَن﴾ أيْ لا أحَد ﴿أصْدَق مِن اللَّه قِيلًا﴾ أيْ قَوْلًا"],[123,123,"ونَزَلَ لَمّا افْتَخَرَ المُسْلِمُونَ وأَهْل الكِتاب ﴿لَيْسَ﴾ الأَمْر مَناطًا ﴿بِأَمانِيِّكُمْ ولا أمانِيّ أهْل الكِتاب﴾ بَلْ بِالعَمَلِ الصّالِح ﴿مَن يَعْمَل سُوءًا يُجْزَ بِهِ﴾ إمّا فِي الآخِرَة أوْ فِي الدُّنْيا بِالبَلاءِ والمِحَن كَما ورَدَ فِي الحَدِيث ﴿ولا يَجِد لَهُ مِن دُون اللَّه﴾ أيْ غَيْره ﴿ولِيًّا﴾ يَحْفَظهُ ﴿ولا نَصِيرًا﴾ يَمْنَعهُ مِنهُ"],[124,124,"﴿ومَن يَعْمَل﴾ شَيْئًا ﴿مِن الصّالِحات مِن ذَكَر أوْ أُنْثى وهُوَ مُؤْمِن فَأُولَئِكَ يَدْخُلُونَ﴾ بِالبِناءِ لِلْمَفْعُولِ والفاعِل ﴿الجَنَّة ولا يُظْلَمُونَ نَقِيرًا﴾ قَدْر نَقْرَة النَّواة"],[125,125,"﴿ومَن﴾ أيْ لا أحَد ﴿أحْسَن دِينًا مِمَّنْ أسْلَمَ وجْهه﴾ أيْ انْقادَ وأَخْلَصَ عَمَله ﴿لِلَّهِ وهُوَ مُحْسِن﴾ مُوَحِّد ﴿واتَّبَعَ مِلَّة إبْراهِيم﴾ المُوافِقَة لِمِلَّةِ الإسْلام ﴿حَنِيفًا﴾ حال أيْ مائِلًا عَنْ الأَدْيان كُلّها إلى الدِّين القَيِّم ﴿واِتَّخَذَ اللَّه إبْراهِيم خَلِيلًا﴾ صَفِيًّا خالِص المَحَبَّة لَهُ"],[126,126,"﴿ولِلَّهِ ما فِي السَّماوات وما فِي الأَرْض﴾ مُلْكًا وخَلْقًا وعَبِيدًا ﴿وكانَ اللَّه بِكُلِّ شَيْء مُحِيطًا﴾ عِلْمًا وقُدْرَة أيْ لَمْ يَزَلْ مُتَّصِفًا بِذَلِكَ"],[127,127,"﴿ويَسْتَفْتُونَك﴾ يَطْلُبُونَ مِنك الفَتْوى ﴿فِي﴾ شَأْن ﴿النِّساء﴾ ومِيراثهنَّ ﴿قُلْ﴾ لَهُمْ ﴿اللَّه يُفْتِيكُمْ فِيهِنَّ وما يُتْلى عَلَيْكُمْ فِي الكِتاب﴾ القُرْآن مِن آيَة المِيراث ويُفْتِيكُمْ أيْضًا ﴿فِي يَتامى النِّساء اللّاتِي لا تُؤْتُونَهُنَّ ما كُتِبَ﴾ فُرِضَ ﴿لَهُنَّ﴾ مِن المِيراث ﴿وتَرْغَبُونَ﴾ أيّها الأَوْلِياء عَنْ ﴿أنْ تَنْكِحُوهُنَّ﴾ لِدَمامَتِهِنَّ وتَعْضُلُوهُنَّ أنْ يَتَزَوَّجْنَ طَمَعًا فِي مِيراثهنَّ أيْ يُفْتِيكُمْ أنْ لا تَفْعَلُوا ذَلِكَ ﴿و﴾ فِي ﴿المُسْتَضْعَفِينَ﴾ الصِّغار ﴿مِن الوِلْدان﴾ أنْ تُعْطُوهُمْ حُقُوقهمْ ﴿وأَنْ﴾ يَأْمُركُمْ ﴿تَقُومُوا لِلْيَتامى بِالقِسْطِ﴾ بِالعَدْلِ فِي المِيراث والمَهْر ﴿وما تَفْعَلُوا مِن خَيْر فَإنَّ اللَّه كانَ بِهِ عَلِيمًا﴾ فَيُجازِيكُمْ بِهِ"],[128,128,"﴿وإنْ امْرَأَة﴾ مَرْفُوع بِفِعْلٍ يُفَسِّرهُ ﴿خافَتْ﴾ تَوَقَّعَتْ ﴿مِن بَعْلها﴾ زَوْجها ﴿نُشُوزًا﴾ تَرَفُّعًا عَلَيْها بِتَرْكِ مُضاجَعَتها والتَّقْصِير فِي نَفَقَتها لِبُغْضِها وطُمُوح عَيْنه إلى أجْمَل مِنها ﴿أوْ إعْراضًا﴾ عَنْها بِوَجْهِهِ ﴿فَلا جُناح عَلَيْهِما أنْ يُصْلِحا﴾ فِيهِ إدْغام التّاء فِي الأَصْل فِي الصّاد وفِي قِراءَة يُصْلِحا مِن: أصْلَحَ ﴿بَيْنهما صُلْحًا﴾ فِي القَسْم والنَّفَقَة بِأَنْ تَتْرُك لَهُ شَيْئًا طَلَبًا لِبَقاءِ الصُّحْبَة فَإنْ رَضِيَتْ بِذَلِكَ وإلّا فَعَلى الزَّوْج أنْ يُوَفِّيها حَقّها أوْ يُفارِقها ﴿والصُّلْح خَيْر﴾ مِن الفُرْقَة والنُّشُوز والإعْراض قالَ تَعالى فِي بَيان ما جُبِلَ عَلَيْهِ الإنْسان ﴿وأُحْضِرَتْ الأَنْفُس الشُّحّ﴾ شِدَّة البُخْل أيْ جُبِلَتْ عَلَيْهِ فَكَأَنَّها حاضِرَته لا تَغِيب عَنْهُ المَعْنى أنَّ المَرْأَة لا تَكاد تَسْمَح بِنَصِيبِها مِن زَوْجها والرَّجُل لا يَكاد يَسْمَح عَلَيْها بِنَفْسِهِ إذا أحَبَّ غَيْرها ﴿وإنْ تُحْسِنُوا﴾ عِشْرَة النِّساء ﴿وتَتَّقُوا﴾ الجَوْر عَلَيْهِنَّ ﴿فَإنَّ اللَّه كانَ بِما تَعْمَلُونَ خَبِيرًا﴾ فَيُجازِيكُمْ بِهِ"],[129,129,"﴿ولَنْ تَسْتَطِيعُوا أنْ تَعْدِلُوا﴾ تُسَوُّوا ﴿بَيْن النِّساء﴾ فِي المَحَبَّة ﴿ولَوْ حَرَصْتُمْ﴾ عَلى ذَلِكَ ﴿فَلا تَمِيلُوا كُلّ المَيْل﴾ إلى الَّتِي تُحِبُّونَها فِي القَسْم والنَّفَقَة ﴿فَتَذَرُوها﴾ أيْ تَتْرُكُوا المُمالَ عَنْها ﴿كالمُعَلَّقَةِ﴾ الَّتِي لا هِيَ أيِّم، ولا هِيَ ذات بَعْل ﴿وإنْ تُصْلِحُوا﴾ بِالعَدْلِ بِالقَسْمِ ﴿وتَتَّقُوا﴾ الجَوْر ﴿فَإنَّ اللَّه كانَ غَفُورًا﴾ لِما فِي قَلْبكُمْ مِن المَيْل ﴿رَحِيمًا﴾ بِكُمْ فِي ذَلِكَ"],[130,130,"﴿وإنْ يَتَفَرَّقا﴾ أيْ الزَّوْجان بِالطَّلاق ﴿يُغْنِ اللَّه كُلًّا﴾ عَنْ صاحِبِهِ ﴿مِن سَعَتِهِ﴾ أيْ فَضْلِهِ بِأَنْ يَرْزُقَها زَوْجًا غَيْرَهُ ويَرْزَقَهُ غَيْرَها ﴿وكانَ اللَّهُ واسِعًا﴾ لِخَلْقِهِ فِي الفَضْلِ ﴿حَكِيمًا﴾ فِيما دَبَّرَ لَهُمْ"],[131,131,"﴿ولِلَّهِ ما فِي السَّماوات وما فِي الأَرْض ولَقَدْ وصَّيْنا الَّذِين أُوتُوا الكِتاب﴾ بِمَعْنى الكُتُب ﴿مِن قَبْلِكُمْ﴾ أيْ اليَهُود والنَّصارى ﴿وإيّاكُم﴾ يا أهْل القُرْآن ﴿أنْ﴾ أيْ بِأَنْ ﴿اتَّقُوا اللَّه﴾ خافُوا عِقابَهُ بِأَنْ تُطِيعُوه ﴿و﴾ قُلْنا لَهُمْ ولَكُمْ ﴿إنْ تَكْفُرُوا﴾ بِما وصَّيْتُمْ بِهِ ﴿فَإنَّ لِلَّهِ ما فِي السَّماواتِ وما فِي الأَرْض﴾ خَلْقًا ومُلْكًا وعَبِيدًا فَلا يَضُرُّه كُفْرُكُمْ ﴿وكانَ اللَّهُ غَنِيًّا﴾ عَنْ خَلْقِهِ وعِبادَتِهِمْ ﴿حَمِيدًا﴾ مَحْمُودًا فِي صُنْعِهِ بِهِمْ"],[132,132,"﴿ولِلَّهِ ما فِي السَّماواتِ وما فِي الأَرْضِ﴾ كَرَّرَهُ تَأْكِيدًا لِتَقْرِيرِ مُوجَب التَّقْوى ﴿وكَفى بِاللَّه وكِيلًا﴾ شَهِيدًا بِأَنَّ ما فِيهِما لَهُ."],[133,133,"﴿إنْ يَشَأْ يُذْهِبْكُمْ﴾ يا ﴿أيُّها النّاسُ ويَأْتِ بِآخَرِينَ﴾ بَدَلَكُم"],[134,134,"﴿مَن كانَ يُرِيد﴾ بِعَمَلِهِ ﴿ثَواب الدُّنْيا فَعِنْدَ اللَّهِ ثَواب الدُّنْيا والآخِرَة﴾ لِمَن أرادَه لا عِنْد غَيْرِهِ فَلَمْ يَطْلُب أحَدكُمْ الأَخَسّ وهَلّا طَلَبَ الأَعْلى بِإخْلاصِهِ لَهُ حَيْثُ كانَ مَطْلَبُهُ لا يُوجَد إلّا عِنْدَه"],[135,135,"﴿ياأَيُّها الَّذِينَ آمَنُوا كُونُوا قَوّامِينَ﴾ قائِمِينَ ﴿بِالقِسْط﴾ بِالعَدْل ﴿شُهَداء﴾ بِالحَقِّ ﴿لِلَّهِ ولَوْ﴾ كانَتْ الشَّهادَةُ ﴿عَلى أنْفُسِكُمْ﴾ فاشْهَدُوا عَلَيْها بِأَنْ تُقِرُّوا بِالحَقِّ ولا تَكْتُمُوهُ ﴿أوْ﴾ عَلى ﴿الوالِدَيْن والأَقْرَبِينَ إنْ يَكُنْ﴾ المَشْهُود عَلَيْهِ ﴿غَنِيًّا أوْ فَقِيرًا فاللَّه أوْلى بِهِما﴾ مِنكُم وأَعْلَم بِمَصالِحِهِما ﴿فَلا تَتَّبِعُوا الهَوى﴾ فِي شَهادَتكُمْ بِأَنْ تُحابُوا الغَنِيّ لِرِضاهُ أوْ الفَقِير رَحْمَة لَهُ ﴿أنْ﴾ لا ﴿تَعْدِلُوا﴾ تَمِيلُوا عَنْ الحَقّ ﴿وإنْ تَلْوُوا﴾ تُحَرِّفُوا الشَّهادَة وفِي قِراءَة بِحَذْفِ الواو الأُولى تَخْفِيفًا ﴿أوْ تُعْرِضُوا﴾ عَنْ أدائِها ﴿فَإنَّ اللَّه كانَ بِما تَعْمَلُونَ خَبِيرًا﴾ فَيُجازِيكُمْ بِهِ"],[136,136,"﴿يا أيّها الَّذِينَ آمَنُوا آمِنُوا﴾ داوِمُوا عَلى الإيمان ﴿بِاللَّهِ ورَسُوله والكِتاب الَّذِي نَزَّلَ عَلى رَسُوله﴾ مُحَمَّد ﷺ وهُوَ القُرْآن ﴿والكِتاب الَّذِي أنْزَلَ مِن قَبْل﴾ عَلى الرُّسُل بِمَعْنى الكُتُب وفِي قِراءَة بِالبِناءِ لِلْفاعِلِ فِي الفِعْلَيْنِ ﴿ومَن يَكْفُر بِاللَّهِ ومَلائِكَته وكُتُبه ورُسُله واليَوْم الآخِر فَقَدْ ضَلَّ ضَلالًا بَعِيدًا﴾ عَنْ الحَقّ"],[137,137,"﴿إنّ الَّذِينَ آمَنُوا﴾ بِمُوسى وهُمْ اليَهُود ﴿ثُمَّ كَفَرُوا﴾ بِعِبادَتِهِمْ العِجْل ﴿ثُمَّ آمَنُوا﴾ بَعْده ﴿ثُمَّ كَفَرُوا﴾ بِعِيسى ﴿ثُمَّ ازْدادُوا كُفْرًا﴾ بِمُحَمَّدٍ ﴿لَمْ يَكُنْ اللَّه لِيَغْفِر لَهُمْ﴾ ما أقامُوا عَلَيْهِ ﴿ولا لِيَهْدِيَهُمْ سَبِيلًا﴾ طَرِيقًا إلى الحَقّ"],[138,138,"﴿بَشِّرْ﴾ أخْبِرْ يا مُحَمَّد ﴿المُنافِقِينَ بِأَنَّ لَهُمْ عَذابًا ألِيمًا﴾ مُؤْلِمًا هُوَ عَذاب النّار"],[139,139,"﴿الَّذِينَ﴾ بَدَل أوْ نَعْت لِلْمُنافِقِينَ ﴿يَتَّخِذُونَ الكافِرِينَ أوْلِياء مِن دُون المُؤْمِنِينَ﴾ لِما يَتَوَهَّمُونَ فِيهِمْ مِن القُوَّة ﴿أيَبْتَغُونَ﴾ يَطْلُبُونَ ﴿عِنْدهمْ العِزَّة﴾ اسْتِفْهام إنْكار أيْ لا يَجِدُونَ عِنْدهمْ ﴿فَإنَّ العِزَّة لِلَّهِ جَمِيعًا﴾ فِي الدُّنْيا والآخِرَة ولا يَنالها إلّا أوْلِياؤُهُ"],[140,140,"﴿وقَدْ نَزَّلَ﴾ بِالبِناءِ لِلْفاعِلِ والمَفْعُول ﴿عَلَيْكُمْ فِي الكِتاب﴾ القُرْآن فِي سُورَة الأَنْعام ﴿أنْ﴾ مُخَفَّفَة واسْمها مَحْذُوف أيْ أنَّهُ ﴿إذا سَمِعْتُمْ آيات اللَّه﴾ القُرْآن ﴿يُكْفَر بِها ويُسْتَهْزَأ بِها فَلا تَقْعُدُوا مَعَهُمْ﴾ أيْ الكافِرِينَ والمُسْتَهْزِئِين ﴿حَتّى يَخُوضُوا فِي حَدِيث غَيْره إنّكُمْ إذًا﴾ إنْ قَعَدْتُمْ مَعَهُمْ ﴿مِثْلهمْ﴾ فِي الإثْم ﴿إنّ اللَّه جامِع المُنافِقِينَ والكافِرِينَ فِي جَهَنَّم جَمِيعًا﴾ كَما اجْتَمَعُوا فِي الدُّنْيا عَلى الكُفْر والِاسْتِهْزاء"],[141,141,"﴿الَّذِينَ﴾ بَدَل مِن الَّذِينَ قَبْله ﴿يَتَرَبَّصُونَ﴾ يَنْتَظِرُونَ ﴿بِكُمْ﴾ الدَّوائِر ﴿فَإنْ كانَ لَكُمْ فَتْح﴾ ظَفَر وغَنِيمَة ﴿مِن اللَّه قالُوا﴾ لَكُمْ ﴿ألَمْ نَكُنْ مَعَكُمْ﴾ فِي الدِّين والجِهاد فَأَعْطُونا مِن الغَنِيمَة ﴿وإنْ كانَ لِلْكافِرِينَ نَصِيب﴾ مِن الظَّفَر عَلَيْكُمْ ﴿قالُوا﴾ لَهُمْ ﴿ألَمْ نَسْتَحْوِذ﴾ نَسْتَوْلِ ﴿عَلَيْكُمْ﴾ ونَقْدِر عَلى أخْذكُمْ وقَتْلكُمْ فَأَبْقَيْنا عَلَيْكُمْ ﴿و﴾ ألَمْ ﴿نَمْنَعكُمْ مِن المُؤْمِنِينَ﴾ أنْ يَظْفَر بِتَخْذِيلِهِمْ ومُراسَلَتهمْ بِأَخْبارِهِمْ فَلَنا عَلَيْكُمْ المِنَّة ﴿فاللّه يَحْكُم بَيْنكُمْ﴾ وبَيْنهمْ ﴿يَوْم القِيامَة﴾ بِأَنْ يُدْخِل ويُدْخِلهُمْ النّار ﴿ولَنْ يَجْعَل اللَّه لِلْكافِرِينَ عَلى المُؤْمِنِينَ سَبِيلًا﴾ طَرِيقًا بِالِاسْتِئْصالِ"],[142,142,"﴿إنّ المُنافِقِينَ يُخادِعُونَ اللَّه﴾ بِإظْهارِ خِلاف ما أبْطَنُوهُ مِن الكُفْر لِيَدْفَعُوا عَنْهُمْ أحْكامه الدُّنْيَوِيَّة ﴿وهُوَ خادِعهمْ﴾ مُجازِيهمْ عَلى خِداعهمْ فَيُفْتَضَحُونَ فِي الدُّنْيا بِإطْلاعِ اللَّه نَبِيّه عَلى ما أبْطَنُوهُ ويُعاقَبُونَ فِي الآخِرَة ﴿وإذا قامُوا إلى الصَّلاة﴾ مَعَ المُؤْمِنِينَ ﴿قامُوا كُسالى﴾ مُتَثاقِلِينَ ﴿يُراءُونَ النّاس﴾ بِصَلاتِهِمْ ﴿ولا يَذْكُرُونَ اللَّه﴾ يُصَلُّونَ ﴿إلّا قَلِيلًا﴾ رِياء"],[143,143,"﴿مُذَبْذَبِينَ﴾ مُتَرَدِّدِينَ ﴿بَيْن ذَلِكَ﴾ الكُفْر والإيمان ﴿لا﴾ مَنسُوبِينَ ﴿إلى هَؤُلاءِ﴾ أيْ الكُفّار ﴿ولا إلى هَؤُلاءِ﴾ أيْ المُؤْمِنِينَ ﴿ومَن يُضْلِلْ﴾ ومَن يُضْلِلْهُ ﴿اللَّه فَلَنْ تَجِد لَهُ سَبِيلًا﴾ طَرِيقًا إلى الهُدى"],[144,144,"﴿يا أيّها الَّذِينَ آمَنُوا لا تَتَّخِذُوا الكافِرِينَ أوْلِياء مِن دُون المُؤْمِنِينَ أتُرِيدُونَ أنْ تَجْعَلُوا لِلَّهِ عَلَيْكُمْ﴾ بِمُوالاتِهِمْ ﴿سُلْطانًا مُبِينًا﴾ بُرْهانًا بَيِّنًا عَلى نِفاقكُمْ"],[145,145,"﴿إنّ المُنافِقِينَ فِي الدَّرْك﴾ المَكان ﴿الأَسْفَل مِن النّار﴾ وهُوَ قَعْرها ﴿ولَنْ تَجِد لَهُمْ نَصِيرًا﴾ مانِعًا مِن العَذاب"],[146,146,"﴿إلّا الَّذِينَ تابُوا﴾ مِن النِّفاق ﴿وأَصْلَحُوا﴾ عَمَلهمْ ﴿واعْتَصَمُوا﴾ وثِقُوا ﴿بِاللَّهِ وأَخْلَصُوا دِينهمْ لِلَّهِ﴾ مِن الرِّياء ﴿فَأُولَئِكَ مَعَ المُؤْمِنِينَ﴾ فِيما يُؤْتَوْنَهُ ﴿وسَوْف يُؤْتِ اللَّه المُؤْمِنِينَ أجْرًا عَظِيمًا﴾ فِي الآخِرَة وهُوَ الجَنَّة"],[147,147,"﴿ما يَفْعَل اللَّه بِعَذابِكُمْ إنْ شَكَرْتُمْ﴾ نِعَمه ﴿وآمَنتُمْ﴾ بِهِ والِاسْتِفْهام بِمَعْنى النَّفْي أيْ لا يُعَذِّبكُمْ ﴿وكانَ اللَّه شاكِرًا﴾ لِأَعْمالِ المُؤْمِنِينَ بِالإثابَةِ ﴿عَلِيمًا﴾ بِخَلْقِهِ"],[148,148,"﴿لا يُحِبّ اللَّه الجَهْر بِالسُّوءِ مِن القَوْل﴾ مِن أحَد أيْ يُعاقِبهُ عَلَيْهِ ﴿إلّا مَن ظُلِمَ﴾ فَلا يُؤاخِذهُ بِالجَهْرِ بِهِ بِأَنْ يُخْبِر عَنْ ظُلْم ظالِمه ويَدْعُو عَلَيْهِ ﴿وكانَ اللَّه سَمِيعًا﴾ لِما يُقال ﴿عَلِيمًا﴾ بِما يَفْعَل"],[149,149,"﴿إنْ تُبْدُوا﴾ تُظْهِرُوا. ﴿خَيْرًا﴾ مِن أعْمال البِرّ ﴿أوْ تُخْفُوهُ﴾ تَعْمَلُوهُ سِرًّا ﴿أوْ تَعْفُوا عَنْ سُوء﴾ ظُلْم"],[150,150,"﴿إنّ الَّذِينَ يَكْفُرُونَ بِاللَّهِ ورُسُله ويُرِيدُونَ أنْ يُفَرِّقُوا بَيْن اللَّه ورُسُله﴾ بِأَنْ يُؤْمِنُوا بِهِ دُونهمْ ﴿ويَقُولُونَ نُؤْمِن بِبَعْضٍ﴾ مِن الرُّسُل ﴿ونَكْفُر بِبَعْضٍ﴾ مِنهُمْ ﴿ويُرِيدُونَ أنْ يَتَّخِذُوا بَيْن ذَلِكَ﴾ الكُفْر والإيمان ﴿سَبِيلًا﴾ طَرِيقًا يَذْهَبُونَ إلَيْهِ"],[151,151,"﴿أُولَئِكَ هُمْ الكافِرُونَ حَقًّا﴾ مَصْدَر مُؤَكِّد لِمَضْمُونِ الجُمْلَة قَبْله ﴿وأَعْتَدْنا لِلْكافِرِينَ عَذابًا مُهِينًا﴾ ذا إهانَة وهُوَ عَذاب النّار"],[152,152,"﴿والَّذِينَ آمَنُوا بِاللَّهِ ورُسُله﴾ كُلّهمْ ﴿ولَمْ يُفَرِّقُوا بَيْن أحَد مِنهُمْ أُولَئِكَ سَوْفَ يُؤْتِيهِمْ﴾ بِالياءِ والنُّون ﴿أُجُورهمْ﴾ ثَواب أعْمالهمْ ﴿وكانَ اللَّه غَفُورًا﴾ لِأَوْلِيائِهِ ﴿رَحِيمًا﴾ بِأَهْلِ طاعَته"],[153,153,"﴿يَسْأَلك﴾ يا مُحَمَّد ﴿أهْل الكِتاب﴾ اليَهُود ﴿أنْ تُنَزِّل عَلَيْهِمْ كِتابًا مِن السَّماء﴾ جُمْلَة كَما أُنْزِلَ عَلى مُوسى تَعَنُّتًا فَإنْ اسْتَكْبَرْت ذَلِكَ ﴿فَقَدْ سَأَلُوا﴾ أيْ آباؤُهُمْ ﴿مُوسى أكْبَر﴾ أعْظَم ﴿مِن ذَلِكَ فَقالُوا أرِنا اللَّه جَهْرَة﴾ عِيانًا ﴿فَأَخَذَتْهُمْ الصّاعِقَة﴾ المَوْت عِقابًا لَهُمْ ﴿بِظُلْمِهِمْ﴾ حَيْثُ تَعَنَّتُوا فِي السُّؤال ﴿ثُمَّ اتَّخَذُوا العِجْل﴾ إلَهًا ﴿مِن بَعْد ما جاءَتْهُمْ البَيِّنات﴾ المُعْجِزات عَلى وحْدانِيَّة اللَّه ﴿فَعَفَوْنا عَنْ ذَلِكَ﴾ ولَمْ نَسْتَأْصِلهُمْ ﴿وآتِينا مُوسى سُلْطانًا مُبِينًا﴾ تَسَلُّطًا بَيِّنًا ظاهِرًا عَلَيْهِمْ حَيْثُ أمَرَهُمْ بِقَتْلِ أنْفُسهمْ تَوْبَة فَأَطاعُوهُ"],[154,154,"﴿ورَفَعْنا فَوْقهمْ الطُّور﴾ الجَبَل ﴿بِمِيثاقِهِمْ﴾ بِسَبَبِ أخْذ المِيثاق عَلَيْهِمْ لِيَخافُوا فَقَبِلُوهُ ﴿وقُلْنا لَهُمْ﴾ وهُوَ مُظِلّ عَلَيْهِمْ ﴿اُدْخُلُوا الباب﴾ باب القَرْيَة ﴿سُجَّدًا﴾ سُجُود انْحِناء ﴿وقُلْنا لَهُمْ لا تَعْدُوا﴾ وفِي قِراءَة بِفَتْحِ العَيْن وتَشْدِيد الدّال وفِيهِ إدْغام التّاء فِي الأَصْل فِي الدّال أيْ لا تَعْتَدُوا ﴿فِي السَّبْت﴾ بِاصْطِيادِ الحِيتان فِيهِ ﴿وأَخَذْنا مِنهُمْ مِيثاقًا غَلِيظًا﴾ عَلى ذَلِكَ فَنَقَضُوهُ"],[155,155,"﴿فَبِما نَقْضِهِمْ﴾ ما زائِدَة والباء لِلسَّبَبِيَّةِ مُتَعَلِّقَة بِمَحْذُوفٍ أيْ لَعَنّاهُمْ بِسَبَبِ نَقْضِهِمْ ﴿مِيثاقهمْ وكُفْرهمْ بِآياتِ اللَّه وقَتْلهمْ الأَنْبِياء بِغَيْرِ حَقّ وقَوْلهمْ﴾ لِلنَّبِيِّ ﷺ ﴿قُلُوبنا غُلْف﴾ لا تَعِي كَلامك ﴿بَلْ طَبَعَ﴾ خَتَمَ ﴿اللَّه عَلَيْها بِكُفْرِهِمْ﴾ فَلا تَعِي وعْظًا ﴿فَلا يُؤْمِنُونَ إلّا قَلِيلًا﴾ مِنهُمْ كَعَبْدِ اللَّه بْن سَلام وأَصْحابه"],[156,156,"﴿وبِكُفْرِهِمْ﴾ ثانِيًا بِعِيسى وكَرَّرَ الباء لِلْفَصْلِ بَيْنه وبَيْن ما عُطِفَ عَلَيْهِ ﴿وقَوْلهمْ عَلى مَرْيَم بُهْتانًا عَظِيمًا﴾ حَيْثُ رَمَوْها بِالزِّنا"],[157,157,"﴿وقَوْلهمْ﴾ مُفْتَخِرِينَ ﴿إنّا قَتَلْنا المَسِيح عِيسى ابْن مَرْيَم رَسُول اللَّه﴾ فِي زَعْمهمْ أيْ بِمَجْمُوعِ ذَلِكَ عَذَّبْناهُمْ قالَ. تَعالى تَكْذِيبًا لَهُمْ فِي قَتْله ﴿وما قَتَلُوهُ وما صَلَبُوهُ ولَكِنْ شُبِّهَ لَهُمْ﴾ المَقْتُول والمَصْلُوب وهُوَ صاحِبهمْ بِعِيسى أيْ ألْقى اللَّه عَلَيْهِ شَبَهه فَظَنُّوهُ إيّاهُ ﴿وإنَّ الَّذِينَ اخْتَلَفُوا فِيهِ﴾ أيْ فِي عِيسى ﴿لَفِي شَكّ مِنهُ﴾ مِن قَتْله حَيْثُ قالَ بَعْضهمْ لَمّا رَأَوْا المَقْتُول الوَجْه وجْه عِيسى والجَسَد لَيْسَ بِجَسَدِهِ فَلَيْسَ بِهِ وقالَ آخَرُونَ: بَلْ هُوَ هُوَ ﴿ما لَهُمْ بِهِ﴾ بِقَتْلِهِ ﴿مِن عِلْم إلّا اتِّباع الظَّنّ﴾ اسْتِثْناء مُنْقَطِع أيْ لَكِنْ يَتَّبِعُونَ فِيهِ الظَّنّ الَّذِي تَخَيَّلُوهُ ﴿وما قَتَلُوهُ يَقِينًا﴾ حال مُؤَكِّدَة لِنَفْيِ القَتْل"],[158,158,"﴿بَلْ رَفَعَهُ اللَّه إلَيْهِ وكانَ اللَّه عَزِيزًا﴾ فِي مُلْكه ﴿حَكِيمًا﴾ فِي صُنْعه"],[159,159,"﴿وإنَّ﴾ ما ﴿مِن أهْل الكِتاب﴾ أحَد ﴿إلّا لَيُؤْمِنَن بِهِ﴾ بِعِيسى ﴿قَبْل مَوْته﴾ أيْ الكِتابِيّ حِين يُعايِن مَلائِكَة المَوْت فَلا يَنْفَعهُ إيمانه أوْ قَبْل مَوْت عِيسى لَمّا يَنْزِل قُرْب السّاعَة كَما ورَدَ فِي حَدِيث ﴿ويَوْم القِيامَة يَكُون﴾ عِيسى ﴿عَلَيْهِمْ شَهِيدًا﴾ بِما فَعَلُوهُ لَمّا بُعِثَ إلَيْهِمْ"],[160,160,"﴿فَبِظُلْمٍ﴾ أيْ فَبِسَبَبِ ظُلْم ﴿مِن الَّذِينَ هادُوا﴾ هُمْ اليَهُود ﴿حَرَّمْنا عَلَيْهِمْ طَيِّبات أُحِلَّتْ لَهُمْ﴾ هِيَ الَّتِي فِي قَوْله تَعالى: ﴿حَرَّمْنا كُلّ ذِي ظُفُر﴾ الآيَة ﴿وبِصَدِّهِمْ﴾ النّاس ﴿عَنْ سَبِيل اللَّه﴾ دِينه صَدًّا"],[161,161,"﴿وأَخْذهمْ الرِّبا وقَدْ نُهُوا عَنْهُ﴾ فِي التَّوْراة ﴿وأَكْلهمْ أمْوال النّاس بِالباطِلِ﴾ بِالرِّشا فِي الحُكْم ﴿وأَعْتَدْنا لِلْكافِرِينَ مِنهُمْ عَذابًا ألِيمًا﴾ مُؤْلِمًا"],[162,162,"﴿لَكِنْ الرّاسِخُونَ﴾ الثّابِتُونَ ﴿فِي العِلْم مِنهُمْ﴾ كَعَبْدِ اللَّه بْن سَلام ﴿والمُؤْمِنُونَ﴾ المُهاجِرُونَ والأَنْصار ﴿يُؤْمِنُونَ بِما أُنْزِلَ إلَيْك وما أُنْزِلَ مِن قَبْلك﴾ مِن الكُتُب ﴿والمُقِيمِينَ الصَّلاة﴾ نُصِبَ عَلى المَدْح وقُرِئَ بِالرَّفْعِ ﴿والمُؤْتُونَ الزَّكاة والمُؤْمِنُونَ بِاللَّهِ واليَوْم الآخِر أُولَئِكَ سَنُؤْتِيهِمْ﴾ بِالنُّونِ والياء ﴿أجْرًا عَظِيمًا﴾ هُوَ الجَنَّة"],[163,163,"﴿إنّا أوْحَيْنا إلَيْك كَما أوْحَيْنا إلى نُوح والنَّبِيِّينَ مِن بَعْده و﴾ كَما ﴿أوْحَيْنا إلى إبْراهِيم وإسْماعِيل وإسْحاق﴾ ابْنَيْهِ ﴿ويَعْقُوب﴾ ابْن إسْحاق ﴿والأَسْباط﴾ أوْلاده ﴿وسُلَيْمان وآتَيْنا﴾ أباهُ ﴿داوُد زَبُورًا﴾ بِالفَتْحِ اسْم لِلْكِتابِ المُؤْتى والضَّمّ مَصْدَر بِمَعْنى مَزْبُورًا أيْ مَكْتُوبًا"],[164,164,"﴿و﴾ أرْسَلْنا ﴿رُسُلًا قَدْ قَصَصْناهُمْ عَلَيْك مِن قَبْل ورُسُلًا لَمْ نَقْصُصْهُمْ عَلَيْك﴾ رُوِيَ أنَّهُ تَعالى بَعَثَ ثَمانِيَة آلاف نَبِيّ أرْبَعَة آلاف مِن إسْرائِيل وأَرْبَعَة آلاف مِن سائِر النّاس قالَهُ الشَّيْخ فِي سُورَة غافِر ﴿وكَلَّمَ اللَّه مُوسى﴾ بِلا واسِطَة"],[165,165,"﴿رُسُلًا﴾ بَدَل مِن رُسُلًا قَبْله ﴿مُبَشِّرِينَ﴾ بِالثَّوابِ مَن آمَنَ ﴿ومُنْذِرِينَ﴾ بِالعِقابِ مَن كَفَرَ أرْسَلْناهُمْ ﴿لِئَلّا يَكُون لِلنّاسِ عَلى اللَّه حُجَّة﴾ تُقال ﴿بَعْد﴾ إرْسال ﴿الرُّسُل﴾ إلَيْهِمْ فَيَقُولُوا: رَبّنا لَوْلا أرْسَلْت إلَيْنا رَسُولًا فَنَتَّبِع آياتك ونَكُون مِن المُؤْمِنِينَ فَبَعَثْناهُمْ لِقَطْعِ عُذْرهمْ ﴿وكانَ اللَّه عَزِيزًا﴾ فِي مُلْكه ﴿حَكِيمًا﴾ فِي صُنْعه"],[166,166,"ونَزَلَ لَمّا سُئِلَ اليَهُود عَنْ نُبُوَّته ﷺ فَأَنْكَرُوهُ ﴿لَكِنَّ اللَّه يَشْهَد﴾ يُبَيِّن نُبُوَّتك ﴿بِما أُنْزِلَ إلَيْك﴾ مِن القُرْآن المُعْجِز ﴿أنْزَلَهُ﴾ مُلْتَبِسًا ﴿بِعِلْمِهِ﴾ أيْ عالِمًا بِهِ أوْ فِيهِ عِلْمه ﴿والمَلائِكَة يَشْهَدُونَ﴾ لَك أيْضًا ﴿وكَفى بِاللَّهِ شَهِيدًا﴾ عَلى ذَلِكَ"],[167,167,"﴿إنّ الَّذِينَ كَفَرُوا﴾ بِاللَّهِ ﴿وصَدُّوا﴾ النّاس ﴿عَنْ سَبِيل اللَّه﴾ دِين الإسْلام بِكَتْمِهِمْ نَعْت مُحَمَّد ﷺ وهُمْ اليَهُود ﴿قَدْ ضَلُّوا ضَلالًا بَعِيدًا﴾ عَنْ الحَقّ"],[168,168,"﴿إنّ الَّذِينَ كَفَرُوا﴾ بِاللَّهِ ﴿وظَلَمُوا﴾ نَبِيّه بِكِتْمانِ نَعْته ﴿لَمْ يَكُنْ اللَّه لِيَغْفِر لَهُمْ ولا لِيَهْدِيَهُمْ طَرِيقًا﴾ مِن الطُّرُق"],[169,169,"﴿إلّا طَرِيق جَهَنَّم﴾ أيْ الطَّرِيق المُؤَدِّي إلَيْها ﴿خالِدِينَ﴾ مُقَدَّرِينَ الخُلُود ﴿فِيها﴾ إذا دَخَلُوها ﴿أبَدًا وكانَ ذَلِكَ عَلى اللَّه يَسِيرًا﴾ هَيِّنًا"],[170,170,"﴿يا أيّها النّاس﴾ أيْ أهْل مَكَّة ﴿قَدْ جاءَكُمْ الرَّسُول﴾ مُحَمَّد ﷺ ﴿بِالحَقِّ مِن رَبّكُمْ فَآمِنُوا﴾ بِهِ واقْصِدُوا ﴿خَيْرًا لَكُمْ﴾ مِمّا أنْتُمْ فِيهِ ﴿وإنْ تَكْفُرُوا﴾ بِهِ ﴿فَإنَّ لِلَّهِ ما فِي السَّماوات والأَرْض﴾ مُلْكًا وخَلْقًا وعَبِيدًا فَلا يَضُرّهُ كُفْركُمْ ﴿وكانَ اللَّه عَلِيمًا﴾ بِخَلْقِهِ ﴿حَكِيمًا﴾ فِي صُنْعه بِهِمْ"],[171,171,"﴿يا أهْل الكِتاب﴾ الإنْجِيل ﴿لا تَغْلُوا﴾ تَتَجاوَزُوا الحَدّ ﴿فِي دِينكُمْ ولا تَقُولُوا عَلى اللَّه إلّا﴾ القَوْل ﴿الحَقّ﴾ مِن تَنْزِيهه عَنْ الشَّرِيك والوَلَد ﴿إنّما المَسِيح عِيسى ابْن مَرْيَم رَسُول اللَّه وكَلِمَته ألْقاها﴾ أوْصَلَها اللَّه ﴿إلى مَرْيَم ورُوح﴾ أيْ ذُو رُوح ﴿مِنهُ﴾ أُضِيفَ إلَيْهِ تَعالى تَشْرِيفًا لَهُ ولَيْسَ كَما زَعَمْتُمْ ابْن اللَّه أوْ إلَهًا مَعَهُ أوْ ثالِث ثَلاثَة لِأَنَّ ذا الرُّوح مُرَكَّب والإلَه مُنَزَّه عَنْ التَّرْكِيب وعَنْ نِسْبَة المُرَكَّب إلَيْهِ ﴿فَآمِنُوا بِاللَّهِ ورُسُله ولا تَقُولُوا﴾ الآلِهَة ﴿ثَلاثَة﴾ اللَّه وعِيسى وأُمّه ﴿انْتَهُوا﴾ عَنْ ذَلِكَ وأْتُوا ﴿خَيْرًا لَكُمْ﴾ مِنهُ وهُوَ التَّوْحِيد ﴿إنّما اللَّه إلَه واحِد سُبْحانه﴾ تَنْزِيهًا لَهُ عَنْ ﴿أنْ يَكُون لَهُ ولَد لَهُ ما فِي السَّماوات وما فِي الأَرْض﴾ خَلْقًا ومُلْكًا وعَبِيدًا والمَلَكِيَّة تُنافِي النُّبُوَّة ﴿وكَفى بِاللَّهِ وكِيلًا﴾ شَهِيدًا عَلى ذَلِكَ"],[172,172,"﴿لَنْ يَسْتَنْكِف﴾ يَتَكَبَّر ويَأْنَف ﴿المَسِيح﴾ الَّذِي زَعَمْتُمْ أنَّهُ إلَه عَنْ ﴿أنْ يَكُون عَبْدًا لِلَّهِ ولا المَلائِكَة المُقَرَّبُونَ﴾ عِنْد اللَّه لا يَسْتَنْكِفُونَ أنْ يَكُونُوا عَبِيدًا وهَذا مِن أحْسَن الِاسْتِطْراد ذُكِرَ لِلرَّدِّ عَلى مَن زَعَمَ أنَّها آلِهَة أوْ بَنات اللَّه كَما رَدَّ بِما قَبْله عَلى النَّصارى الزّاعِمِينَ ذَلِكَ المَقْصُود خِطابهمْ ﴿ومَن يَسْتَنْكِف عَنْ عِبادَته ويَسْتَكْبِر فَسَيَحْشُرُهُمْ إلَيْهِ جَمِيعًا﴾ فِي الآخِرَة"],[173,173,"﴿فَأَمّا الَّذِينَ آمَنُوا وعَمِلُوا الصّالِحات فَيُوَفِّيهِمْ أُجُورهمْ﴾ ثَواب أعْمالهمْ ﴿ويَزِيدهُمْ مِن فَضْله﴾ ما لا عَيْن رَأَتْ ولا أُذُن سَمِعَتْ ولا خَطَرَ عَلى قَلْب بَشَر ﴿وأَمّا الَّذِينَ اسْتَنْكَفُوا واسْتَكْبَرُوا﴾ عَنْ عِبادَته ﴿فَيُعَذِّبهُمْ عَذابًا ألِيمًا﴾ مُؤْلِمًا هُوَ عَذاب النّار ﴿ولا يَجِدُونَ لَهُمْ مِن دُون اللَّه﴾ أيْ غَيْره ﴿ولِيًّا﴾ يَدْفَعهُ عَنْهُمْ ﴿ولا نَصِيرًا﴾ يَمْنَعهُمْ مِنهُ"],[174,174,"﴿يا أيّها النّاس قَدْ جاءَكُمْ بُرْهان﴾ حُجَّة ﴿مِن رَبّكُمْ﴾ عَلَيْكُمْ وهُوَ النَّبِيّ ﷺ ﴿وأَنْزَلْنا إلَيْكُمْ نُورًا مُبِينًا﴾ بَيِّنًا وهُوَ القُرْآن"],[175,175,"﴿فَأَمّا الَّذِينَ آمَنُوا بِاللَّهِ واعْتَصَمُوا بِهِ فَسَيُدْخِلُهُمْ فِي رَحْمَة مِنهُ وفَضْل ويَهْدِيهِمْ إلَيْهِ صِراطًا﴾ طَرِيقًا ﴿مُسْتَقِيمًا﴾ هُوَ دَيِن الإسْلام"],[176,176,"﴿يَسْتَفْتُونَك﴾ فِي الكَلالَة ﴿قُلْ اللَّه يُفْتِيكُمْ فِي الكَلالَة إنْ امْرُؤٌ﴾ مَرْفُوع بِفِعْلٍ يُفَسِّرهُ ﴿هَلَكَ﴾ ماتَ ﴿لَيْسَ لَهُ ولَد﴾ أيْ ولا والِد وهُوَ الكَلالَة ﴿ولَهُ أُخْت﴾ مِن أبَوَيْنِ أوْ أب ﴿فَلَها نِصْف ما تَرَكَ وهُوَ﴾ أيْ الأَخ كَذَلِكَ ﴿يَرِثها﴾ جَمِيع ما تَرَكَتْ ﴿إنْ لَمْ يَكُنْ لَها ولَد﴾ فَإنْ كانَ لَها ولَد ذَكَر فَلا شَيْء لَهُ أوْ أُنْثى فَلَهُ ما فَضَلَ مِن نَصِيبها ولَوْ كانَتْ الأُخْت أوْ الأَخ مِن أُمّ فَفَرْضه السُّدُس كَما تَقَدَّمَ أوَّل السُّورَة ﴿فَإنْ كانَتا﴾ أيْ الأُخْتانِ ﴿اثْنَتَيْنِ﴾ أيْ فَصاعِدًا لِأَنَّها نَزَلَتْ فِي جابِر وقَدْ ماتَ عَنْ أخَوات ﴿فَلَهُما الثُّلُثانِ مِمّا تَرَكَ﴾ الأَخ ﴿وإنْ كانُوا﴾ أيْ الوَرَثَة ﴿إخْوَة رِجالًا ونِساء فَلِلذَّكَرِ﴾ مِنهُمْ ﴿مِثْل حَظّ الأُنْثَيَيْنِ يُبَيِّن اللَّه لَكُمْ﴾ شَرائِع دِينكُمْ ﴿أنْ﴾ لا ﴿تَضِلُّوا واللَّه بِكُلِّ شَيْء عَلِيم﴾ ومِنهُ المِيراث رَوى الشَّيْخانِ عَنْ البَراء أنَّها آخِر آيَة نَزَلَتْ أيْ مِن الفَرائِض."]]};
